local config = {
  ui_story_5046_50460101_1_dialog_content = "PlayerName!",
  ui_story_5046_50460101_2_dialog_content = "움브라톤 고아원 준공식에 참석해 주겠다고 해서 정말 고마워요!",
  ui_story_5046_50460101_3_dialog_content = "오랜만이야, 베델.",
  ui_story_5046_50460101_4_dialog_content = "딱히 섀도우마스터 명의로 초대한 게 아니었어도 준공식엔 참석했을 거야.",
  ui_story_5046_50460101_5_dialog_content = "우리도 이젠 친구 사이잖아!",
  ui_story_5046_50460101_6_dialog_content = "그나저나 청첩장이 너무 호화로워서 놀랐지 뭐야.",
  ui_story_5046_50460101_7_dialog_content = "당연히 정식으로 초대장을 보내야죠.\n친한 사이라고 해서 예법에 소홀해선 안 되니까요!",
  ui_story_5046_50460101_8_dialog_content = "게다가 이번에 초대한 손님 중엔 백야성의 귀족도 많아요.\n그 사람들은 다들 예법을 중요시하니까요.",
  ui_story_5046_50460101_9_dialog_content = "만약 섀도우마스터가 당신에게 초대장을 보내지 않았고,\n그걸 저들이 알게 된다면 또 무슨 오해가 펼쳐질지 몰라요.",
