  ui_story_5046_50460101_17_dialog_content = "남에게 비방을 받으면 엄격하게 상대해야 해요.\n안 그러면 당신의 명예를 크게 실추시킬 거예요.",
  ui_story_5046_50460101_18_dialog_content = "모든 사람이 유언비어를 멀리할 수 있는 것도 아니고,\n상대를 실제로 만나서 알아갈 수 있지도 않으니까요.",
