  ui_story_5046_50460101_31_dialog_content = "PlayerName 당신도 같이 봐 주세요. 그럼 당일의 절차도 알 수 있을 테니까요.",
  ui_story_5046_50460101_32_dialog_content = "응, 그럴게!",
  ui_story_5046_50460101_33_dialog_content = "자, 그럼 따라오세요.",
  ui_story_5046_50460101_34_dialog_content = "<color=#e8d9bb>움브라톤 고아원 준공식 리허설 현장</color>",
  ui_story_5046_50460101_35_dialog_content = "베델 양, 현장의 경비 배치는 이미 준비를 마쳤습니다.",
  ui_story_5046_50460101_36_dialog_content = "알겠어요, 고생했어요.",
  ui_story_5046_50460101_37_dialog_content = "PlayerName, 제가 소개해 줄게요.",
  ui_story_5046_50460101_38_dialog_content = "이쪽은 리허설 장소의 경비를 담당하고 있는 경비대장 제나스 씨라고 해요.",
  ui_story_5046_50460101_39_dialog_content = "말씀은 많이 들었습니다. 만나 뵙게 되어 영광입니다.",
