  ui_story_5046_50460101_41_dialog_content = "(복장부터가 백야성 사람이네... 게다가 신분이 높은 사람 같아.)",
  ui_story_5046_50460101_42_dialog_content = "(근데 이런 사람이 왜 경비 일을 하고 있는 거지?)",
  ui_story_5046_50460101_43_dialog_content = "그리고 이쪽은 백야성 심판소의 견습 심판관 크리스틴 씨예요.\n제나스 씨의 일을 돕고 있죠.",
