  ui_story_5046_50460101_45_dialog_content = "이리돈 대심판관님과 선배님들이 당신 이야기를 자주 하셨어요.\n용기와 지혜를 가진 분이라고 말이에요.",
  ui_story_5046_50460101_46_dialog_content = "아하하... 그거 왠지 쑥스럽네.",
  ui_story_5046_50460101_47_dialog_content = "하멜 씨!",
  ui_story_5046_50460101_48_dialog_content = "베델 양!",
  ui_story_5046_50460101_49_dialog_content = "하멜 씨, 오늘은 리허설일 뿐인데도 이렇게 현장까지 와주셨군요.",
  ui_story_5046_50460101_50_dialog_content = "집에 있어도 시간을 주체할 수 없어서 말이지요.\n구경이라도 할까 해서 나와 봤습니다.",
  ui_story_5046_50460101_51_dialog_content = "고아원 재건에 협조해 주신 섀도우마스터와 베델 양에겐 정말 감사드립니다.",
  ui_story_5046_50460101_52_dialog_content = "큰 화재로 소실된 고아원을 재건하는 훌륭한 사업을 도와주셨으니,\n아이들을 대신해서 제가 감사의 말씀을 드려야 마땅하지요.",
  ui_story_5046_50460101_53_dialog_content = "말씀 나눈다고 소개해 드리는 걸 잊었네요. 이쪽은 아이테르 PlayerName입니다.",
  ui_story_5046_50460101_54_dialog_content = "PlayerName, 이쪽은 새 고아원의 원장을 맡아 주실 하멜 씨예요.\n움브라톤에서 유명한 골동품 상인이시죠.",
  ui_story_5046_50460101_55_dialog_content = "신문에서 본 것보다 훨씬 젊군요. 참으로 재능 있는 청년이 아닙니까.",
  ui_story_5046_50460101_56_dialog_content = "콜로서스로 아스트라 대륙 곳곳을 여행하고 있고,\n저 유명한 공중상회와도 협력 관계라 들었습니다.",
  ui_story_5046_50460101_57_dialog_content = "정말 보기 드문 인재로군요!",
  ui_story_5046_50460101_58_dialog_content = "아... 전부 다른 사람들의 도움 덕분이었어요.",
  ui_story_5046_50460101_59_dialog_content = "아니, 그렇지 않습니다. 인맥도 사업의 중요한 요소 중 하나니까요!",
  ui_story_5046_50460101_60_dialog_content = "그만한 인맥을 갖는 건 결코 쉽지 않은 일이지요!",
  ui_story_5046_50460101_61_dialog_content = "당신 같은 젊은이를 만나다니, 정말 오래 산 보람이 있군요...",
  ui_story_5046_50460101_62_dialog_content = "과, 과찬이세요... 전 그저 평범한 사람인데요...",
  ui_story_5046_50460101_63_dialog_content = "그나저나 전부터 아이테르는 무척 부유하다고 들었습니다만.",
  ui_story_5046_50460101_64_dialog_content = "하아? 누가... 그러는데요?",
  ui_story_5046_50460101_65_dialog_content = "그렇게 큰 콜로서스를 타고 다니려면 상당한 유지비가 필요하겠죠.",
  ui_story_5046_50460101_66_dialog_content = "그거야 그렇긴 하지만, 그렇다고 그게 제가 돈이 많다는 뜻은 아닌데요...",
  ui_story_5046_50460101_67_dialog_content = "참으로 겸손한 젊은이로군요!",
  ui_story_5046_50460101_68_dialog_content = "당신처럼 인맥도 넓으면서 겸손한 부자는 이 아스트라 대륙에서도 매우 드물 겁니다.",
  ui_story_5046_50460101_69_dialog_content = "게다가 선량하기까지!",
  ui_story_5046_50460101_70_dialog_content = "혹시 앞으로 고아원에 장기적으로 기부하실 생각은 없습니까?",
  ui_story_5046_50460101_71_dialog_content = "으엑...",
  ui_story_5046_50460101_72_dialog_content = "크흠.",
  ui_story_5046_50460101_73_dialog_content = "하멜 씨, 손님을 곤란하게 하지 마세요.",
  ui_story_5046_50460101_74_dialog_content = "장기적인 협력 관계는 쌍방의 신뢰를 바탕으로 성립하는 것이니까요.",
  ui_story_5046_50460101_75_dialog_content = "아, 그럼요. 그렇지요...",
  ui_story_5046_50460101_76_dialog_content = "제가 너무 성급했습니다.",
  ui_story_5046_50460101_77_dialog_content = "아니요, 괜찮아요. 아이들을 생각하는 하멜 씨 마음은 이해할 수 있거든요.",
  ui_story_5046_50460101_78_dialog_content = "어쨌든 오늘은 리허설일 뿐이니까, 일단 서로 인사부터 해둔 걸로 해요.",
  ui_story_5046_50460101_79_dialog_content = "협력 관계에 대해서는 앞으로 천천히 이야기를 나눠보도록 하세요.",
  ui_story_5046_50460101_80_dialog_content = "알겠습니다.",
  ui_story_5046_50460101_81_dialog_content = "그럼 여러분, 먼저 이야기 좀 나누고 계세요.\n전 당일 행사 절차를 좀 확인하고 올게요.",
  ui_story_5046_50460101_82_dialog_content = "먼저 실례하겠습니다.",
  ui_story_5046_50460101_83_dialog_content = "베델은 참 바쁘네.",
  ui_story_5046_50460101_84_dialog_content = "참, 궁금한 게 있는데요...",
  ui_story_5046_50460101_85_option_content = "왜 백야성 분이 움브라톤의 경비 일을 하시는 거죠?",
  ui_story_5046_50460101_86_dialog_content = "보시다시피 이번 행사엔 백야성의 고위 귀족들도 다수 초청되었습니다.",
  ui_story_5046_50460101_87_dialog_content = "그분들은 움브라톤의 용병을 믿지 않습니다.\n그래서 백야성 사람들을 경비로 보내라고 요구했던 겁니다.",
  ui_story_5046_50460101_88_dialog_content = "게다가 최근 움브라톤에선 방화 사건이 빈번하게 발생하고 있어서\n귀족들도 더 신중해질 수밖에 없었을 겁니다.",
  ui_story_5046_50460101_89_dialog_content = "때문에 백야성에선 절 파견했고, 견습 심판관인 크리스틴 아가씨까지\n함께 보내서 질서 유지를 책임지도록 했지요.",
  ui_story_5046_50460101_90_dialog_content = "방화 사건? 그러고 보니까 움브라톤에 도착했을 때 현상 수배 벽보를 본 것 같아요.",
  ui_story_5046_50460101_91_dialog_content = "주변에 사람들이 많아서 뭐라 적혀 있는지는 못 봤지만요...",
  ui_story_5046_50460101_92_dialog_content = "무척 세심한 분이시군요. 마침 저도 그 현상 수배령을 가지고 있으니 한번 보시죠.",
  ui_story_5046_50460101_93_dialog_content = "“현상 수배령.”",
  ui_story_5046_50460101_94_dialog_content = "“본 용의자는 움브라톤 내 다수의 방화 사건을 저지른 혐의가 있으며,\n이로 인해 세 명이 숨지고, 다수의 부상자가 발생했습니다.”",
  ui_story_5046_50460101_95_dialog_content = "“용의자에 대한 단서를 제공해 주시는 분께는 현상금 200,000 나이티움을 드립니다.”",
  ui_story_5046_50460101_96_dialog_content = "“용의자는 체격이 좋고 움직임이 민첩하며, 힘이 세고 야수처럼 잔혹하며 사납습니다.”",
  ui_story_5046_50460101_97_dialog_content = "“용의자의 코드네임은 「검은 흉성」입니다.”",
  ui_story_5046_50460101_98_dialog_content = "20만 나이티움?! 그렇게 많이요?! 제가 용의자를 잡을 수 있었으면 좋겠는데요...",
  ui_story_5046_50460101_99_dialog_content = "근데 「검은 흉성」이라니, 정말 무서운 이름이네요.\n역시 위험한 일엔 나서지 않는 게 좋겠죠...",
  ui_story_5046_50460101_100_dialog_content = "게다가 현상 수배령의 몽타주가 너무 흐릿해서 별로 도움이 안 되는 것 같아요...",
  ui_story_5046_50460101_101_dialog_content = "유감스럽게도 아직까진 용의자의 모습을 명확하게 본 사람이 없습니다.",
  ui_story_5046_50460101_102_dialog_content = "다만 첫 번째 화재 때 현장을 떠나는 야수 같은 그림자를 봤다는\n움브라톤 주민들의 증언이 있었습니다.",
  ui_story_5046_50460101_103_dialog_content = "따라서 범인은 아인족 혈통일 가능성이 높습니다.",
  ui_story_5046_50460101_104_dialog_content = "몽타주를 닮은 수상한 사람을 보게 되시면,\n제일 먼저 저 또는 제나스 대장에게 알려 주세요.",
  ui_story_5046_50460101_105_dialog_content = "하지만 용의자는 무척 난폭하기 때문에, 현상금을 노리고 정면으로 나서진 마세요.\n무엇보다 중요한 건 자신의 안전이니까요.",
  ui_story_5046_50460101_106_dialog_content = "아, 알겠어...",
  ui_story_5046_50460101_107_dialog_content = "더 궁금하신 점이 있으십니까?",
  ui_story_5046_50460101_108_option_content = "원래 있던 고아원도 불이 났던 건가요?",
  ui_story_5046_50460101_109_dialog_content = "맞습니다. 옛 고아원 건물은 몇 년 전 실화로 인한 화재로 전소됐었지요.\n다행히 아이들은 모두 무사했지만요.",
  ui_story_5046_50460101_110_dialog_content = "섀도우마스터는 갈 곳을 잃은 아이들을 불쌍히 여겨 자신의 저택에 살게 해주셨습니다.",
  ui_story_5046_50460101_111_dialog_content = "그 이후로 몇 년 동안 계속 신세를 지고 있었지요.",
  ui_story_5046_50460101_112_dialog_content = "하지만 언제까지나 저택에 살게 할 순 없는 노릇 아닙니까.\n게다가 밖엔 아직 거리를 떠도는 아이들이 많이 있습니다.",
  ui_story_5046_50460101_113_dialog_content = "최근 몇 년간 저도 골동품 장사로 돈을 조금 모았습니다.\n그래서 전 고아원을 재건하고 아이들을 거두어 주려고 생각했습니다.",
  ui_story_5046_50460101_114_dialog_content = "그러면 부모 없는 아이들도 친구들과 마음씨 좋은 어른들\n사이에서 자랄 수 있을 테니 말이지요.",
  ui_story_5046_50460101_115_dialog_content = "하멜 씨는 참 대단하시네요. 정말 마음씨가 좋은 분이셨군요.",
  ui_story_5046_50460101_116_dialog_content = "정말 숭고한 선행이십니다. 하멜 씨.",
  ui_story_5046_50460101_117_dialog_content = "그저 힘닿는 데까지 아이들을 위해 제가 할 수 있는 일을 할 뿐입니다.",
  ui_story_5046_50460101_118_dialog_content = "부디 새 고아원이 아무 일 없이 순조롭게 준공되었으면 좋겠군요.",
  ui_story_5046_50460101_119_dialog_content = "더 궁금하신 점이 있으십니까?",
  ui_story_5046_50460101_120_option_content = "이제 없어요.",
  ui_story_5046_50460101_121_dialog_content = "시간이 늦었어요, 선생님. 이제 리허설 전까지 순찰을 해야 해요.",
  ui_story_5046_50460101_122_dialog_content = "아, 미안! 내가 일을 방해해 버렸네...",
  ui_story_5046_50460101_123_dialog_content = "천만의 말씀입니다. 귀빈들의 안전을 지키는 것은 저희의 직무입니다.",
  ui_story_5046_50460101_124_dialog_content = "<color=#e8d9bb>딸그락──</color>",
  ui_story_5046_50460101_125_dialog_content = "어? 제나스 씨, 뭘 떨어트렸는데요?",
  ui_story_5046_50460101_126_dialog_content = "(예쁜 펜던트네. 멋진 말 문양도 있잖아.)",
  ui_story_5046_50460101_127_dialog_content = "여기요.",
  ui_story_5046_50460101_128_dialog_content = "감사합니다.",
  ui_story_5046_50460101_129_dialog_content = "자, 시간이 없으니 그럼 순찰을 계속하도록 하죠, 아가씨.",
  ui_story_5046_50460101_130_dialog_content = "네, 선생님──",
  ui_story_5046_50460101_131_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5046_50460101_132_dialog_content = "무슨 일이죠?!",
  ui_story_5046_50460101_133_dialog_content = "불이야! 불이 났다!",
  ui_story_5046_50460101_134_dialog_content = "갑자기 왜 불이 난 거죠?!",
  ui_story_5046_50460101_135_dialog_content = "「검은 흉성」의 짓이 분명해!",
  ui_story_5046_50460101_136_dialog_content = "그 잔인하고 흉악하다는 「검은 흉성」이 나타났다고?!",
  ui_story_5046_50460101_137_dialog_content = "여러분, 진정하십시오. 아무래도 고아원 쪽에서 불이 시작된 것 같군요.",
  ui_story_5046_50460101_138_dialog_content = "아가씨, 보러 가 봅시다.",
  ui_story_5046_50460101_139_dialog_content = "알겠어요, 선생님!",
  ui_story_5046_50460101_140_dialog_content = "<color=#e8d9bb>근처</color>",
  ui_story_5046_50460101_141_dialog_content = "......",
  ui_story_5046_50460201_1_dialog_content = "PlayerName 씨, 하멜 씨.",
  ui_story_5046_50460201_2_dialog_content = "두 분은 이쪽에 계십시오. 이제 곧 백야성 경비병이 와서 보호해 드릴 겁니다.",
  ui_story_5046_50460201_3_dialog_content = "저도 갈게요! 사람 찾는 일이라면 제 감응 능력을 쓰는 게 제일 빨라요!",
  ui_story_5046_50460201_4_dialog_content = "왜 갑자기 불이 난 건지 저도 좀 확인해 봐야겠습니다!",
  ui_story_5046_50460201_5_dialog_content = "알겠습니다. 시간이 없으니 두 분은 절 바짝 따라오십시오.\n제가 최선을 다해 두 분을 지켜드리겠습니다!",
  ui_story_5046_50460201_6_dialog_content = "콜록콜록! 연기가 짙어서 아무것도 안 보여요... 일단 불을 빨리 꺼야겠어요...",
  ui_story_5046_50460201_7_dialog_content = "소용돌이치는 격류여!",
  ui_story_5046_50460201_8_dialog_content = "잠깐만요, 크리스틴!",
  ui_story_5046_50460201_9_dialog_content = "<color=#e8d9bb>콰아앙!!!</color>",
  ui_story_5046_50460201_10_dialog_content = "위험합니다!",
  ui_story_5046_50460201_11_dialog_content = "앗! 선생님?!",
  ui_story_5046_50460201_12_dialog_content = "콜록... 전 괜찮습니다.",
  ui_story_5046_50460201_13_dialog_content = "저 불은 지면의 연료를 따라 번지고 있습니다.\n연료가 물 위에 떠서 계속 타오를 테니, 물로는 끌 수 없습니다.",
  ui_story_5046_50460201_14_dialog_content = "죄송해요. 또 선생님한테 상처를...",
  ui_story_5046_50460201_15_dialog_content = "지금은 그런 이야기를 할 시간이 없습니다.",
  ui_story_5046_50460201_16_dialog_content = "PlayerName 씨, 감응 능력으로 안에 갇힌 사람이 있는지,\n아니면 「검은 흉성」의 흔적이 있는지 확인해 주실 수 있겠습니까?",
  ui_story_5046_50460201_17_dialog_content = "알겠어요!",
  ui_story_5046_50460201_18_option_content = "(강제 감응!)",
  ui_story_5046_50460201_19_dialog_content = "훌쩍... 도와줘...",
  ui_story_5046_50460201_20_dialog_content = "불 속에 아이가 있어요! 이쪽일 거예요!",
  ui_story_5046_50460201_21_dialog_content = "......",
  ui_story_5046_50460201_22_dialog_content = "어머니...",
  ui_story_5046_50460201_23_dialog_content = "콜록, 콜록콜록! 목이... 아파...",
  ui_story_5046_50460201_24_dialog_content = "더는 못 버틸 것 같아요! 빨리 구해야 해요!",
  ui_story_5046_50460201_25_dialog_content = "연기가 너무 짙어서 PlayerName 씨가 안 보여요!",
  ui_story_5046_50460201_26_dialog_content = "안 됩니다! 불길이 너무 셉니다!",
  ui_story_5046_50460201_27_dialog_content = "꼬마야, 무서워하지 마. 내가 구하러 왔어!",
  ui_story_5046_50460201_28_dialog_content = "콜록, 콜록! 여, 여기야!",
  ui_story_5046_50460201_29_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5046_50460201_30_dialog_content = "이런! 불이 더 세졌어! 곧 무너질 것 같아!",
  ui_story_5046_50460201_31_dialog_content = "출구를 찾아야 해... 근데 연기가 너무 짙어서 아무것도 안 보여!",
  ui_story_5046_50460201_32_dialog_content = "흐아앙... 무서워...",
  ui_story_5046_50460201_33_dialog_content = "괜찮아... 분명히 나갈 수 있을 거야!",
  ui_story_5046_50460201_34_dialog_content = "<color=#e8d9bb>쿠르릉──!</color>",
  ui_story_5046_50460201_35_dialog_content = "무너진다!",
  ui_story_5046_50460201_36_dialog_content = "꺄아아아악!",
  ui_story_5046_50460201_37_dialog_content = "눈 떠. 아직 죽은 거 아니니까.",
  ui_story_5046_50460201_38_dialog_content = "누...구...?",
  ui_story_5046_50460201_39_dialog_content = "아직 살아있으니까 얼른 일어나서 밖으로 나가.",
  ui_story_5046_50460201_40_dialog_content = "커다란 강아지다! 콜록, 콜록콜록!",
  ui_story_5046_50460201_41_dialog_content = "강아지가 우릴 구해줬어!",
  ui_story_5046_50460201_42_dialog_content = "나, 남자?",
  ui_story_5046_50460201_43_dialog_content = "아니야... 외모는 남자애 느낌이 있지만... 여자애인 모양이네...",
  ui_story_5046_50460201_44_dialog_content = "강아지! 콜록, 콜록! 강아지야! 복슬복슬하고 귀여운 강아지!",
  ui_story_5046_50460201_45_dialog_content = "뭐, 뭔가... 콜록! 동화책 속에서 사람을 구해주는...",
  ui_story_5046_50460201_46_dialog_content = "말수는 적지만 마음씨는 착한... 콜록! 강아지 같아!",
  ui_story_5046_50460201_47_dialog_content = "언제까지 떠들 생각이지? 타죽고 싶은 거라면 난 이만 가겠어.",
  ui_story_5046_50460201_48_dialog_content = "너, 넌 불 속에서 왜 아무렇지도 않아?",
  ui_story_5046_50460201_49_dialog_content = "이 정도 불씨 따윈 날 해칠 수 없어.",
  ui_story_5046_50460201_50_dialog_content = "자, 잠깐만! 왠지 어디서 본 것 같은데...",
  ui_story_5046_50460201_51_dialog_content = "아! 서, 서서서서설마... 「검은 흉성」?!",
  ui_story_5046_50460201_52_dialog_content = "「검은 흉성」? 사람 잘못 봤어.",
  ui_story_5046_50460201_53_dialog_content = "내 이름은 하티다.",
  ui_story_5046_50460201_54_dialog_content = "그리고 그렇게 무서워할 거면, 내 손을 잡지 마라.",
  ui_story_5046_50460201_55_dialog_content = "PlayerName 씨! 어디 계십니까?",
  ui_story_5046_50460201_56_dialog_content = "콜록, 콜록콜록! 사람들을 데려와서 바깥의 불은 거의 다 껐습니다!",
  ui_story_5046_50460201_57_dialog_content = "PlayerName 씨 옆에 누가 한 명 더 있는 것 같은데요?",
  ui_story_5046_50460201_58_dialog_content = "저 모습... 설마 「검은 흉성」?!",
  ui_story_5046_50460201_59_dialog_content = "「검은 흉성」이라고?!",
  ui_story_5046_50460201_60_dialog_content = "연쇄 방화 용의자 「검은 흉성」! 즉시 인질을 석방하라!",
  ui_story_5046_50460201_61_dialog_content = "말했잖아. 난 「검은 흉성」 같은 게 아니라고. 난 하티다.",
  ui_story_5046_50460201_62_dialog_content = "그리고 「인질」이라니, 무슨 뜻이지?",
  ui_story_5046_50460201_63_dialog_content = "PlayerName 씨를 놓아준다면 어떤 조건이든 협상할 수 있다!",
  ui_story_5046_50460201_64_dialog_content = "조건 협상? 물물교환을 하자는 건가?",
  ui_story_5046_50460201_65_dialog_content = "그럼 네가 저 녀석들에게 아주 중요한 사람인 모양이지? PlayerName?",
  ui_story_5046_50460201_66_dialog_content = "그, 그래... 내가 인질이 될 테니까 여자애는 풀어줘...",
  ui_story_5046_50460201_67_dialog_content = "「검은 흉성」! 경거망동하지 마라!",
  ui_story_5046_50460201_68_dialog_content = "쳇... 시끄러워!",
  ui_story_5046_50460201_69_dialog_content = "강아지... 무서워...",
  ui_story_5046_50460201_70_dialog_content = "으아아──!",
  ui_story_5046_50460201_71_dialog_content = "「검은 흉성」이 PlayerName 씨를 인질로 잡은 건가요?!",
  ui_story_5046_50460201_72_dialog_content = "한 발짝만 더 다가오면 이 녀석, 죽여버린다.",
  ui_story_5046_50460201_73_dialog_content = "이 녀석이 너희들한테 그렇게 중요하다면, 내가 좀 빌려야겠어.",
  ui_story_5046_50460201_74_dialog_content = "나, 날 어디로 데려가려는 거야?! 이거 놔!",
  ui_story_5046_50460201_75_dialog_content = "사, 살려줘!",
  ui_story_5046_50460201_76_dialog_content = "경비병! 막으세요!",
  ui_story_5046_50460201_77_dialog_content = "「검은 흉성」이 PlayerName 씨를 데리고 도망치려 합니다! 놓치면 안 됩니다!",
  ui_story_5046_50460202_1_dialog_content = "경비병들이 「검은 흉성」을 놓쳤어요.",
  ui_story_5046_50460202_2_dialog_content = "죄송해요, 선생님...",
  ui_story_5046_50460202_3_dialog_content = "자신을 탓할 필요는 없습니다.\n불 속에선 불꽃을 조종하는 「검은 흉성」이 절대적으로 유리할 테니까요.",
  ui_story_5046_50460202_4_dialog_content = "게다가 저자는 다른 오로리안들보다 움직임이 월등히 민첩합니다.",
  ui_story_5046_50460202_5_dialog_content = "그러니 놓칠지도 모른다고 이미 예상했습니다.",
  ui_story_5046_50460202_6_dialog_content = "준비해주신 긴급 대피 계획이 도움이 되었어요.",
  ui_story_5046_50460202_7_dialog_content = "현장은 혼란스러웠지만, 내빈분들은 조금 놀라기만 했을 뿐,\n모두 무사히 화재 현장을 떠날 수 있었어요.",
  ui_story_5046_50460202_8_dialog_content = "다만... 어째서 PlayerName 씨가 「검은 흉성」에게 인질로 잡힌 건지...\n설명해 주실 수 있을까요?",
  ui_story_5046_50460202_9_dialog_content = "죄송합니다. 모두 저희의 실책입니다.",
  ui_story_5046_50460202_10_dialog_content = "아니에요, PlayerName 씨는 저 때문에...",
  ui_story_5046_50460202_11_dialog_content = "베델 아가씨, 용의자의 신분을 파악했습니다.",
  ui_story_5046_50460202_12_dialog_content = "알겠어요, 고마워요.",
  ui_story_5046_50460202_13_dialog_content = "「하티, 여성, 18세, 출생지 미상.」",
  ui_story_5046_50460202_14_dialog_content = "「한때 움브라톤 고아원에서 살다가 큰 화재를 일으켰고,\n섀도우마스터에 의해 모처의 저택으로 보내짐.」",
  ui_story_5046_50460202_15_dialog_content = "(아버님이...? 설마 이 일도 아버님과 관계가 있는 걸까요...)",
  ui_story_5046_50460202_16_dialog_content = "고아원의 화재라니, 아무래도 상습범인 모양이군요.",
  ui_story_5046_50460202_17_dialog_content = "「2개월 전, 만 18세가 되었고, 평가 결과 문제가 없어 저택을 떠나게 됨.」",
  ui_story_5046_50460202_18_dialog_content = "(역시 이 일은 아버님께 말씀드리는 게 좋을 것 같네요.)",
  ui_story_5046_50460202_19_dialog_content = "방화 전과가 있는 사람을 풀어줬다는 건가요...",
  ui_story_5046_50460202_20_dialog_content = "어쨌든 전 이 일을 섀도우마스터께 보고드려야겠어요.\n움브라톤의 각 세력을 동원해서 PlayerName 씨의 행방을 찾을 거예요.",
  ui_story_5046_50460202_21_dialog_content = "하지만... 그렇게 되면 일이 커지지 않겠습니까...",
  ui_story_5046_50460202_22_dialog_content = "리허설 날 귀빈이 납치됐다... 그런 사실이 세상에 알려지면\n고아원의 명성은 땅에 떨어지고 말 겁니다...",
  ui_story_5046_50460202_23_dialog_content = "지금 PlayerName 씨는 생사조차 알 수 없는 상황이라구요!",
  ui_story_5046_50460202_24_dialog_content = "휴...",
  ui_story_5046_50460202_25_dialog_content = "베델 양, 하멜 씨.",
  ui_story_5046_50460202_26_dialog_content = "두 분께서 절 믿어주실 수 있다면, PlayerName 씨의 납치 사실 공개를\n조금만 늦춰 주셨으면 합니다.",
  ui_story_5046_50460202_27_dialog_content = "지금 상황에서 일을 키운다면, 「검은 흉성」이 PlayerName 씨를 해칠 수도 있습니다.",
  ui_story_5046_50460202_28_dialog_content = "제가 한시라도 빨리 「검은 흉성」의 행방을 찾아 PlayerName 씨를 구하겠습니다.",
  ui_story_5046_50460202_29_dialog_content = "......",
  ui_story_5046_50460202_30_dialog_content = "미안하지만 전 지금 당신들을 믿을 수 없어요.",
  ui_story_5046_50460202_31_dialog_content = "베델 씨가 믿을 수 없는 게 저희의 능력이라면...",
  ui_story_5046_50460202_32_dialog_content = "제가 이반 가문의 이름을 걸고 맹세할게요.\n제 선생님, 기사 제나스는 신뢰할 수 있는 사람이에요.",
  ui_story_5046_50460202_33_dialog_content = "아가씨, 저 때문에 그러실 필요는 없습니다...",
  ui_story_5046_50460202_34_dialog_content = "베델 양, 부디 저희에게 실수를 만회할 기회를 주십시오.",
  ui_story_5046_50460202_35_dialog_content = "제나스 씨의 소문은 저도 들었어요.",
  ui_story_5046_50460202_36_dialog_content = "몰락한 귀족에서 현재의 지위까지 뛰어오른 걸 보면 보통 실력과 수완은 아니겠죠.",
  ui_story_5046_50460202_37_dialog_content = "좋아요, 이반 가문이 나서서 보증을 서는 이상, 저도 일단은 믿어보도록 할게요.",
  ui_story_5046_50460202_38_dialog_content = "다만 이것만은 확실히 알아두세요.\n섀도우마스터께선 머지않아 이번 일을 아시게 될 거예요.",
  ui_story_5046_50460202_39_dialog_content = "3일의 시간을 드리죠.",
  ui_story_5046_50460202_40_dialog_content = "전 3일 뒤에 PlayerName 씨가 털끝 하나 다치지 않고\n준공식 현장에 돌아오는 걸 봐야겠어요.",
  ui_story_5046_50460202_41_dialog_content = "만약 그렇게 안 된다면, 전 움브라톤의 방식대로 이번 일을 처리하겠어요.",
  ui_story_5046_50460202_42_dialog_content = "감사합니다.",
  ui_story_5046_50460202_43_dialog_content = "고마워요.",
  ui_story_5046_50460202_44_dialog_content = "그럼, PlayerName 씨 일은 우선 그렇게 하기로 하죠.",
  ui_story_5046_50460202_45_dialog_content = "이젠 하멜 씨가 귀빈들의 동요를 막아 주실 차례예요.",
  ui_story_5046_50460202_46_dialog_content = "물론 그래야지요!",
  ui_story_5046_50460202_47_dialog_content = "하멜 씨, 절 따라오세요.",
  ui_story_5046_50460202_48_dialog_content = "선생님, 「검은 흉성」을 찾는 일을 돕고 싶어요.",
  ui_story_5046_50460202_49_dialog_content = "최근 몇 년간 전 루미나틱스와 체술 훈련에 힘써 왔어요.\n그건 모두 언젠가 선생님께 힘이 되고 싶었기 때문이에요.",
  ui_story_5046_50460202_50_dialog_content = "제게 기회를 주세요!",
  ui_story_5046_50460202_51_dialog_content = "안 됩니다.",
  ui_story_5046_50460202_52_dialog_content = "혹시 방금 제가 불을 제대로 못 끈 것 때문에 더는 절 못 믿으시는 건가요?",
  ui_story_5046_50460202_53_dialog_content = "...그래요. 전부 제 잘못이에요. 또 선생님이 절 불길 속에서 구해주도록 만들어 버렸잖아요.",
  ui_story_5046_50460202_54_dialog_content = "왜 전 항상 선생님을 위험에 빠트리기만 하는 걸까요...",
  ui_story_5046_50460202_55_dialog_content = "아가씨, 자책하지 마십시오.",
  ui_story_5046_50460202_56_dialog_content = "그때나 오늘이나 아가씨를 지키려고 불길에 뛰어든 건 제 선택이었습니다.",
  ui_story_5046_50460202_57_dialog_content = "그럼 왜 안 된다는 거죠...?",
  ui_story_5046_50460202_58_dialog_content = "아가씨는 항상 현장 조사 보고서나 관련 자료 속에서 중요한 실마리를 찾아내셨습니다.",
  ui_story_5046_50460202_59_dialog_content = "그러니 직접 범인을 추적하는 것보다는 현장 조사나 자료의 분석이\n아가씨께 더 맞는 일이라 할 수 있을 겁니다.",
  ui_story_5046_50460202_60_dialog_content = "능숙하지 않은 일에 무리해서 나설 필요는 없습니다.",
  ui_story_5046_50460202_61_dialog_content = "<size=30>능숙하지 않다기보다는 경험이 부족한 거겠죠...</size>",
  ui_story_5046_50460202_62_dialog_content = "아가씨?",
  ui_story_5046_50460202_63_dialog_content = "아니요, 아무것도 아니에요.",
  ui_story_5046_50460202_64_dialog_content = "그럼 아가씨께는 화재 현장 조사를 부탁드리겠습니다.\n아가씨라면 분명히 유용한 단서를 찾아주실 수 있겠지요.",
  ui_story_5046_50460202_65_dialog_content = "네... 알겠어요!",
  ui_story_5046_50460202_66_dialog_content = "꼭 단서를 찾아낼게요!",
  ui_story_5046_50460202_67_dialog_content = "지금까지 말씀드린 내용이 현재 상황입니다.",
  ui_story_5046_50460202_68_dialog_content = "이제 어떻게 하는 게 좋을까요?",
  ui_story_5046_50460202_69_dialog_content = "흐음...",
  ui_story_5046_50460202_70_dialog_content = "상황을 지켜보도록.",
  ui_story_5046_50460202_71_dialog_content = "하지만... PlayerName의 안전이...",
  ui_story_5046_50460202_72_dialog_content = "걱정할 필요 없다. PlayerName 쪽도 지켜보는 눈이 있으니까.",
  ui_story_5046_50460202_73_dialog_content = "...네.",
  ui_story_5046_50460301_1_dialog_content = "<color=#e8d9bb>움브라톤, 파이어플라이 바</color>",
  ui_story_5046_50460301_2_dialog_content = "다녀왔어요?",
  ui_story_5046_50460301_3_dialog_content = "(「검은 흉성」은 대체 날 어디로 데려온 걸까...)",
  ui_story_5046_50460301_4_dialog_content = "오늘 준공식 리허설 보러 간 거 아니었나요? 웬 선물까지 가지고 왔대요?",
  ui_story_5046_50460301_5_dialog_content = "(이 분위기... 뭔가 술집 같은데? 일단 계속 기절한 척하면서 대화를 들어보자.)",
  ui_story_5046_50460301_6_dialog_content = "「도깨비바늘」 같은 거야.",
  ui_story_5046_50460301_7_dialog_content = "아하하, 뾰족해서 옷에 잘 달라붙는 그 풀 말이죠?",
  ui_story_5046_50460301_8_dialog_content = "응, 옛날에 어머니가 밖에 나갔다 오면 자주 붙여와서, 내가 따는 걸 도와줬거든.",
  ui_story_5046_50460301_9_dialog_content = "참, 물건은 손에 넣었나요?",
  ui_story_5046_50460301_10_dialog_content = "아니, 「도깨비바늘」 때문에 시간을 좀 날렸거든. 사람도 많아서 손을 못 썼어.",
  ui_story_5046_50460301_11_dialog_content = "이 「도깨비바늘」, 왠지 거물인 것 같아. 잡았더니 녀석들이 바짝 긴장하더라고.",
  ui_story_5046_50460301_12_dialog_content = "이런, 이 사람... 아이테르잖아요.",
  ui_story_5046_50460301_13_dialog_content = "아이테르가 뭐지?",
  ui_story_5046_50460301_14_dialog_content = "하다 하다 이젠 아이테르도 모른단 말이에요?\n아, 그렇죠... 당신은 세상에 나온 지 아직 두 달도 안 됐으니까요.",
  ui_story_5046_50460301_15_dialog_content = "그럼 그 아이테르란 건 원래 자는 척하는 걸 좋아하나?",
  ui_story_5046_50460301_16_dialog_content = "(앗?! 엿듣는 걸 들켰나?!)",
  ui_story_5046_50460301_17_dialog_content = "모르겠네요. 움브라톤의 신문에서도 그런 취미가 있다는 내용은 못 봤는데요.",
  ui_story_5046_50460301_18_dialog_content = "어이, 일어나.",
  ui_story_5046_50460301_19_dialog_content = "(으윽! 뼈가 부러질 것 같아! 얼마나 힘이 센 거야?!)",
  ui_story_5046_50460301_20_dialog_content = "(지금 깬 척하는 수밖에 없겠어...)",
  ui_story_5046_50460301_21_dialog_content = "으으...",
  ui_story_5046_50460301_22_dialog_content = "여, 여긴 어디야?",
  ui_story_5046_50460301_23_dialog_content = "너, 왜 이제 일어난 척하는 거지? 바에 들어왔을 때부터 몰래 둘러봤잖아.",
  ui_story_5046_50460301_24_dialog_content = "아하하하... 무, 무슨 소리야? 지금 막 깬 건데.",
  ui_story_5046_50460301_25_dialog_content = "거짓말하는 걸 보면 착한 사람은 아니네.",
  ui_story_5046_50460301_26_dialog_content = "자자, 괜히 PlayerName 씨 겁주지 마세요.",
  ui_story_5046_50460301_27_dialog_content = "어, 어떻게 내 이름을 알아?",
  ui_story_5046_50460301_28_dialog_content = "아이테르의 명성은 이미 온 대륙에 퍼져 있어요.\n당신의 이름을 알고 있어도 전혀 이상할 게 없는데요.",
  ui_story_5046_50460301_29_dialog_content = "그, 그것도 그렇네.",
  ui_story_5046_50460301_30_dialog_content = "긴장할 거 없어요. 우린 무슨 악당 같은 건 아니니까요.",
  ui_story_5046_50460301_31_dialog_content = "전 그림이라고 해요. 「파이어플라이 바」의 바텐더죠.",
  ui_story_5046_50460301_32_dialog_content = "이쪽은 하티, 지금은 이 바에서 아르바이트를 하고 있어요.",
  ui_story_5046_50460301_33_dialog_content = "관계는... 제 쪽이 보호자라고 할 수 있겠네요.",
  ui_story_5046_50460301_34_dialog_content = "섀도우마스터 쪽에서 나온 뒤로는 줄곧 제가 돌보고 있거든요.",
  ui_story_5046_50460301_35_dialog_content = "어른스러워서 20대 정도로 보이죠? 이 친구 사실 18살밖에 안 됐어요!",
  ui_story_5046_50460301_36_dialog_content = "게다가 세상에 나온 지 아직 두 달 정도밖에 되지 않았으니까,\n정신연령은 7, 8살 정도겠네요.",
  ui_story_5046_50460301_37_dialog_content = "왜 당신을 데려왔는지는 모르겠지만, 이것만은 믿어주세요. 하티는 착한 아이예요.",
  ui_story_5046_50460301_38_dialog_content = "사람을 납치해 놓고 「착한 아이」라니...",
  ui_story_5046_50460301_39_dialog_content = "그저 말이나 행동이 조금 거리낌 없을 뿐이지, 딱히 나쁜 마음이 있는 건 아니에요.",
  ui_story_5046_50460301_40_dialog_content = "이번 일은 확실히 하티가 잘못했네요. 제가 하티한테 사과하라고 말해 둘게요.",
  ui_story_5046_50460301_41_dialog_content = "쳇, 내가 왜 이런 녀석한테 사과해야 되는데?",
  ui_story_5046_50460301_42_dialog_content = "이 녀석도 다른 녀석들이랑 똑같이 날 나쁜 놈 취급했어.\n계속 날 「검은 흉성」인지 뭔지라고 부르면서 말이야...",
  ui_story_5046_50460301_43_dialog_content = "이 사람이 뭐라고 했든, 납치해 오는 건 분명한 잘못이에요.",
  ui_story_5046_50460301_44_dialog_content = "잘못을 했다면 사과를 해야죠.",
  ui_story_5046_50460301_45_dialog_content = "쳇...",
  ui_story_5046_50460301_46_dialog_content = "미안해.",
  ui_story_5046_50460301_47_dialog_content = "(엄청 사나워 보이는 녀석인데, 그림이 하는 말은 듣는구나...)",
  ui_story_5046_50460301_48_dialog_content = "죄송해요, PlayerName 씨.",
  ui_story_5046_50460301_49_dialog_content = "(사과에 꽤 성의가 있잖아... 그리고 딱히 나한테 무슨 짓을 한 것도 아니긴 하니까...)",
  ui_story_5046_50460301_50_dialog_content = "그, 그래. 너희가 그렇게 진심으로 사과한다면야... 용서해 줄게.",
  ui_story_5046_50460301_51_dialog_content = "그럼 지금까지의 빚을 청산하는 뜻에서 서로 악수하세요.",
  ui_story_5046_50460301_52_dialog_content = "......",
  ui_story_5046_50460301_53_dialog_content = "......",
  ui_story_5046_50460301_54_dialog_content = "하하하, 둘 다 쭈뼛쭈뼛한 게 꽤 비슷하네요.",
  ui_story_5046_50460301_55_dialog_content = "누가 이런 사람이랑 비슷하다는 거야...",
  ui_story_5046_50460301_56_dialog_content = "아아, 참, 아이테르는 감응 능력으로 다른 사람의 머릿속 깊은 곳의\n기억을 찾을 수 있다고 들었는데 말이죠.",
  ui_story_5046_50460301_57_dialog_content = "PlayerName 씨 도움을 받으면 당신 어머니 일을 떠올릴 수 있을지도 몰라요.",
  ui_story_5046_50460301_58_dialog_content = "(음? 어머니 얘기가 나오니까 하티가 갑자기 괴로운 표정을 지었어...)",
  ui_story_5046_50460301_59_dialog_content = "하티 당신, 과거에 무슨 일이 있었는지 계속 궁금해했잖아요?",
  ui_story_5046_50460301_60_dialog_content = "...이 녀석이 도움이 된다고?",
  ui_story_5046_50460301_61_dialog_content = "지금 내 힘을 무시하는 거야? 아니지, 왜 내가 도와줘야 하는데?",
  ui_story_5046_50460301_62_dialog_content = "음... 그것도 그렇네요.",
  ui_story_5046_50460301_63_dialog_content = "그럼 이렇게 하자. 내가 감응 능력으로 도와줄 테니까, 너흰 날 돌려보내 줘.",
  ui_story_5046_50460301_64_dialog_content = "그리고 하티 넌 가서 자수해. 자기가 지은 죄에 대한 책임을 져야지!",
  ui_story_5046_50460301_65_dialog_content = "합리적인 제안이네요. 그렇게 하기로 해요.",
  ui_story_5046_50460301_66_dialog_content = "하지만 그 사건들은 정말 하티가 한 게 아니에요. 제가 보증할 수 있어요.",
  ui_story_5046_50460301_67_dialog_content = "PlayerName 씨도 사건에 관심이 있는 거라면,\n이참에 하티와 함께 진범을 찾아보시는 건 어떨까요?",
  ui_story_5046_50460301_68_dialog_content = "도움을 주는 조건으로서 말이죠.",
  ui_story_5046_50460301_69_dialog_content = "좋아, 그럼 그렇게 하자!",
  ui_story_5046_50460301_70_dialog_content = "......",
  ui_story_5046_50460301_71_dialog_content = "내 기억을 되찾는 걸 도와준다면...",
  ui_story_5046_50460301_72_dialog_content = "네가 날 잡아다 현상금 20만 나이티움을 받더라도 불만은 없어.",
  ui_story_5046_50460301_73_dialog_content = "걱정 마. 네가 진짜 범인이 아니라면 현상금 때문에 널 파는 짓은 안 할 거니까.",
  ui_story_5046_50460301_74_dialog_content = "20만 나이티움은 확실히 큰돈이지만, 난 돈 때문에 그런 짓을 할 사람은 아냐.",
  ui_story_5046_50460301_75_dialog_content = "상관없어.",
  ui_story_5046_50460301_76_dialog_content = "그, 그럼 이제 내가 뭘 도와주면 되는데?",
  ui_story_5046_50460301_77_dialog_content = "감응 능력을 제대로 발휘하려면 사정을 더 자세히 알아두는 게 좋아.",
  ui_story_5046_50460301_78_dialog_content = "어머니를 찾고 싶어.",
  ui_story_5046_50460301_79_dialog_content = "난 어렸을 때 어머니랑 같이 살았다.\n어머니는 나한테 잘해주시진 않았지만, 딱히 나쁘지도 않았지.",
  ui_story_5046_50460301_80_dialog_content = "그러다 어느 날, 왠지는 모르겠지만 난 어머니와 떨어졌다.",
  ui_story_5046_50460301_81_dialog_content = "그 뒤로는 고아원에 있을 때의 기억뿐이야.",
  ui_story_5046_50460301_82_dialog_content = "그러니까 그 전의 기억을 잃었다는 거지?",
  ui_story_5046_50460301_83_dialog_content = "그럼 만약 그 기억을 찾을 수 있다면, 너희 어머니를 찾을 수도 있다는 얘기겠네.",
  ui_story_5046_50460301_84_dialog_content = "그래.",
  ui_story_5046_50460301_85_dialog_content = "정보는 그게 다야?",
  ui_story_5046_50460301_86_dialog_content = "맞아.",
  ui_story_5046_50460301_87_dialog_content = "알겠어... 네가 나랑 내 감응 능력을 못 믿는 건 이해해.",
  ui_story_5046_50460301_88_dialog_content = "그래도 약속한 일은 최선을 다할게.",
  ui_story_5046_50460301_89_dialog_content = "......",
  ui_story_5046_50460301_90_dialog_content = "죄송해요, PlayerName 씨. 이 아이는 아직 세상에 나온 지 얼마 안 돼서 붙임성이 없거든요.",
  ui_story_5046_50460301_91_dialog_content = "괜찮아. 그저 너희가 약속을 지키고, 도움이 끝나면 내가 돌아가게 해주길 바랄 뿐이야.",
  ui_story_5046_50460301_92_dialog_content = "하티, 지금부터 기억이 끊기기 전에 봤던 마지막 장면을 떠올려줘.",
  ui_story_5046_50460301_93_dialog_content = "그럼 준비되면 알려줘.",
  ui_story_5046_50460301_94_dialog_content = "준비됐어.",
  ui_story_5046_50460301_95_dialog_content = "하티, 심호흡하고, 너무 긴장하지 마세요.",
  ui_story_5046_50460301_96_dialog_content = "그럼 시작하자.",
  ui_story_5046_50460301_97_option_content = "(강제 감응!)",
  ui_story_5046_50460301_98_dialog_content = "......",
  ui_story_5046_50460301_99_dialog_content = "(여기가 어디지? 평범한 민가 같은데...)",
  ui_story_5046_50460301_100_dialog_content = "(하티의 집인가?)",
  ui_story_5046_50460301_101_dialog_content = "(PlayerName?)",
  ui_story_5046_50460301_102_dialog_content = "(너 정말 내 기억이 보이는구나.)",
  ui_story_5046_50460301_103_dialog_content = "(이제 날 믿을 수 있겠어?)",
  ui_story_5046_50460301_104_dialog_content = "<color=#e8d9bb>뚜벅, 뚜벅, 뚜벅...</color>",
  ui_story_5046_50460301_105_dialog_content = "(발소리야. 점점 가까워지고 있어.)",
  ui_story_5046_50460301_106_dialog_content = "하티... 또 어디로 갔을까?",
  ui_story_5046_50460301_107_dialog_content = "(누구야?)",
  ui_story_5046_50460301_108_dialog_content = "(어머니야...)",
  ui_story_5046_50460301_109_dialog_content = "휴...",
  ui_story_5046_50460301_110_dialog_content = "저 아이의 힘... 갈수록 제어하기 힘들어지고 있어... 걱정이네...",
  ui_story_5046_50460301_111_dialog_content = "게다가 이젠 바깥세상을 동경하기 시작했어...",
  ui_story_5046_50460301_112_dialog_content = "하지만 절대 밖으로 나가게 해선 안 돼...",
  ui_story_5046_50460301_113_dialog_content = "(왜 하티를 나가게 하면 안 된다는 거지?)",
  ui_story_5046_50460301_114_dialog_content = "(어머니는 내 힘을... 내 불꽃을 무서워하셨거든.)",
  ui_story_5046_50460301_115_dialog_content = "<color=#e8d9bb>퍼어엉!</color>",
  ui_story_5046_50460301_116_dialog_content = "크오오오!",
  ui_story_5046_50460301_117_dialog_content = "(으악──!)",
  ui_story_5046_50460301_118_dialog_content = "(이, 이건... 개? 아니면 늑대인가? 엄청 크네!)",
  ui_story_5046_50460301_119_dialog_content = "(게다가 하티랑 좀 비슷하게 생긴 것 같은데...)",
  ui_story_5046_50460301_120_dialog_content = "(저건 내 마음속 어둠이야. 내 힘에 대한 두려움과 혐오가 형상화된 거지.)",
  ui_story_5046_50460301_121_dialog_content = "(녀석이 내 잃어버린 기억을 지키고 있어서, 날 한 발짝도 다가가지 못하게 해.)",
  ui_story_5046_50460301_122_dialog_content = "(으윽──! 머리가... 아파...!)",
  ui_story_5046_50460301_123_dialog_content = "(괜찮아? 무슨 일이야? 많이 안 좋아 보이는데...)",
  ui_story_5046_50460301_124_dialog_content = "넌 내가 싫은 거냐... 하지만... 나는 곧 너다...",
  ui_story_5046_50460301_125_dialog_content = "(상황이 안 좋아! 감응을 멈추고 일단 여기서 벗어나자!)",
  ui_story_5046_50460301_126_dialog_content = "PlayerName 넌 정말로 내 기억을 볼 수 있었구나. 심지어 내 마음속 어둠까지...",
  ui_story_5046_50460301_127_dialog_content = "아이테르의 능력은 정말 신기하네.",
  ui_story_5046_50460301_128_dialog_content = "확실히 아이테르의 감응 능력이 도움이 된 모양이네요.",
  ui_story_5046_50460301_129_dialog_content = "정말 다행이에요, 하티.",
  ui_story_5046_50460301_130_dialog_content = "근데 마음속 어둠이 나타나니까 하티의 감정이 심하게 흔들렸어.\n그래서 감응을 끊을 수밖에 없었어.",
  ui_story_5046_50460301_131_dialog_content = "결국 하티는 아무것도 못 떠올렸어...",
  ui_story_5046_50460301_132_dialog_content = "그럼 네가 더 많은 걸 알수록, 내가 기억을 되찾을 가능성도 높아지는 거겠지?",
  ui_story_5046_50460301_133_dialog_content = "뭐?",
  ui_story_5046_50460301_134_dialog_content = "아, 아마 그럴걸...",
  ui_story_5046_50460301_135_dialog_content = "그럼 더 얘기해 줄 테니까, 다시 감응 능력을 사용해 줄 수 있겠어?",
  ui_story_5046_50460301_136_dialog_content = "안 되는 건 아니지만...",
  ui_story_5046_50460301_137_dialog_content = "대신 약속은 꼭 지켜줘. 일이 끝나면 날 풀어주는 거야.",
  ui_story_5046_50460301_138_dialog_content = "약속할게.",
  ui_story_5046_50460401_1_dialog_content = "크리스틴 심판관님, 고아원 화재 현장의 조사 보고서를 가져왔습니다. 확인해 보십시오.",
  ui_story_5046_50460401_2_dialog_content = "수고했어요. 하지만 전 아직 견습 심판관이에요.\n그냥 크리스틴이라고 불러주셔도 돼요.",
  ui_story_5046_50460401_3_dialog_content = "화재 원인은 불이 붙기 쉬운 연료인가요...\n고아원 건설 공사로 남은 건자재가 연료와 함께 창고에 보관돼 있었던 거군요.",
  ui_story_5046_50460401_4_dialog_content = "화재 발생 당시엔 모두 준공식 준비로 바빴고,\n아무도 창고에 연료가 반입된 걸 눈치채지 못했겠죠.",
  ui_story_5046_50460401_5_dialog_content = "「이번에 발견된 연료는 지난 2개월간의 화재 현장에서 발견된 것과\n일치해 동일인의 범행으로 추측된다.」",
  ui_story_5046_50460401_6_dialog_content = "으음... 확실히 합리적인 추론이네요.",
  ui_story_5046_50460401_7_dialog_content = "하지만 지난 두 달간의 화재에선 인질을 잡고 도주하진 않았어요.\n그런데 이번엔 아이테르를 인질로 잡고 도주했죠...",
  ui_story_5046_50460401_8_dialog_content = "이 점은 이상하네요. 게다가 용의자의 범행 동기는 뭘까요?",
  ui_story_5046_50460401_9_dialog_content = "현장 인원의 보고에 따르면 용의자는 아인족 혈통의 오로리안으로,\n이름은 하티라고 합니다.",
  ui_story_5046_50460401_10_dialog_content = "지금까지는 계속 섀도우마스터의 저택에서 살고 있었습니다만,\n두 달 전에 그 저택을 떠났습니다. 이것들은 관련 자료입니다.",
  ui_story_5046_50460401_11_dialog_content = "으음...",
  ui_story_5046_50460401_12_dialog_content = "「목격자들은 고아원 화재 당일 밤, 하티가 강력한 불꽃의\n루미나를 발산해 큰 화재를 일으켰다고 증언했다.」",
  ui_story_5046_50460401_13_dialog_content = "지금 모든 단서는 이 하티라는 이름의 아인족 혈통 오로리안을 가리키고 있어요.",
  ui_story_5046_50460401_14_dialog_content = "게다가 마침 하티가 섀도우마스터의 저택을 나오고 얼마 안 가서 이 화재들이 발생했죠...\n하지만 대체 무슨 목적 때문이었을까요?",
  ui_story_5046_50460401_15_dialog_content = "참, 그 구조된 여자애는...",
  ui_story_5046_50460401_16_dialog_content = "현재 고아원 숙소에서 보육교사가 돌보고 있습니다.",
  ui_story_5046_50460401_17_dialog_content = "그럼 가서 여자애한테 화재 현장에서의 상황을 물어보기로 해요.",
  ui_story_5046_50460401_18_dialog_content = "안녕하세요. 전 백야성의 견습 심판관 크리스틴이라고 해요.",
  ui_story_5046_50460401_19_dialog_content = "아이에게 화재 현장에서 있었던 일을 좀 묻고 싶어요.",
  ui_story_5046_50460401_20_dialog_content = "백야성의 귀족 아가씨인가요. 어차피 거절할 수도 없겠죠.\n하지만 아이가 아직 마음이 안정되지 않았어요.",
  ui_story_5046_50460401_21_dialog_content = "질문은 되도록 간략하게 해 주세요. 아이가 또 시끄러워지면 바로 돌아가 주셔야 해요.",
  ui_story_5046_50460401_22_dialog_content = "아이들을 무척 배려해 주시는군요. 최대한 빨리 끝낼게요.",
  ui_story_5046_50460401_23_dialog_content = "꼬마야, 안녕.",
  ui_story_5046_50460401_24_dialog_content = "앗! 아까 그 언니네!",
  ui_story_5046_50460401_25_dialog_content = "나 구해준 오빠랑 그 강아지는 안 왔어?",
  ui_story_5046_50460401_26_dialog_content = "응... 안 왔어. 그 둘이랑 잘 아니?",
  ui_story_5046_50460401_27_dialog_content = "아니야. 근데 불이 났을 때 그 오빠가 나 지켜줬어. 그러니까 오빠는 좋은 사람이야!",
  ui_story_5046_50460401_28_dialog_content = "위에서 나무토막이 떨어질 때 커다란 강아지가\n갑자기 나타나서 나랑 오빠를 구해줬거든!",
  ui_story_5046_50460401_29_dialog_content = "(하티가 두 사람을 구했단 말인가요?)",
  ui_story_5046_50460401_30_dialog_content = "그럼 언니한테 알려줄래? 왜 그때 불 속에 있었어?",
  ui_story_5046_50460401_31_dialog_content = "아... 으... 훌쩍...",
  ui_story_5046_50460401_32_dialog_content = "으음?",
  ui_story_5046_50460401_33_dialog_content = "앗! 꼬마야, 사탕 먹을래?",
  ui_story_5046_50460401_34_dialog_content = "응!",
  ui_story_5046_50460401_35_dialog_content = "냠냠... 우린 숨바꼭질을 했어. 난 그래서 거기 숨어 있었던 거야.",
  ui_story_5046_50460401_36_dialog_content = "근데 그 방엔 커다란 양동이가 잔뜩 있었고, 이상한 상자도 있었어.",
  ui_story_5046_50460401_37_dialog_content = "이상한 상자?",
  ui_story_5046_50460401_38_dialog_content = "응, 내가 실수로 그 상자를 쳐서 땅에 떨어트렸거든. 그랬더니 갑자기 불이 화아악 붙었어!",
  ui_story_5046_50460401_39_dialog_content = "방에서 나가려고 했는데 불이 방에 다 번져서 너무 무서웠어...",
  ui_story_5046_50460401_40_dialog_content = "으... 훌쩍... 나 일부러 그런 거 아니야...",
  ui_story_5046_50460401_41_dialog_content = "으아아아아아앙──!",
  ui_story_5046_50460401_42_dialog_content = "부, 불 싫어! 너무 무서워!",
  ui_story_5046_50460401_43_dialog_content = "아이참, 또 울리면 어떡해요? 물어볼 건 다 물어봤죠? 얼른 돌아가세요.",
  ui_story_5046_50460401_44_dialog_content = "미안해, 꼬마야... 대신 다음부터는 모르는 데 혼자 가면 안 돼.",
  ui_story_5046_50460401_45_dialog_content = "훌쩍... 아, 알았어...",
  ui_story_5046_50460401_46_dialog_content = "<color=#e8d9bb>움브라톤, 파이어플라이 바</color>",
  ui_story_5046_50460401_47_dialog_content = "안 돼... 역시 기억이 안 나...",
  ui_story_5046_50460401_48_dialog_content = "그렇게 많은 정보가 있어도, 감응 능력으로는 역시 그 시절의 기억을 찾을 수 없는 건가...",
  ui_story_5046_50460401_49_dialog_content = "미안. 도움이 안 됐네...",
  ui_story_5046_50460401_50_dialog_content = "납치했던 걸 용서해 줬을 뿐만 아니라, 도움까지 주려고 했잖아요. 이미 그걸로 충분해요.",
  ui_story_5046_50460401_51_dialog_content = "분명히 다른 방법이 있을 거야...",
  ui_story_5046_50460401_52_dialog_content = "...펜던트! 그래! 펜던트다!",
  ui_story_5046_50460401_53_dialog_content = "펜던트?",
  ui_story_5046_50460401_54_dialog_content = "내가 이 녀석을 잡아 온 건 그 가면 쓴 자식한테 펜던트를 되찾기 위해서였어.",
  ui_story_5046_50460401_55_dialog_content = "그 펜던트는 나한테 매우 소중한 거야.\n그리고 넌 그 가면 쓴 자식한테 중요한 사람이지.",
  ui_story_5046_50460401_56_dialog_content = "그럼 등가교환이다.",
  ui_story_5046_50460401_57_dialog_content = "날 가지고 펜던트랑 교환하겠다고?! 그거 너무 막 나가는 제안 아냐?!",
  ui_story_5046_50460401_58_dialog_content = "사회적인 상식이 완전히 결여돼 있잖아!",
  ui_story_5046_50460401_59_dialog_content = "그림, 넌 하티의 보호자라고 했잖아. 뭐 할 말 없어?!",
  ui_story_5046_50460401_60_dialog_content = "확실히 좀 돌직구긴 한데, 그렇다고 틀린 말은 아니지 않나요?",
  ui_story_5046_50460401_61_dialog_content = "PlayerName 씨는 무사히 돌아갈 수 있고, 하티도 원하는 걸 얻을 수 있잖아요.",
  ui_story_5046_50460401_62_dialog_content = "아주 타산이 맞는 거래 아닌가요?",
  ui_story_5046_50460401_63_dialog_content = "왜, 왠지 일리가 있는 것 같기도...",
  ui_story_5046_50460401_64_dialog_content = "아니지, 잠깐만! 내가 도와주면 풀어준다고 했었잖아?",
  ui_story_5046_50460401_65_dialog_content = "근데 왜 또 내가 교환 조건이 되는 건데?! 이건 약속이 다르잖아!",
  ui_story_5046_50460401_66_dialog_content = "하지만 하티는 기억을 못 찾았잖아요?",
  ui_story_5046_50460401_67_dialog_content = "크윽... 역시 움브라톤 사람들은 하나같이 교활하다니까.",
  ui_story_5046_50460401_68_dialog_content = "(거래할 물건 취급을 받는 건 기분이 나쁘지만, 그렇다고 나한테 손해가 되는 건 아니니까...)",
  ui_story_5046_50460401_69_dialog_content = "(게다가 상황을 봐서 도망칠 수 있을지도 몰라. 그러고 나서 베델한테 알리면 돼...)",
  ui_story_5046_50460401_70_dialog_content = "그럼 이제 어떻게 하면 그 가면남과 거래할 수 있을지 생각해 봐야겠네요.",
  ui_story_5046_50460401_71_dialog_content = "하티는 지금 지명 수배가 돼 있어요.\n함부로 나갔다가는 거래하기도 전에 체포돼 버릴 거예요.",
  ui_story_5046_50460401_72_dialog_content = "자, 이렇게 하죠. 하티 당신은 편지를 써 주세요.\n제가 어떻게든 가면남한테 전달할게요.",
  ui_story_5046_50460401_73_dialog_content = "움브라톤 밖에서 만나기로 하고, 반드시 혼자 오라고 해야겠죠.",
  ui_story_5046_50460401_74_dialog_content = "좋아.",
  ui_story_5046_50460401_75_dialog_content = "그림 넌 이 녀석이 도망 못 가게 감시해 줘.",
  ui_story_5046_50460401_76_dialog_content = "도망치려고 하면 기절시켜. 내가 데리고 왔을 때처럼 말이야.",
  ui_story_5046_50460401_77_dialog_content = "...큭!",
  ui_story_5046_50460401_78_dialog_content = "뭐라도 좀 마실래요? 거래가 끝나면 돌아가야 하잖아요.",
  ui_story_5046_50460401_79_dialog_content = "그때가 되면 여기 앉아서 느긋하게 한잔할 기회가 없을지도 몰라요.",
  ui_story_5046_50460401_80_dialog_content = "그 펜던트는 어떤 물건이야?",
  ui_story_5046_50460401_81_dialog_content = "왜 하티가 저렇게 아끼는 건데?",
  ui_story_5046_50460401_82_dialog_content = "마침 하티도 없겠다, 그럼 제가 이야기를 좀 들려드리죠.",
  ui_story_5046_50460401_83_dialog_content = "어느 날 하티가 갑자기 달려와서는, 어떤 가면 쓴 남자가\n어머니의 펜던트를 가지고 있었다고 하더군요.",
  ui_story_5046_50460401_84_dialog_content = "가면 쓴 남자? 분명히 제나스 대장 얘기겠지? 가면 쓰고 있는 건 그 사람뿐이니까.",
  ui_story_5046_50460401_85_dialog_content = "하티는 그 사람과 거래를 하려고 했지만, 상대방은 하티를 보고 무척 놀란 것 같았고,\n어떤 조건을 걸어도 그 펜던트를 주지 않았다고 해요.",
  ui_story_5046_50460401_86_dialog_content = "그래서 하티는 그 펜던트를 빼앗을 계획을 세웠죠.",
  ui_story_5046_50460401_87_dialog_content = "그건 범죄잖아!",
  ui_story_5046_50460401_88_dialog_content = "게다가 그 펜던트가 자기가 찾는 거랑 같다는 걸 어떻게 확신하는데?",
  ui_story_5046_50460401_89_dialog_content = "하티 말로는 그 펜던트를 보자마자 갑자기 머리가 아파지기 시작했다고 해요.",
  ui_story_5046_50460401_90_dialog_content = "자긴 어머니의 펜던트 문양을 확실하게 기억하고 있는데,\n그 펜던트의 문양과 완전히 똑같았다더군요.",
  ui_story_5046_50460401_91_dialog_content = "그리고 그 펜던트만 되찾으면 잃어버린 기억을 되찾을 수 있다고도 했어요.",
  ui_story_5046_50460401_92_dialog_content = "말 무늬 말하는 거야?",
  ui_story_5046_50460401_93_dialog_content = "백야성 귀족은 저마다 자기 가문을 상징하는 문장이 있다고 들었어.\n설마 그 사람이랑 하티의 어머니가 같은 가문 사람일까?",
  ui_story_5046_50460401_94_dialog_content = "그건 저도 모르겠네요.",
  ui_story_5046_50460401_95_dialog_content = "편지 다 썼어.",
  ui_story_5046_50460401_96_dialog_content = "<color=#e8d9bb>똑똑똑, 똑, 똑똑</color>",
  ui_story_5046_50460401_97_dialog_content = "마침 잘 왔어요. 들어와요.",
  ui_story_5046_50460401_98_dialog_content = "사장님.",
  ui_story_5046_50460401_99_dialog_content = "괜찮아요. 하티도 PlayerName도 나쁜 사람이 아니에요.",
  ui_story_5046_50460401_100_dialog_content = "움브라톤의 각 세력들 모두 별다른 움직임은 없어요.\n백야성에서 온 그 기사는 지금 사람들을 데리고 여기로 오고 있어요.",
  ui_story_5046_50460401_101_dialog_content = "아마 곧 도착할 거예요.",
  ui_story_5046_50460401_102_dialog_content = "그래요? 타이밍이 좋네요.",
  ui_story_5046_50460401_103_dialog_content = "고마워요. 자, 수고비예요.",
  ui_story_5046_50460401_104_dialog_content = "고마워요, 사장님!",
  ui_story_5046_50460401_105_dialog_content = "그럼 먼저 갈게요.",
  ui_story_5046_50460401_106_dialog_content = "(저 꼬맹이가 그림의 정보원이라고? 그림 이 녀석... 대체 정체가 뭐지...)",
  ui_story_5046_50460401_107_dialog_content = "하티, 편지는 제가 전할게요. 당신은 먼저 약속장소에 가서 기다리고 있어요.",
  ui_story_5046_50460401_108_dialog_content = "알겠어. PlayerName, 가자.",
  ui_story_5046_50460401_109_dialog_content = "얌전히 따라오는 게 좋을 거야. 살려달라고 소리를 치거나 한다면...",
  ui_story_5046_50460401_110_dialog_content = "기절시킬 거지?",
  ui_story_5046_50460401_111_dialog_content = "이번엔 꼭 약속을 지켜주길 바랄게. 펜던트를 손에 넣으면 날 풀어줘.",
  ui_story_5046_50460401_112_dialog_content = "백야성의 경비병은 이미 근처까지 와 있어요. 나갈 때 조심하세요.",
  ui_story_5046_50460401_113_dialog_content = "경비병도 기절시키면 되지.",
  ui_story_5046_50460402_1_dialog_content = "<color=#e8d9bb>딸랑──</color>",
  ui_story_5046_50460402_2_dialog_content = "어서 오세요. 뭘로 드릴까요?",
  ui_story_5046_50460402_3_dialog_content = "이런, 백야성의 높으신 분들이셨군요.\n귀하신 분들이 이런 누추한 움브라톤의 바에는 무슨 일로 오셨을까요?",
  ui_story_5046_50460402_4_dialog_content = "오래 방해할 생각은 없습니다. 질문만 조금 하고 바로 가겠습니다.",
  ui_story_5046_50460402_5_dialog_content = "그럼 뭐라도 마시면서 천천히 말씀하시죠. 제가 아는 건 전부 말씀드릴게요.",
  ui_story_5046_50460402_6_dialog_content = "괜찮습니다.",
  ui_story_5046_50460402_7_dialog_content = "목격자의 증언에 따르면 오늘 리허설 장소에서 불을 지른 범인은 당신의 친구인 하티입니다.",
  ui_story_5046_50460402_8_dialog_content = "도주 경로로 봤을 때 저흰 하티가 이곳으로 도망친 것으로 추정하고 있습니다.",
  ui_story_5046_50460402_9_dialog_content = "수사에 협조해 주셨으면 좋겠군요.",
  ui_story_5046_50460402_10_dialog_content = "물론 저도 협조하고 싶지만, 하티가 방화범이라는 확실한 증거를 보여주셨으면 좋겠네요.",
  ui_story_5046_50460402_11_dialog_content = "그렇지 않으면 협조는 어려워요.",
  ui_story_5046_50460402_12_dialog_content = "그렇다면 강제로 수사할 수밖에 없습니다.",
  ui_story_5046_50460402_13_dialog_content = "아이테르는 하티와 함께 있어요.",
  ui_story_5046_50460402_14_dialog_content = "!",
  ui_story_5046_50460402_15_dialog_content = "백야성 사람이 움브라톤의 경비 임무를 맡아 놓고, 중요한 손님이 납치당하게 만들었는데...",
  ui_story_5046_50460402_16_dialog_content = "베델 씨는 움브라톤 내 다른 세력에 도움을 청하지 않고, 당신 혼자 조사하게 하고 있죠...",
  ui_story_5046_50460402_17_dialog_content = "아마 일을 크게 만들고 싶지 않은 거겠죠.",
  ui_story_5046_50460402_18_dialog_content = "이 일이 알려지는 건 당신도 원하지 않을 것 같은데요.",
  ui_story_5046_50460402_19_dialog_content = "흥, 하티가 있는 곳을 알고 있습니까?\n하티만 넘기면 백야성이나 움브라톤도 당신을 섭섭하게 만들 일은 없을 겁니다.",
  ui_story_5046_50460402_20_dialog_content = "후훗... 섭섭하지 않을지 어떨지는 둘이 따로 천천히 얘기했으면 좋겠는데요.",
  ui_story_5046_50460402_21_dialog_content = "...여러분은 먼저 나가 있으세요.",
  ui_story_5046_50460402_22_dialog_content = "하지만 대장님...",
  ui_story_5046_50460402_23_dialog_content = "밖에서 기다리세요.",
  ui_story_5046_50460402_24_dialog_content = "예.",
  ui_story_5046_50460402_25_dialog_content = "당신이 지금의 자리에 있는 건 그만한 능력이 있기 때문이겠죠.",
  ui_story_5046_50460402_26_dialog_content = "자, 이건 하티가 당신에게 전해달라고 부탁한 편지예요.",
  ui_story_5046_50460402_27_dialog_content = "「가면 쓴 자식에게」",
  ui_story_5046_50460402_28_dialog_content = "「해가 지기 전까지 펜던트를 가지고 움브라톤 동쪽 숲에 있는\n가장 큰 단풍나무 아래로 와라. 아이테르와 맞교환이다.」",
  ui_story_5046_50460402_29_dialog_content = "「혼자 와라. 다른 사람에게 말하거나 헛수작은 부리지 않는 게 좋을 거다.」",
  ui_story_5046_50460402_30_dialog_content = "「──하티」",
  ui_story_5046_50460402_31_dialog_content = "......",
  ui_story_5046_50460402_32_dialog_content = "PlayerName 씨는 무사한 게 확실합니까?",
  ui_story_5046_50460402_33_dialog_content = "안심하세요. 아이테르라면 멀쩡하니까요.\n이제 시간도 얼마 안 남았고, 어차피 다른 선택지는 없을 텐데요.",
  ui_story_5046_50460402_34_dialog_content = "흥, 이 제나스에게 협박은 통하지 않습니다.",
  ui_story_5046_50460402_35_dialog_content = "조심히 가세요. 다음엔 꼭 한잔 마시고 가세요.",
  ui_story_5046_50460402_36_dialog_content = "......",
  ui_story_5046_50460402_37_dialog_content = "사장님.",
  ui_story_5046_50460402_38_dialog_content = "가게를 좀 봐주시겠어요? 잠깐 나갔다 와야겠어요.",
  ui_story_5046_50460402_39_dialog_content = "대장님!",
  ui_story_5046_50460402_40_dialog_content = "조사해 볼 일이 생겼습니다. 저 혼자 가겠습니다.",
  ui_story_5046_50460402_41_dialog_content = "여러분은 계속해서 이 일대를 수색하십시오. 어느 한 곳도 빠트리지 마십시오.",
  ui_story_5046_50460402_42_dialog_content = "만약 용의자와 PlayerName 씨의 흔적을 발견한다면,\nPlayerName 씨의 안전을 최우선으로 고려하면서 두 사람을 데려오십시오.",
  ui_story_5046_50460402_43_dialog_content = "예!",
  ui_story_5046_50460402_44_dialog_content = "<color=#e8d9bb>움브라톤, 자료관</color>",
  ui_story_5046_50460402_45_dialog_content = "지난 두 달 동안 발생한 화재에 대한 자료는 모두 여기 있습니다.",
  ui_story_5046_50460402_46_dialog_content = "고마워요. 나머지는 저 혼자 살펴볼게요.",
  ui_story_5046_50460402_47_dialog_content = "(최근 두 달 동안 화재가 빈번하게 일어났군요.\n하지만 그중 사망자가 발생한 건 세 건뿐...)",
  ui_story_5046_50460402_48_dialog_content = "「첫 번째 피해자, 안드레, 36세, 남성, 무직, 가끔 일용직으로 일하며, 술에 빠져 지냄.」",
  ui_story_5046_50460402_49_dialog_content = "「두 번째 피해자, 페르민, 42세, 남성, 상인, 사업 상황이 줄곧 시원찮았음.」",
  ui_story_5046_50460402_50_dialog_content = "「세 번째 피해자, 칼로타, 31세, 여성, 세탁소 근무, 별다른 특징 없음.」",
  ui_story_5046_50460402_51_dialog_content = "(피해자는 모두 옛 고아원에서 일했다는 공통점이 있네요.\n안드레는 회계, 페르민은 배달, 칼로타는 청소부였군요)",
  ui_story_5046_50460402_52_dialog_content = "(하티와 이 세 사람의 접점 역시 이 고아원이고 말이죠.)",
  ui_story_5046_50460402_53_dialog_content = "(설마 하티가 옛 고아원에서 피해자들에게 괴롭힘을 당했고...\n그래서 원한을 품고 보복을 한 걸까요?)",
  ui_story_5046_50460402_54_dialog_content = "(옛 고아원의 인사 자료를 조금 더 찾아봐야겠네요.)",
  ui_story_5046_50460402_55_dialog_content = "(고아원의 다른 사람들은 거기서 화재가 발생한 뒤로 뿔뿔이 흩어졌군요.\n가서 당시 상황을 물어볼 여력은 없겠어요.)",
  ui_story_5046_50460402_56_dialog_content = "(이제 어떻게 하면 좋을까요...)",
  ui_story_5046_50460402_57_dialog_content = "「하멜 씨는 장기간 고아원에 기부를 해 왔고,\n정기적으로 자선활동을 벌여 고아원을 위해 기부금을 모았다.」",
  ui_story_5046_50460402_58_dialog_content = "(...하멜 씨?!)",
  ui_story_5046_50460402_59_dialog_content = "<color=#e8d9bb>고아원 안</color>",
  ui_story_5046_50460402_60_dialog_content = "하멜 씨, 잠시만 시간을 내주시겠어요?",
  ui_story_5046_50460402_61_dialog_content = "크리스틴 양! 아이테르님을 찾았습니까?! 정말 다행입니다!",
  ui_story_5046_50460402_62_dialog_content = "아이테르의 행방은 아직 못 찾았어요.\n지금은 「검은 흉성」에 대해 여쭤보고 싶은 게 있어서 온 거예요.",
  ui_story_5046_50460402_63_dialog_content = "그 방화범 말씀이십니까?",
  ui_story_5046_50460402_64_dialog_content = "현재로서는 하티가 방화범 「검은 흉성」일 가능성이 매우 높아요.\n게다가 하티는 옛 고아원의 직원들과 원한 관계가 있어서 범행을 저질렀을 수도 있어요.",
  ui_story_5046_50460402_65_dialog_content = "하멜 씨는 옛 고아원에 오랫동안 기부를 하셨고, 모금 자선활동도 하셨어요.\n그러니 분명 고아원 사정도 잘 알고 계시겠죠.",
  ui_story_5046_50460402_66_dialog_content = "그래서 하멜 씨 생각을 좀 여쭙고 싶었어요.",
  ui_story_5046_50460402_67_dialog_content = "확실히... 전 오랫동안 고아원에 자금을 지원하고 모금 활동을 해 왔습니다.",
  ui_story_5046_50460402_68_dialog_content = "하지만 자세한 일은 모두 고아원 원장과 직원들이 준비해 왔습니다.\n전 그저 당일에 참석만 했을 뿐이지요.",
  ui_story_5046_50460402_69_dialog_content = "고아원에서 정기적으로 장부 내용을 보내주긴 했지만, 그 외의 일은 잘 모릅니다.",
  ui_story_5046_50460402_70_dialog_content = "하지만 지금 당신은 고아원의 새 원장이고, 옛 고아원과도 관계가 깊어요.",
  ui_story_5046_50460402_71_dialog_content = "만약 용의자의 목적이 정말 고아원 관계자에 대한 보복이라면,\n당신이 다음 타깃이 될 가능성이 높아요.",
  ui_story_5046_50460402_72_dialog_content = "뭔가 단서가 될 만한 게 있는지 잘 떠올려 보세요.\n그럼 저희가 한시라도 빨리 용의자를 체포할 수 있을 테니까요.",
  ui_story_5046_50460402_73_dialog_content = "그리고 당분간은 백야성 경비병이 주둔하는 곳에 머무르시는 게 좋을 것 같아요.",
  ui_story_5046_50460402_74_dialog_content = "용의자가 언제 당신을 노릴지 몰라요. 백야성의 경비병이 당신을 지켜드릴 거예요.",
  ui_story_5046_50460402_75_dialog_content = "크리스틴 양, 당신 말은 모두 추측일 뿐이잖습니까.",
  ui_story_5046_50460402_76_dialog_content = "이 고아원은 움브라톤에서 가장 큰 고아원입니다. 관계자도 아주 많이 있지요.",
  ui_story_5046_50460402_77_dialog_content = "주변에서 아무나 붙잡고 물어보세요. 아마 대부분이 고아원과 관계가 있는 사람일 겁니다.",
  ui_story_5046_50460402_78_dialog_content = "건설 노동자, 청소부, 심지어 고아원 입구에서 노점을 차리고 간식을 파는 사람까지...",
  ui_story_5046_50460402_79_dialog_content = "용의자가 그런 사람들에게까지 전부 보복할까요?",
  ui_story_5046_50460402_80_dialog_content = "그, 그건...",
  ui_story_5046_50460402_81_dialog_content = "당신 추측은 그저 우연히 들어맞았을 뿐입니다.",
  ui_story_5046_50460402_82_dialog_content = "그런 우연에 시간을 낭비하느니, 한시라도 빨리 용의자를 체포해 주시는 편이\n사람들을 더 안심시킬 수 있을 겁니다.",
  ui_story_5046_50460402_83_dialog_content = "벌써 시간이 이렇게 됐군요. 나이 든 사람은 일찍 쉬어야 해서요.",
  ui_story_5046_50460402_84_dialog_content = "죄송합니다. 그럼 실례했습니다.",
  ui_story_5046_50460402_85_dialog_content = "멀리 안 나갑니다. 조심히 가세요.",
  ui_story_5046_50460402_86_dialog_content = "오랜만이로군요.",
  ui_story_5046_50460402_87_dialog_content = "너였나.",
  ui_story_5046_50460402_88_dialog_content = "다시 만났는데 기쁘지 않습니까?",
  ui_story_5046_50460402_89_dialog_content = "날 만나러 온 게 아니라 <color=#FFB400>그걸</color> 찾으러 온 거겠지.",
  ui_story_5046_50460501_1_dialog_content = "(하멜 씨의 태도는 어딘가 수상해요. 뭔가 숨기고 있는 것 같아요.)",
  ui_story_5046_50460501_2_dialog_content = "(하지만 이야기를 꺼낼 생각은 없어 보여요.)",
  ui_story_5046_50460501_3_dialog_content = "(용의자 하티, 납치된 아이테르, 리허설 현장의 연료통과 불을 붙이는 장치...)",
  ui_story_5046_50460501_4_dialog_content = "(옛 고아원의 화재와 하멜 씨의 비밀...)",
  ui_story_5046_50460501_5_dialog_content = "(설마 이 모든 게 정말 우연일까요?)",
  ui_story_5046_50460501_6_dialog_content = "(휴... 전혀 단서가 없네요.)",
  ui_story_5046_50460501_7_dialog_content = "(선생님이라면 분명히 곧바로 해결해 주셨을 텐데...)",
  ui_story_5046_50460501_8_dialog_content = "아가씨, 절 찾으셨습니까?",
  ui_story_5046_50460501_9_dialog_content = "서, 선생님?!",
  ui_story_5046_50460501_10_dialog_content = "언제 돌아오셨어요?",
  ui_story_5046_50460501_11_dialog_content = "조금 됐습니다. 혼자 생각에 깊이 잠기신 것 같아서 방해하지 않았습니다.",
  ui_story_5046_50460501_12_dialog_content = "죄송해요. 오신 줄 전혀 몰랐어요...",
  ui_story_5046_50460501_13_dialog_content = "참, 선생님! 조사 과정에서 중요한 사실을 발견했어요!",
  ui_story_5046_50460501_14_dialog_content = "음? 어떤 내용입니까?",
  ui_story_5046_50460501_15_dialog_content = "리허설 현장에서 구조된 여자애의 말에 따르면,\n자기가 실수로 어떤 상자를 떨어트렸더니 불이 났다고 해요.",
  ui_story_5046_50460501_16_dialog_content = "아마 그건 불을 붙이는 장치였을 거예요.\n특정 시간에 창고에 놓인 연료에 불이 붙도록 준비한 거겠죠.",
  ui_story_5046_50460501_17_dialog_content = "범인은 그곳에 장치를 두었지만, 여자애가 나타나서 계획이 틀어졌을 거예요.",
  ui_story_5046_50460501_18_dialog_content = "특정 시간에 화재를 일으킨다라... 그렇다면 그 목적은 무엇이었을까요?",
  ui_story_5046_50460501_19_dialog_content = "지금까지의 조사 결과를 보면, 지난 2개월 동안 일어난 화재 중\n세 건의 화재에서만 사상자가 발생했어요.",
  ui_story_5046_50460501_20_dialog_content = "그리고 그 세 명의 피해자는 모두 옛 고아원에서 일하고 있었죠.",
  ui_story_5046_50460501_21_dialog_content = "마침 오늘 화재 현장에 나타난 하티도 옛 고아원에 한 달 동안 지낸 적이 있었어요.",
  ui_story_5046_50460501_22_dialog_content = "전 하티가 전에 고아원에서 무슨 일을 당했고, 그래서 원한을 품었을 거라 생각해요.",
  ui_story_5046_50460501_23_dialog_content = "불의 힘을 제어하지 못해 옛 고아원에 화재를 일으킨 뒤로,\n섀도우마스터의 저택에서 지내는 동안엔 보복 계획을 멈출 수밖에 없었겠죠.",
  ui_story_5046_50460501_24_dialog_content = "그러다가 두 달 전 저택을 나온 후 바로 보복을 시작한 거예요.",
  ui_story_5046_50460501_25_dialog_content = "그리고 오늘 화재 현장에는 오랜 시간 동안 고아원을 후원해 온 하멜 씨도 있었어요.",
  ui_story_5046_50460501_26_dialog_content = "하티의 다음 타깃은 하멜 씨라고 의심하시는 거군요.",
  ui_story_5046_50460501_27_dialog_content = "네, 하지만 아직은 제 추측일 뿐이고, 확실한 근거는 없어요.",
  ui_story_5046_50460501_28_dialog_content = "그래서 하멜 씨를 찾아가서 수사에 협조해 달라고 하셨군요.",
  ui_story_5046_50460501_29_dialog_content = "네...",
  ui_story_5046_50460501_30_dialog_content = "하멜 씨는 모두 우연일 뿐이라고 하셨지만, 전 하멜 씨가 뭔가 숨기고 있는 것 같아요.",
  ui_story_5046_50460501_31_dialog_content = "아가씨의 몸은 항상 생각보다 행동이 먼저 앞서시는군요.",
  ui_story_5046_50460501_32_dialog_content = "...무슨 말씀이시죠?",
  ui_story_5046_50460501_33_dialog_content = "선악이 뒤섞인 움브라톤에서 어느 정도의 재산이나 지위를 얻은 인물이라면\n대부분 자신만의 비밀을 가지고 있기 마련입니다.",
  ui_story_5046_50460501_34_dialog_content = "그러한 비밀은 그들의 목숨이나 다름없습니다.\n남들, 특히 백야성 사람들에게는 알리고 싶지 않을 겁니다.",
  ui_story_5046_50460501_35_dialog_content = "하멜 씨를 지키고 싶은 아가씨의 마음은 이해합니다.\n하지만 아가씨의 방식은 오히려 상대를 경계하게 만들었습니다.",
  ui_story_5046_50460501_36_dialog_content = "하멜 씨는 수사에 협조하지 않을 것이고, 경호도 받지 못하겠죠.\n게다가 용의자도 아가씨의 의도를 깨닫고 몸을 더 깊이 숨길 겁니다.",
  ui_story_5046_50460501_37_dialog_content = "...제가 생각이 너무 짧았네요... 죄송해요, 선생님.",
  ui_story_5046_50460501_38_dialog_content = "역시 전... 선생님께 힘이 될 수 없는 거군요.",
  ui_story_5046_50460501_39_dialog_content = "다만 아가씨의 추측엔 근거가 있다고 생각합니다.\n그 모든 것은 결코 우연이 아닙니다.",
  ui_story_5046_50460501_40_dialog_content = "제 추측이 맞다고 말씀하시는 건가요?",
  ui_story_5046_50460501_41_dialog_content = "물론입니다. 오랫동안 곁에서 아가씨의 성장을 지켜봐 온 이상,\n아가씨의 능력은 제가 가장 잘 알고 있습니다.",
  ui_story_5046_50460501_42_dialog_content = "자료 속에서 실마리를 찾아 완벽한 증거의 사슬을 짜내는 일에 있어서\n아가씨의 능력은 이미 최고의 수준입니다.",
  ui_story_5046_50460501_43_dialog_content = "서, 선생님...",
  ui_story_5046_50460501_44_dialog_content = "모두 선생님의 가르침 덕분이에요!",
  ui_story_5046_50460501_45_dialog_content = "......",
  ui_story_5046_50460501_46_dialog_content = "크흠... 근데 선생님은 용의자와 PlayerName 씨의 행방을 쫓고 계셨던 거 아닌가요?",
  ui_story_5046_50460501_47_dialog_content = "네. 파이어플라이 바라는 술집의 주인은 하티의 친구였습니다.",
  ui_story_5046_50460501_48_dialog_content = "하지만 그 사람은 입이 무겁더군요. 딱히 알아낸 정보는 없었습니다.\n사람을 시켜 그 부근을 감시하고 있으니 뭔가 수확이 있었으면 좋겠습니다만...",
  ui_story_5046_50460501_49_dialog_content = "크윽...",
  ui_story_5046_50460501_50_dialog_content = "선생님! 괜찮으세요?! 불에 덴 상처 때문인가요?",
  ui_story_5046_50460501_51_dialog_content = "다 저 때문이에요... 저 때문에 선생님이 또 상처를...",
  ui_story_5046_50460501_52_dialog_content = "괜찮습니다. 이 정도 상처는 아무것도 아닙니다.",
  ui_story_5046_50460501_53_dialog_content = "아가씨가 하멜 씨를 다음 타깃이라 추정한다면, 저도 어서 돌아가서 병력을 준비해야겠군요...",
  ui_story_5046_50460501_54_dialog_content = "이제 시간이 얼마 없습니다...",
  ui_story_5046_50460501_55_dialog_content = "으윽!",
  ui_story_5046_50460501_56_dialog_content = "선생님! 무리하시면 안 돼요!",
  ui_story_5046_50460501_57_dialog_content = "제가 선생님을 처음 만났을 때...\n선생님은 만신창이가 되어가면서 불바다 속에서 절 구해주셨죠.",
  ui_story_5046_50460501_58_dialog_content = "오늘도 그래요. 제가 경솔하게 불을 끄려고 할 때도 절 감싸주셨죠...",
  ui_story_5046_50460501_59_dialog_content = "저도 선생님을 위해 힘이 되고 싶어요!",
  ui_story_5046_50460501_60_dialog_content = "아가씨...",
  ui_story_5046_50460501_61_dialog_content = "아가씨라고 부르지 마세요.",
  ui_story_5046_50460501_62_dialog_content = "언제까지나 선생님의 보호만 받는 온실 속의 아가씨가 되고 싶진 않아요.",
  ui_story_5046_50460501_63_dialog_content = "전 백야성에 정의를 가져다주는 심판관이 될 거예요.\n선생님처럼 신뢰할 수 있는 사람이 되고 싶다구요.",
  ui_story_5046_50460501_64_dialog_content = "무, 물론 아직 갈 길이 멀다는 건 잘 알고 있어요.\n하지만 첫발을 내딛지 못하면... 영원히 제자리에 머물 수밖에 없는걸요.",
  ui_story_5046_50460501_65_dialog_content = "아주 작은 걸음이라도 좋으니까, 저도 앞으로 나아가야 해요.",
  ui_story_5046_50460501_66_dialog_content = "그, 그러니까! 하멜 씨의 경호는 제게 맡겨주세요!",
  ui_story_5046_50460501_67_dialog_content = "후훗...",
  ui_story_5046_50460501_68_dialog_content = "아가씨...",
  ui_story_5046_50460501_69_dialog_content = "아니, 크리스틴.",
  ui_story_5046_50460501_70_dialog_content = "참으로 소중한 마음입니다. 당신의 결의에 전 정말 감동했습니다.",
  ui_story_5046_50460501_71_dialog_content = "(에...?! 가, 갑자기 왜 이렇게 가까이 오시는 거죠...?)",
  ui_story_5046_50460501_72_dialog_content = "(선생님의 숨결이 느껴져요...)",
  ui_story_5046_50460501_73_dialog_content = "(머리카락이 얼굴에 닿아서... 간지러워요...)",
  ui_story_5046_50460501_74_dialog_content = "그리고 저에 대한 크리스틴의 마음도 충분히 느꼈습니다...",
  ui_story_5046_50460501_75_dialog_content = "(마, 마음?! 선생님, 지금 무슨 말씀이신 거죠...?!)",
  ui_story_5046_50460501_76_dialog_content = "(서, 설마?!)",
  ui_story_5046_50460501_77_dialog_content = "전 크리스틴이...",
  ui_story_5046_50460501_78_dialog_content = "서, 선생님!",
  ui_story_5046_50460501_79_dialog_content = "전 이제 하멜 씨 경호를 하러 가야겠어요!",
  ui_story_5046_50460501_80_dialog_content = "반드시 노력해서 훌륭하게 임무를 해낼게요!",
  ui_story_5046_50460501_81_dialog_content = "후훗...",
  ui_story_5046_50460501_82_dialog_content = "당신의 두뇌와 용기라면, 분명 훌륭하게 임무를 완수할 수 있을 거라 믿습니다.",
  ui_story_5046_50460501_83_dialog_content = "고마워요, 선생님!",
  ui_story_5046_50460501_84_dialog_content = "꼭 임무를 완수하고 선생님의 기대에 부응할게요!",
  ui_story_5046_50460501_85_dialog_content = "<color=#e8d9bb>움브라톤 교외</color>",
  ui_story_5046_50460501_86_dialog_content = "이 숲에서 가장 키가 큰 단풍나무는 저 앞에 있어.",
  ui_story_5046_50460501_87_dialog_content = "도착한 거야?",
  ui_story_5046_50460501_88_dialog_content = "숲속 길은 걷기 힘드니까 넘어지지 않게...",
  ui_story_5046_50460501_89_dialog_content = "으앗!",
  ui_story_5046_50460501_90_dialog_content = "...조심해.",
  ui_story_5046_50460501_91_dialog_content = "으아아앗! 아파라!",
  ui_story_5046_50460501_92_dialog_content = "앉아.",
  ui_story_5046_50460501_93_dialog_content = "괘, 괜찮아. 별로 안 심해...",
  ui_story_5046_50460501_94_dialog_content = "앉으라고.",
  ui_story_5046_50460501_95_dialog_content = "(엄청난 위압감이다... 거절할 수 없겠어...)",
  ui_story_5046_50460501_96_dialog_content = "그, 그래. 그럼 잠깐만 앉을게.",
  ui_story_5046_50460501_97_dialog_content = "바지 걷어.",
  ui_story_5046_50460501_98_dialog_content = "...무슨 말이야?",
  ui_story_5046_50460501_99_dialog_content = "풀어줄게.",
  ui_story_5046_50460501_100_dialog_content = "별로 안 아프다니까... 으앗! 내, 내가 걷을 테니까 됐어!",
  ui_story_5046_50460501_101_dialog_content = "이, 이 정도면 돼?",
  ui_story_5046_50460501_102_dialog_content = "그래. 여기쯤이겠지. 누르면 아프냐?",
  ui_story_5046_50460501_103_dialog_content = "거긴 별로 안 아파. 그나저나 너 손 되게 뜨겁네! 숲은 꽤 쌀쌀한데.",
  ui_story_5046_50460501_104_dialog_content = "난 체온이 높아. 추우면 가까이 붙어.",
  ui_story_5046_50460501_105_dialog_content = "(하티는 겉보기엔 쌀쌀맞아 보이는데, 앉았을 때 귀가 떨리는 게 왠지 보들보들해 보여.)",
  ui_story_5046_50460501_106_dialog_content = "(그리고 꽤 좋은 녀석이잖아. 넘어질까 봐 주의도 주고, 발목 삐었다고 풀어도 주고...)",
  ui_story_5046_50460501_107_dialog_content = "음? 뭐지?",
  ui_story_5046_50460501_108_dialog_content = "아, 아무것도 아니야!",
  ui_story_5046_50460501_109_dialog_content = "약속한 시간까지 조금 남았으니까 여기서 잠깐 쉬자.",
  ui_story_5046_50460501_110_dialog_content = "그래.",
  ui_story_5046_50460501_111_dialog_content = "......",
  ui_story_5046_50460501_112_dialog_content = "......",
  ui_story_5046_50460501_113_dialog_content = "(어, 어색하네... 뭐라도 얘기할까...)",
  ui_story_5046_50460501_114_dialog_content = "저기, 혹시 너희 어머니에 대해 말해줄 수 있어?",
  ui_story_5046_50460501_115_dialog_content = "따, 딱히 무슨 의도가 있는 건 아니야!",
  ui_story_5046_50460501_116_dialog_content = "우리 어머니는 내가 태어난 지 얼마 안 돼서 내 곁을 떠났거든.\n심지어 난 어머니 모습도 본 적이 없어...",
  ui_story_5046_50460501_117_dialog_content = "......",
  ui_story_5046_50460501_118_dialog_content = "이, 이야기하고 싶지 않으면 안 해도 괜찮아!",
  ui_story_5046_50460501_119_dialog_content = "......",
  ui_story_5046_50460501_120_dialog_content = "사실 네가 잃어버린 기억을 되찾고 싶은 마음은 충분히 이해할 수 있어.",
  ui_story_5046_50460501_121_dialog_content = "......",
  ui_story_5046_50460501_122_dialog_content = "지금까지 날 키워준 건 스카이워커호라는 콜로서스거든.",
  ui_story_5046_50460501_123_dialog_content = "하지만 스카이워커는 그냥 콜로서스가 아니라, 내 좋은 친구이자 선생님이야.",
  ui_story_5046_50460501_124_dialog_content = "오랜 시간 동안 스카이워커는 내 곁에 함께 있어 줬어.\n바깥세상의 지식도 가르쳐 줬고, 내가 갑갑하지 않게 나와 이야기도 나눠줬어.",
  ui_story_5046_50460501_125_dialog_content = "근데 지금 스카이워커는 날 기억하지 못하게 됐어.",
  ui_story_5046_50460501_126_dialog_content = "기억을 잃은 건가?",
  ui_story_5046_50460501_127_dialog_content = "날 구하는 대신 모든 기억을 잃었어.\n그래서 지금 난 스카이워커의 기억을 되찾을 방법을 찾고 있어.",
  ui_story_5046_50460501_128_dialog_content = "그렇게 보면 그림 말이 맞는 것 같아. 우린 비슷한 점이 있어.",
  ui_story_5046_50460501_129_dialog_content = "둘 다 기억을 찾기 위해 노력하고 있잖아.",
  ui_story_5046_50460501_130_dialog_content = "그래서 난 네 마음을 잘 알아. 네가 얼른 어머니에 대한 기억을 되찾길 바랄게.",
  ui_story_5046_50460501_131_dialog_content = "......",
  ui_story_5046_50460501_132_dialog_content = "그 스카이워커호의 기억을 찾는데 내가 도울 일이 있다면 얼마든지 말해.",
  ui_story_5046_50460501_133_dialog_content = "날 도와주려면 먼저 네 혐의부터 풀어야지!",
  ui_story_5046_50460501_134_dialog_content = "펜던트를 되찾고 나면 모두에게 제대로 해명하자. 알았지?",
  ui_story_5046_50460501_135_dialog_content = "쳇... 귀찮아.",
  ui_story_5046_50460501_136_dialog_content = "귀찮아도 해야지!",
  ui_story_5046_50460501_137_dialog_content = "알겠어.",
  ui_story_5046_50460501_138_dialog_content = "약속이야!",
  ui_story_5046_50460501_139_dialog_content = "캬악──!",
  ui_story_5046_50460501_140_dialog_content = "암귀들이 모여들고 있어. 수도 많아...",
  ui_story_5046_50460501_141_dialog_content = "크오오──!",
  ui_story_5046_50460501_142_dialog_content = "조심해.",
  ui_story_5046_50460501_143_dialog_content = "흥, PlayerName 너, 왜 그렇게 약한 거지?",
  ui_story_5046_50460501_144_dialog_content = "아이테르는 싸울 수 없다고!",
  ui_story_5046_50460501_145_dialog_content = "정말 약하네.",
  ui_story_5046_50460501_146_dialog_content = "무시하지 마. 네 왼쪽에서 암귀가 오고 있어!",
  ui_story_5046_50460501_147_dialog_content = "구오오오──!",
  ui_story_5046_50460501_148_dialog_content = "이거나 받아라!",
  ui_story_5046_50460501_149_dialog_content = "어때! 난 전투 능력은 없지만, 지휘 능력은 백야성 공주도 인정했을 정도라고!",
  ui_story_5046_50460501_150_dialog_content = "그럼 내 뒤에 숨어서 지휘에 집중해!",
  ui_story_5046_50460502_1_dialog_content = "안 돼, 암귀가 너무 많아...",
  ui_story_5046_50460502_2_dialog_content = "하아... 하아...",
  ui_story_5046_50460502_3_dialog_content = "이런 데서 쓰러질 순 없어...",
  ui_story_5046_50460502_4_dialog_content = "그어억...",
  ui_story_5046_50460502_5_dialog_content = "또 온다!",
  ui_story_5046_50460502_6_dialog_content = "젠장! 이 방법밖에 없는 건가...",
  ui_story_5046_50460502_7_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5046_50460502_8_dialog_content = "크아아아아!",
  ui_story_5046_50460502_9_dialog_content = "우와! 암귀가... 다 타버렸어!",
  ui_story_5046_50460502_10_dialog_content = "주변에 더는 암귀의 기운은 안 느껴져.",
  ui_story_5046_50460502_11_dialog_content = "하아... 하아...",
  ui_story_5046_50460502_12_dialog_content = "크윽!",
  ui_story_5046_50460502_13_dialog_content = "너... 결국 이 힘을 쓰는구나...",
  ui_story_5046_50460502_14_dialog_content = "킥킥킥...",
  ui_story_5046_50460502_15_dialog_content = "결국... 네가 그렇게 싫어하는 모습이 됐어...",
  ui_story_5046_50460502_16_dialog_content = "엄마는... 그래서 우릴 떠난 거야...",
  ui_story_5046_50460502_17_dialog_content = "닥쳐! 닥치라고!",
  ui_story_5046_50460502_18_dialog_content = "하티?! 왜 그래?!",
  ui_story_5046_50460502_19_dialog_content = "(하티가 눈을 감고 바닥에서 발버둥 치고 있어... 엄청 괴로워 보이잖아...)",
  ui_story_5046_50460502_20_dialog_content = "닥치라고 했잖아!",
  ui_story_5046_50460502_21_dialog_content = "엄마... 난 나쁜 애 아니야... 아니라고...",
  ui_story_5046_50460502_22_dialog_content = "(엄마? 설마 과거의 기억에 빠진 건가?)",
  ui_story_5046_50460502_23_dialog_content = "(이대론 안 돼! 감응해서 하티를 도와야겠어!)",
  ui_story_5046_50460502_24_dialog_content = "미안, 하티... 멋대로 네 기억을 볼 생각은 없었지만...",
  ui_story_5046_50460502_25_option_content = "(강제 감응!)",
  ui_story_5046_50460502_26_dialog_content = "(여기가 어디지?)",
  ui_story_5046_50460502_27_dialog_content = "엄마! 옷에 도깨비바늘이 붙어 있어. 내가 떼 줄게.",
  ui_story_5046_50460502_28_dialog_content = "고마워, 하티.",
  ui_story_5046_50460502_29_dialog_content = "하티는 정말 착하구나.",
  ui_story_5046_50460502_30_dialog_content = "헤헤...",
  ui_story_5046_50460502_31_dialog_content = "진짜 오랜만에 엄마랑 밖에서 논 것 같아.",
  ui_story_5046_50460502_32_dialog_content = "(어렸을 때의 하티인가? 저건 하티네 어머니?)",
  ui_story_5046_50460502_33_dialog_content = "......",
  ui_story_5046_50460502_34_dialog_content = "미안해, 하티.",
  ui_story_5046_50460502_35_dialog_content = "왜 엄마가 미안해? 엄마는 잘못한 게 없잖아.",
  ui_story_5046_50460502_36_dialog_content = "아니... 엄마가 나빴어.",
  ui_story_5046_50460502_37_dialog_content = "엄마는 잘못 없어...",
  ui_story_5046_50460502_38_dialog_content = "넌 밖에서 자유롭게 놀아야 하는데, 어쩌다 이렇게...",
  ui_story_5046_50460502_39_dialog_content = "펜리르... 이런 내 선택이 맞는 건가요...",
  ui_story_5046_50460502_40_dialog_content = "엄마, 울어...? 나 때문에...?",
  ui_story_5046_50460502_41_dialog_content = "그럼 나 이제부터 밖에서 안 놀게...",
  ui_story_5046_50460502_42_dialog_content = "아니야, 엄마는 괜찮아... 자, 재미있게 놀자!",
  ui_story_5046_50460502_43_dialog_content = "엄마가 눈을 감고 셋을 셀게. 그리고 하티를 잡을 거야!",
  ui_story_5046_50460502_44_dialog_content = "응!",
  ui_story_5046_50460502_45_dialog_content = "셋...",
  ui_story_5046_50460502_46_dialog_content = "그어어...",
  ui_story_5046_50460502_47_dialog_content = "(시커먼 녀석이 엄마한테 가고 있어...)",
  ui_story_5046_50460502_48_dialog_content = "둘...",
  ui_story_5046_50460502_49_dialog_content = "(왠지 엄마를 해치려는 것 같아...!)",
  ui_story_5046_50460502_50_dialog_content = "하나...",
  ui_story_5046_50460502_51_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5046_50460502_52_dialog_content = "!!!",
  ui_story_5046_50460502_53_dialog_content = "하티?!",
  ui_story_5046_50460502_54_dialog_content = "엄마! 쟨 나쁜 녀석이야!",
  ui_story_5046_50460502_55_dialog_content = "하티가 불덩이로 만들 거야!",
  ui_story_5046_50460502_56_dialog_content = "에잇!",
  ui_story_5046_50460502_57_dialog_content = "너... 엄마가 불꽃은 쓰면 안 된다고 했잖아!",
  ui_story_5046_50460502_58_dialog_content = "왜 말을 안 듣는 거니!",
  ui_story_5046_50460502_59_dialog_content = "그치만... 엄마가...",
  ui_story_5046_50460502_60_dialog_content = "당장 엄마랑 집으로 돌아가!",
  ui_story_5046_50460502_61_dialog_content = "훌쩍... 왜 그래...",
  ui_story_5046_50460502_62_dialog_content = "불장난하면... 엄마 나 싫어...?",
  ui_story_5046_50460502_63_dialog_content = "(엄마는 하티를 싫어해... 불꽃을 싫어해...)",
  ui_story_5046_50460502_64_dialog_content = "(하티는 나쁜 아이야...)",
  ui_story_5046_50460502_65_dialog_content = "(나쁜 아이야...)",
  ui_story_5046_50460502_66_dialog_content = "(내가... 나쁜 아이?)",
  ui_story_5046_50460502_67_dialog_content = "(아니야! 하티는 나쁜 아이가 아니야!)",
  ui_story_5046_50460502_68_dialog_content = "(소중한 사람을 지키기 위해 힘을 썼을 뿐이잖아. 비록 그 힘을 어머니가 인정하진 않았지만...)",
  ui_story_5046_50460502_69_dialog_content = "(그렇다고 해서 그게 하티가 나쁜 아이라는 뜻은 아니라고!)",
  ui_story_5046_50460502_70_dialog_content = "(하티... 나쁜 아이가 아니야?)",
  ui_story_5046_50460502_71_dialog_content = "(너희 어머니는 분명히 다른 고민 때문에 그러셨을 거야...)",
  ui_story_5046_50460502_72_dialog_content = "(하티가 어머니를 지키려고 불꽃의 힘을 사용하는 모습은 정말 멋졌어!)",
  ui_story_5046_50460502_73_dialog_content = "(아까 날 지키려고 불꽃을 사용했던 것도 그래! 정말 멋있었다고!)",
  ui_story_5046_50460502_74_dialog_content = "(하티는 아주 착한 아이야!)",
  ui_story_5046_50460502_75_dialog_content = "(내가... 착한 아이라고?)",
  ui_story_5046_50460502_76_dialog_content = "(그래, 하티는 착해. 자, 이제 마음을 가라앉히고 천천히 눈을 뜨는 거야...)",
  ui_story_5046_50460502_77_dialog_content = "......",
  ui_story_5046_50460502_78_dialog_content = "PlayerName?",
  ui_story_5046_50460502_79_dialog_content = "응, 이제 괜찮아?",
  ui_story_5046_50460502_80_dialog_content = "응...",
  ui_story_5046_50460502_81_dialog_content = "미안, 곤란하게 만들었네.",
  ui_story_5046_50460502_82_dialog_content = "사과는 오히려 내가 해야지.",
  ui_story_5046_50460502_83_dialog_content = "네 허락도 없이 감응 능력으로 네 기억에 들어갔으니까...",
  ui_story_5046_50460502_84_dialog_content = "그래도 너무 기분 나빠하지 않았으면 좋겠어!",
  ui_story_5046_50460502_85_dialog_content = "방금 전엔... 네가 없었으면...",
  ui_story_5046_50460502_86_dialog_content = "난 아마 완전히 이성을 잃었을 거야.",
  ui_story_5046_50460502_87_dialog_content = "고마워.",
  ui_story_5046_50460502_88_dialog_content = "갑자기 그렇게 착하게 나오니까 오히려 어색한데 말이지...",
  ui_story_5046_50460502_89_dialog_content = "크흠, 이제 시간이 다 됐어. 얼른 단풍나무가 있는 곳으로 가자.",
  ui_story_5046_50460502_90_dialog_content = "이번 일이 끝난 뒤에도 기억을 되찾는 데 내 도움이 필요해진다면...",
  ui_story_5046_50460502_91_dialog_content = "저기... 그땐 콜로서스로 날 찾아와.",
  ui_story_5046_50460502_92_dialog_content = "알겠어.",
  ui_story_5046_50460502_93_dialog_content = "그리고 약속해. 제대로 사람들한테 상황을 설명하고 혐의를 벗는 거야...",
  ui_story_5046_50460502_94_dialog_content = "안 그러면 날 찾아오는 것보다 누가 널 잡아다 현상금을 타는 게 더 빠를 것 같으니까...",
  ui_story_5046_50460502_95_dialog_content = "약속할게.",
  ui_story_5046_50460502_96_dialog_content = "정말이지?",
  ui_story_5046_50460502_97_dialog_content = "그래.",
  ui_story_5046_50460601_1_dialog_content = "(아침에 백야성의 경비병들을 고아원에 보냈지만, 하멜 씨는 쫓아내지 않았어요.)",
  ui_story_5046_50460601_2_dialog_content = "(오히려 경비병들을 데리고 움브라톤을 나와 이 숲으로 왔죠...)",
  ui_story_5046_50460601_3_dialog_content = "(게다가 지금 PlayerName 씨와 하티가 나타나서 양쪽이 싸우기 시작했어요...)",
  ui_story_5046_50460601_4_dialog_content = "(하지만 이 경비병들의 전투 방식은... 백야성의 것과는 달라요.\n입고 있는 건 분명히 백야성 경비병의 제복인데...)",
  ui_story_5046_50460601_5_dialog_content = "(대체 뭐가 어떻게 된 걸까요...?)",
  ui_story_5046_50460601_6_dialog_content = "(지금 막으려고 나서 봤자 아무 소용도 없겠죠.\n역시 여기 숨어서 상태를 지켜보는 게 좋겠어요.)",
  ui_story_5046_50460601_7_dialog_content = "하아... 하아... 이래도 죽질 않는 거냐.",
  ui_story_5046_50460601_8_dialog_content = "하멜 씨?! 대체 무슨 말씀이시죠? 그리고 왜 여기 오신 건데요?",
  ui_story_5046_50460601_9_dialog_content = "제나스 씨는 어디 있죠?\n...설마 편지가 제나스 씨한테 안 간 건가?",
  ui_story_5046_50460601_10_dialog_content = "가만히 앉아서 너한테 목숨을 빼앗기느니, 내가 먼저 나서는 편이 낫겠지.",
  ui_story_5046_50460601_11_dialog_content = "안드레, 페르민, 칼로타, 전부 네가 죽인 거냐?",
  ui_story_5046_50460601_12_dialog_content = "고아원 일을 가지고 우리한테 복수하려는 거겠지?",
  ui_story_5046_50460601_13_dialog_content = "넌 그날 리허설에서 우리 둘을 한 번에 없애려고 했겠지. 내 말이 틀렸나?",
  ui_story_5046_50460601_14_dialog_content = "아쉽지만 네 계획은 실패했다.",
  ui_story_5046_50460601_15_dialog_content = "난 네가 말한 사람들이 누군지 모른다. 리허설 날은 그냥 지나가는 중이었고.",
  ui_story_5046_50460601_16_dialog_content = "아직도 시치미를 떼는 거냐! 넌 분명히 우릴... 크억!",
  ui_story_5046_50460601_17_dialog_content = "조심해!",
  ui_story_5046_50460601_18_dialog_content = "(하멜 씨가 쓰러졌어요! 하티가 사람을 죽인 건가요?!)",
  ui_story_5046_50460601_19_dialog_content = "하멜 씨?! 정신 차리세요!",
  ui_story_5046_50460601_20_dialog_content = "이미 죽었어.",
  ui_story_5046_50460601_21_dialog_content = "하티 켈피! 당신을 살인 혐의로 체포하겠어요!\n지금 즉시 저와 움브라톤으로 가서 심문을 받으세요!",
  ui_story_5046_50460601_22_dialog_content = "크리스틴? 네가 여긴 왜...",
  ui_story_5046_50460601_23_dialog_content = "이 사람은 내가 죽인 게 아니야.",
  ui_story_5046_50460601_24_dialog_content = "물론 그렇게 말하겠죠.",
  ui_story_5046_50460601_25_dialog_content = "하티 말은 진짜야. 내가 증명할게. 하멜 씨는 갑자기 혼자서 쓰러졌어...",
  ui_story_5046_50460601_26_dialog_content = "PlayerName 씨, 왜 살인범을 감싸려고 하시는 거죠?",
  ui_story_5046_50460601_27_dialog_content = "지금 손에 도끼도 들고 있잖아요. 흉기도 명확한데...",
  ui_story_5046_50460601_28_dialog_content = "내 말은 진짜라고!",
  ui_story_5046_50460601_29_dialog_content = "두 사람이 반박하고 싶다면, 저와 함께 심판소로 가서 하세요.",
  ui_story_5046_50460601_30_dialog_content = "비록 전 견습 심판관일 뿐이지만, 그래도 정의를 실현해야 해요.\n눈앞에서 벌어진 범죄를 못 본 척할 순 없어요.",
  ui_story_5046_50460601_31_dialog_content = "아니, 난 아직 너랑 같이 갈 순 없어.",
  ui_story_5046_50460601_32_dialog_content = "동행을 거부하면 죄가 더 무거워질 뿐이에요.",
  ui_story_5046_50460601_33_dialog_content = "좋을 대로 생각해.",
  ui_story_5046_50460601_34_dialog_content = "둘 다 좀 진정해!",
  ui_story_5046_50460601_35_dialog_content = "크리스틴! 괜찮습니까?",
  ui_story_5046_50460601_36_dialog_content = "흥, 가면 쓴 자식, 이제야 나타났군.",
  ui_story_5046_50460601_37_dialog_content = "이, 이건... 하멜 씨가 아닙니까?!",
  ui_story_5046_50460601_38_dialog_content = "하티? 아무래도 하멜 씨를 죽인 범인은 당신 같군요. 크리스틴, 체포하세요.",
  ui_story_5046_50460601_39_dialog_content = "자, 잠깐만요! 진짜로 하티가 한 짓이 아니에요!",
  ui_story_5046_50460601_40_dialog_content = "싸울 건가? 얼마든지!",
  ui_story_5046_50460601_41_dialog_content = "PlayerName 씨, 거기 있으면 위험해요! 빨리 이쪽으로 오세요!",
  ui_story_5046_50460601_42_dialog_content = "받아라!",
  ui_story_5046_50460601_43_dialog_content = "느려.",
  ui_story_5046_50460601_44_dialog_content = "<color=#e8d9bb>툭──</color>",
  ui_story_5046_50460601_45_dialog_content = "가면이...",
  ui_story_5046_50460601_46_dialog_content = "그 얼굴...?!",
  ui_story_5046_50460601_47_dialog_content = "넌 누구야...?! 대체 누구냐고!",
  ui_story_5046_50460601_48_dialog_content = "하티! 왜 그래?!",
  ui_story_5046_50460601_49_dialog_content = "나, 난... 으윽... 으으으...!",
  ui_story_5046_50460601_50_dialog_content = "<color=#e8d9bb>「그날...」</color>",
  ui_story_5046_50460601_51_dialog_content = "<color=#e8d9bb>「난 저 얼굴을 봤어.」</color>",
  ui_story_5046_50460601_52_dialog_content = "<color=#e8d9bb>「그날...」</color>",
  ui_story_5046_50460601_53_dialog_content = "<color=#e8d9bb>「어머니한테... 무슨 일이 있었지?」</color>",
  ui_story_5046_50460601_54_dialog_content = "으아아아악!",
  ui_story_5046_50460601_55_dialog_content = "하티?! 하티!",
  ui_story_5046_50460601_56_dialog_content = "선생님! 뭔가 이상해요!",
  ui_story_5046_50460601_57_dialog_content = "아우우우우우──!",
  ui_story_5046_50460601_58_dialog_content = "하티! 하티! 내 목소리 들려?!",
  ui_story_5046_50460601_59_dialog_content = "정신 차려!",
  ui_story_5046_50460601_60_dialog_content = "크윽!",
  ui_story_5046_50460601_61_dialog_content = "<color=#e8d9bb>화르륵──</color>",
  ui_story_5046_50460601_62_dialog_content = "모습이 바뀌었는데요...?! 게다가 몸에서 불이 나고 있어요!",
  ui_story_5046_50460601_63_dialog_content = "조심하세요! 크리스틴! 뒤로 물러나세요!",
  ui_story_5046_50460601_64_dialog_content = "크아아아!",
  ui_story_5046_50460601_65_dialog_content = "하티!",
  ui_story_5046_50460601_66_dialog_content = "(하티의 지금 모습... 기억 속에서 본 마음속 어둠과 똑같아...)",
  ui_story_5046_50460601_67_dialog_content = "(설마, 마음속 어둠에 침식된 건가?! 안 돼! 내가 깨워줘야 해!)",
  ui_story_5046_50460601_68_dialog_content = "PlayerName 씨! 이쪽으로 오세요! 하티는 지금 매우 위험한 상태예요!",
  ui_story_5046_50460601_69_dialog_content = "괜찮아! 하티가 날 해치진 않을 거야! 지금 하티는 내가 필요해!",
  ui_story_5046_50460601_70_dialog_content = "하티, 진정해!",
  ui_story_5046_50460601_71_dialog_content = "아우우우!",
  ui_story_5046_50460601_72_dialog_content = "소용없어요! 무슨 말을 해도 지금 저 사람은 못 들을 거예요!",
  ui_story_5046_50460601_73_dialog_content = "빨리 이쪽으로 오세요! PlayerName 씨!",
  ui_story_5046_50460601_74_dialog_content = "PlayerName...",
  ui_story_5046_50460601_75_dialog_content = "...방금 날 부른 거야?!",
  ui_story_5046_50460601_76_dialog_content = "안 돼, 이대로 내버려 둘 순 없어!",
  ui_story_5046_50460601_77_dialog_content = "(어떻게 하면 내 목소리가 닿을 수 있을까...?)",
  ui_story_5046_50460601_78_dialog_content = "(그래, 나한테는...)",
  ui_story_5046_50460601_79_option_content = "(강제 감응!)",
  ui_story_5046_50460601_80_dialog_content = "(하티! 진정해!)",
  ui_story_5046_50460601_81_dialog_content = "(PlayerName? 나... 저 남자 얼굴을 봤더니... 날 억제할 수 없게 돼버렸어...)",
  ui_story_5046_50460601_82_dialog_content = "(머리가 너무 아파... 으, 으아악!)",
  ui_story_5046_50460601_83_dialog_content = "(어떡하지... 대체 어떻게 해야...)",
  ui_story_5046_50460601_84_dialog_content = "(아무튼 우리 일단 여길 떠나자. 어디라도 좀 가서 진정해야 돼.)",
  ui_story_5046_50460601_85_dialog_content = "(우리... 같이?)",
  ui_story_5046_50460601_86_dialog_content = "(그래, 같이!)",
  ui_story_5046_50460601_87_dialog_content = "둘을 놓치면 안 됩니다! 크윽!",
  ui_story_5046_50460601_88_dialog_content = "선생님, 움직이지 마세요! 다치셨잖아요!",
  ui_story_5046_50460601_89_dialog_content = "PlayerName 씨는 어디로 갔죠?",
  ui_story_5046_50460601_90_dialog_content = "하티가 데려가 버렸어요...",
  ui_story_5046_50460601_91_dialog_content = "제길... 또 놓치다니!",
  ui_story_5046_50460601_92_dialog_content = "...제 가면은 어디 있죠?",
  ui_story_5046_50460601_93_dialog_content = "제가 찾아드릴 테니까 선생님은 가만히 계세요!",
  ui_story_5046_50460601_94_dialog_content = "(선생님, 얼굴의 상처...)",
  ui_story_5046_50460601_95_dialog_content = "큰일이에요! 불이 났어요!",
  ui_story_5046_50460601_96_dialog_content = "아가씨! 아가씨가 아직 안에 있어요!",
  ui_story_5046_50460601_97_dialog_content = "아직 안에 사람이 있습니까?",
  ui_story_5046_50460601_98_dialog_content = "부탁드려요! 제발 크리스틴 아가씨를 좀 구해주세요!",
  ui_story_5046_50460601_99_dialog_content = "콜록콜록...",
  ui_story_5046_50460601_100_dialog_content = "아버님... 어머님... 어디 계세요...?",
  ui_story_5046_50460601_101_dialog_content = "아가씨!",
  ui_story_5046_50460601_102_dialog_content = "누...누구세요...?",
  ui_story_5046_50460601_103_dialog_content = "드디어 찾았군요. 무서워하지 않아도 됩니다. 제가 밖으로 모셔다드리겠습니다.",
  ui_story_5046_50460601_104_dialog_content = "아가씨, 무사하셨군요!",
  ui_story_5046_50460601_105_dialog_content = "난 괜찮아... 저기, 감사해요... 앗!",
  ui_story_5046_50460601_106_dialog_content = "얼굴에 상처가 심해요! 얼른 치료해야 해요!",
  ui_story_5046_50460601_107_dialog_content = "저 말입니까? 죄송합니다. 아가씨를 놀라게 해 버렸군요.",
  ui_story_5046_50460601_108_dialog_content = "미, 미안해요. 절 구하시느라...",
  ui_story_5046_50460601_109_dialog_content = "괜찮습니다. 아가씨께서 무사하면 된 겁니다.",
  ui_story_5046_50460601_110_dialog_content = "저기... 이름이...",
  ui_story_5046_50460601_111_dialog_content = "제나스라고 합니다.",
  ui_story_5046_50460601_112_dialog_content = "오늘부터 제가 아가씨의 가정교사를 맡게 되었습니다.",
  ui_story_5046_50460601_113_dialog_content = "정말 잘됐네요! 선생님!",
  ui_story_5046_50460601_114_dialog_content = "제가 몰락한 귀족임에도 불구하고 아버님께 기꺼이 추천해 주셔서 감사합니다.",
  ui_story_5046_50460601_115_dialog_content = "선생님은 귀족 출신이셨나요?",
  ui_story_5046_50460601_116_dialog_content = "네. 이것이 제 가문의 문장입니다.",
  ui_story_5046_50460601_117_dialog_content = "굉장히 특이한 문양이네요.",
  ui_story_5046_50460601_118_dialog_content = "이미 몰락한 가문입니다. 언급할 가치도 없지요.",
  ui_story_5046_50460601_119_dialog_content = "<color=#e8d9bb>「그 뒤로 선생님은 줄곧 제 곁에 계셨고, 절 가르치고 이끌어 주셨어요.」</color>",
  ui_story_5046_50460601_120_dialog_content = "<color=#e8d9bb>「그러던 중 선생님은 가정교사 일을 그만두고, 백야성에서 일을 하시게 됐어요.」</color>",
  ui_story_5046_50460601_121_dialog_content = "<color=#e8d9bb>「전 여명 아카데미를 졸업하고 백야성 심판소에 들어갔고, 계속 선생님을 따를 수 있었죠.」</color>",
  ui_story_5046_50460601_122_dialog_content = "선생님, 여기 가면이요.",
  ui_story_5046_50460601_123_dialog_content = "후...",
  ui_story_5046_50460601_124_dialog_content = "하티는 하멜 씨를 살해하고 다시 아이테르를 납치했습니다.",
  ui_story_5046_50460601_125_dialog_content = "지금 당장 하티가 도주한 쪽으로 경비병을 보내 추적을 강화해야 합니다.",
  ui_story_5046_50460601_126_dialog_content = "네, 선생님!",
  ui_story_5046_50460601_127_dialog_content = "크리스틴, 이번 사건은 여기서 손을 떼도록 하세요.",
  ui_story_5046_50460601_128_dialog_content = "네?",
  ui_story_5046_50460601_129_dialog_content = "이 사건은 앞으로 점점 더 위험해질 뿐입니다. 당신을 끌어들이고 싶지 않습니다.",
  ui_story_5046_50460601_130_dialog_content = "게다가 지난번 하멜 씨 건에서도 느꼈겠지만,\n경험이 적은 당신이 용의자를 상대하는 건 아직 어렵습니다.",
  ui_story_5046_50460601_131_dialog_content = "선생님, 이번 일련의 사건에 대해 지금 저보다 더 잘 아는 사람은 없어요.\n부디 제가 계속 도와드릴 수 있게 해 주세요!",
  ui_story_5046_50460601_132_dialog_content = "이미 결정한 일입니다. 이 사건은 저 혼자 처리하겠습니다.",
  ui_story_5046_50460601_133_dialog_content = "당신은 지금까지 얻은 정보를 정리하고, 백야성 심판소에 보고서를 제출하십시오.",
  ui_story_5046_50460601_134_dialog_content = "하지만 선생님...!",
  ui_story_5046_50460601_135_dialog_content = "그만하세요! 아무리 제가 모시는 아가씨라고 해도, 전 당신의 상관이기도 합니다.",
  ui_story_5046_50460601_136_dialog_content = "지시에 따라 주십시오!",
  ui_story_5046_50460601_137_dialog_content = "...네.",
  ui_story_5046_50460601_138_dialog_content = "조금 말이 거칠었습니다만, 이것도 모두 당신의 안전을 위해서입니다.",
  ui_story_5046_50460601_139_dialog_content = "먼저 돌아가세요.",
  ui_story_5046_50460601_140_dialog_content = "(처음 맡게 된 용의자 추적인데, 제가 다 망치고 말았네요.)",
  ui_story_5046_50460601_141_dialog_content = "(선생님은 사건에서 손을 떼라고 하셨지만, 그래도 진실이 뭔지는 꼭 밝혀내고 싶어요.)",
  ui_story_5046_50460601_142_dialog_content = "(게다가... 일련의 사건엔 아직도 의문점이 많이 있어요...)",
  ui_story_5046_50460601_143_dialog_content = "(하티가 방화범이라면, 왜 화재 현장에서 PlayerName 씨와 여자애를 구한 걸까요?)",
  ui_story_5046_50460601_144_dialog_content = "(그리고 방금도 왜 인질인 PlayerName 씨가 하티를 감싸고 도주를 도왔을까요?)",
  ui_story_5046_50460601_145_dialog_content = "(하멜 씨는 살해되기 전 「우리 둘」이라고 말했어요.\n하티가 노리는 다른 사람이 있다는 걸 알고 있다는 뜻이겠죠.)",
  ui_story_5046_50460601_146_dialog_content = "(그 사람이 누군지 알아낼 수 있다면, 하티의 다음 행방도 알 수 있을 거예요.)",
  ui_story_5046_50460601_147_dialog_content = "(선생님, 이번에야말로 증명해 보이겠어요. 전 더는 온실 속의 귀족 아가씨가 아니에요!)",
  ui_story_5046_50460601_148_dialog_content = "(반드시 제 능력으로 선생님께 힘이 될 거예요!)",
  ui_story_5046_50460701_1_dialog_content = "(으, 이불이 축축해. 괴로워...)",
  ui_story_5046_50460701_2_dialog_content = "(또 비가 새나? 저번 집은 이 정도는 아니었는데...)",
  ui_story_5046_50460701_3_dialog_content = "엄마, 엄마?",
  ui_story_5046_50460701_4_dialog_content = "(엄마가 잠들었나?)",
  ui_story_5046_50460701_5_dialog_content = "(엄마는 요즘 계속 외출하고 있어. 돌아오면 요리도 하고,\n집안일도 하고... 분명히 힘들 거야.)",
  ui_story_5046_50460701_6_dialog_content = "(나도 많이 컸잖아! 더는 엄마를 힘들게 하면 안 돼!)",
  ui_story_5046_50460701_7_dialog_content = "(이불은 내가 널자!)",
  ui_story_5046_50460701_8_dialog_content = "(엄마가 일어났을 때 내가 알아서 자기 일을 하는 걸 보면 분명히 기뻐할 거야!)",
  ui_story_5046_50460701_9_dialog_content = "(분명히 하티가 착한 아이라고 칭찬해 주겠지!)",
  ui_story_5046_50460701_10_dialog_content = "<color=#e8d9bb>휘이익──</color>",
  ui_story_5046_50460701_11_dialog_content = "(휴, 이렇게 걸어두면 되겠지? 엄마는 평소에 얼마나 걸어두더라?)",
  ui_story_5046_50460701_12_dialog_content = "(엄마가 일어나기 전까지 다 말랐으면 좋겠다!)",
  ui_story_5046_50460701_13_dialog_content = "이불아~ 이불아~ 빨리 말라!",
  ui_story_5046_50460701_14_dialog_content = "이불아~ 이불아~",
  ui_story_5046_50460701_15_dialog_content = "빨리 바짝 말라~!",
  ui_story_5046_50460701_16_dialog_content = "<color=#e8d9bb>화르륵──</color>",
  ui_story_5046_50460701_17_dialog_content = "으아앗!",
  ui_story_5046_50460701_18_dialog_content = "왜 멋대로 불이 나온 거야?!",
  ui_story_5046_50460701_19_dialog_content = "엄마가 보면 화낼 텐데!",
  ui_story_5046_50460701_20_dialog_content = "어, 얼른 꺼야지!",
  ui_story_5046_50460701_21_dialog_content = "하티?! 너 뭐 하는 거니?!",
  ui_story_5046_50460701_22_dialog_content = "히잉, 엄마!",
  ui_story_5046_50460701_23_dialog_content = "(엄마가 날 무서워하는 거 같아... 얼른 사과해야지!)",
  ui_story_5046_50460701_24_dialog_content = "미안... 난 그냥 이불 널려고 한 건데...",
  ui_story_5046_50460701_25_dialog_content = "이, 일부러 불을 낸 건 아니야... 불이 자기 마음대로...",
  ui_story_5046_50460701_26_dialog_content = "다친 곳은 없니?!",
  ui_story_5046_50460701_27_dialog_content = "응... 엄마... 나 정말 일부러 그런 거 아니야...",
  ui_story_5046_50460701_28_dialog_content = "일부러 엄마가 하지 말라는 일을 한 것도 아니야...",
  ui_story_5046_50460701_29_dialog_content = "잘 들어! 앞으로 다시는 그 힘을 쓰면 안 돼!",
  ui_story_5046_50460701_30_dialog_content = "알았니?!",
  ui_story_5046_50460701_31_dialog_content = "(엄마... 너무 무서워...)",
  ui_story_5046_50460701_32_dialog_content = "그치만 난 그냥 엄마를... 나 일부러 그런 거 아니야...",
  ui_story_5046_50460701_33_dialog_content = "으아아아아앙!",
  ui_story_5046_50460701_34_dialog_content = "넌 아직 그 힘을 잘 제어할 수 없어...",
  ui_story_5046_50460701_35_dialog_content = "그건 아주 강한 힘이란다. 그래서 조금만 실수해도 널 다치게 만들 거야...",
  ui_story_5046_50460701_36_dialog_content = "게다가 그 힘을 빼앗으려는 사람이 있어... 그럼 널 해칠지도 몰라...",
  ui_story_5046_50460701_37_dialog_content = "그러니까 다시는 그 힘을 쓰면 안 돼. 알겠어?!",
  ui_story_5046_50460701_38_dialog_content = "훌쩍... 알았어...",
  ui_story_5046_50460701_39_dialog_content = "(엄마...)",
  ui_story_5046_50460701_40_dialog_content = "<color=#e8d9bb>「엄마, 내 힘이 그렇게 무서워?」</color>",
  ui_story_5046_50460701_41_dialog_content = "<color=#e8d9bb>「엄마, 내가 그렇게 무서워?」</color>",
  ui_story_5046_50460701_42_dialog_content = "<color=#e8d9bb>「난 엄마가 제일 좋은데 어째서!」</color>",
  ui_story_5046_50460701_43_dialog_content = "으아아악!",
  ui_story_5046_50460701_44_dialog_content = "(엄마는... 하티가 필요 없어...)",
  ui_story_5046_50460701_45_dialog_content = "(하티는... 말을 안 들으니까...)",
  ui_story_5046_50460701_46_dialog_content = "난... 크윽... 엄마... 아...!",
  ui_story_5046_50460701_47_dialog_content = "하티, 정신 차려!",
  ui_story_5046_50460701_48_dialog_content = "(아무래도 기억 속에 갇혀버린 것 같아...)",
  ui_story_5046_50460701_49_dialog_content = "(마음속 어둠이 계속 하티의 귓가에 속삭이는 게 느껴져...)",
  ui_story_5046_50460701_50_dialog_content = "(하티가 마음속 어둠에 맞서지 않는 한, 계속 기억 속에 사로잡히고 말 거야...)",
  ui_story_5046_50460701_51_dialog_content = "(이대로 과거에 사로잡혀 깨어나지 못하면 큰일이야.)",
  ui_story_5046_50460701_52_dialog_content = "(내가 도와야 해!)",
  ui_story_5046_50460701_53_option_content = "(강제 감응!)",
  ui_story_5046_50460701_54_dialog_content = "(여긴... 하티의 집인가?)",
  ui_story_5046_50460701_55_dialog_content = "하티! 너 뭐 하는 거니!",
  ui_story_5046_50460701_56_dialog_content = "어, 엄마?",
  ui_story_5046_50460701_57_dialog_content = "지금 뭐 하는 거냐고 물어보잖아!",
  ui_story_5046_50460701_58_dialog_content = "그, 그냥 밖에 애들이 뭐 하고 노나 보려고...",
  ui_story_5046_50460701_59_dialog_content = "창문 닫아! 당장!",
  ui_story_5046_50460701_60_dialog_content = "그치만 나도 밖에 나가서 놀고 싶어...",
  ui_story_5046_50460701_61_dialog_content = "엄마가 몇 번이나 말했니? 또 말해야겠어?",
  ui_story_5046_50460701_62_dialog_content = "으...",
  ui_story_5046_50460701_63_dialog_content = "왜 밖에서 못 놀게 하는 건데!",
  ui_story_5046_50460701_64_dialog_content = "엄마는 맨날 날 지키기 위해서라고... 그래서 밖에서 놀면 안 된다고 하면서...",
  ui_story_5046_50460701_65_dialog_content = "정작 이유는 제대로 안 알려줬잖아!",
  ui_story_5046_50460701_66_dialog_content = "......",
  ui_story_5046_50460701_67_dialog_content = "이사 온 집은 엉망인 데다가 춥고! 아무것도 없어!",
  ui_story_5046_50460701_68_dialog_content = "그림책도 있잖아. 가서 책 읽어.",
  ui_story_5046_50460701_69_dialog_content = "벌써 다 해지게 읽었다구!",
  ui_story_5046_50460701_70_dialog_content = "책에 나오는 애들은 항상 같이 놀아. 친구네 집에도 놀러가고...",
  ui_story_5046_50460701_71_dialog_content = "엄마는 그림책 보여주면서 나한테 다른 사람들이랑 얘기하는 법도,\n물건 사는 법도, 남한테 고맙다고 하는 법도 가르쳐 줬어...",
  ui_story_5046_50460701_72_dialog_content = "......",
  ui_story_5046_50460701_73_dialog_content = "근데 하나도 해볼 수가 없잖아!",
  ui_story_5046_50460701_74_dialog_content = "왜냐면 엄마가 못 나가게 하니까!",
  ui_story_5046_50460701_75_dialog_content = "너한테 그것들을 가르쳐 준 건...",
  ui_story_5046_50460701_76_dialog_content = "엄마가 곁에 없을 때도 하티가 혼자서 잘 살아갈 수 있길 바라서야.",
  ui_story_5046_50460701_77_dialog_content = "왜 엄마가 곁에 없는데?",
  ui_story_5046_50460701_78_dialog_content = "......",
  ui_story_5046_50460701_79_dialog_content = "엄마... 왜 그렇게 슬픈 표정이야?",
  ui_story_5046_50460701_80_dialog_content = "누가 엄마 괴롭혔어?",
  ui_story_5046_50460701_81_dialog_content = "하티는 이제 다 컸어!",
  ui_story_5046_50460701_82_dialog_content = "엄마를 괴롭히는 나쁜 놈은 하티가 혼내줄 수 있어!",
  ui_story_5046_50460701_83_dialog_content = "이길 수 없어도... 하티가 전부 태워버릴 거야!",
  ui_story_5046_50460701_84_dialog_content = "!",
  ui_story_5046_50460701_85_dialog_content = "<color=#e8d9bb>찰싹──</color>",
  ui_story_5046_50460701_86_dialog_content = "어...엄마?",
  ui_story_5046_50460701_87_dialog_content = "엄마가 그러면 안 된다고 한 거 벌써 잊었니?!",
  ui_story_5046_50460701_88_dialog_content = "엄마가... 날 때렸어...?",
  ui_story_5046_50460701_89_dialog_content = "왜 안 되는 건데?!",
  ui_story_5046_50460701_90_dialog_content = "왜... 왜! 도대체 왜!",
  ui_story_5046_50460701_91_dialog_content = "(왜... 안 되는 거냐고...)",
  ui_story_5046_50460701_92_dialog_content = "<color=#e8d9bb>화르륵──</color>",
  ui_story_5046_50460701_93_dialog_content = "?!",
  ui_story_5046_50460701_94_dialog_content = "으아앗!",
  ui_story_5046_50460701_95_dialog_content = "하티, 너...!",
  ui_story_5046_50460701_96_dialog_content = "어, 엄마? 내... 몸에서... 불꽃이...",
  ui_story_5046_50460701_97_dialog_content = "엄마도 펜던트가 있고, 하티도 펜던트가 있네.",
  ui_story_5046_50460701_98_dialog_content = "이건 뭐에 쓰는 거야?",
  ui_story_5046_50460701_99_dialog_content = "이 펜던트는 아주 중요한 물건이야.",
  ui_story_5046_50460701_100_dialog_content = "꼭 소중하게 간직해야 돼.",
  ui_story_5046_50460701_101_dialog_content = "응!",
  ui_story_5046_50460701_102_dialog_content = "근데 왜 중요한데?",
  ui_story_5046_50460701_103_dialog_content = "......이 펜던트가...... 중요한 건......",
  ui_story_5046_50460701_104_dialog_content = "......몸에 지니고 있으면......",
  ui_story_5046_50460701_105_dialog_content = "(이 부분 기억은 흐릿해...)",
  ui_story_5046_50460701_106_dialog_content = "엄마, 뭐 해? 왜 그렇게 긴장했어?",
  ui_story_5046_50460701_107_dialog_content = "오늘 내 생일이지? 딸기 케이크 먹고 싶어!",
  ui_story_5046_50460701_108_dialog_content = "...하티... 잘 들어...",
  ui_story_5046_50460701_109_dialog_content = "이제 시간이 없어. 더 얘기할 시간도 없어.",
  ui_story_5046_50460701_110_dialog_content = "펜던트를 잘 가지고 있어. 절대 잃어버리면 안 돼!",
  ui_story_5046_50460701_111_dialog_content = "엄마, 무슨 소리 하는 거야? 잘 모르겠어.",
  ui_story_5046_50460701_112_dialog_content = "나쁜 사람... 나쁜 사람이 올 거야.",
  ui_story_5046_50460701_113_dialog_content = "나쁜 사람? 누가 나쁜 사람인데?",
  ui_story_5046_50460701_114_dialog_content = "엄마, 나쁜 사람이 누구야?",
  ui_story_5046_50460701_115_dialog_content = "엄마... 뭐 하는 거야? 엄마?!",
  ui_story_5046_50460701_116_dialog_content = "으아아아──!",
  ui_story_5046_50460701_117_dialog_content = "<color=#e8d9bb>「엄마, 나쁜 사람이 누구야?」</color>",
  ui_story_5046_50460701_118_dialog_content = "<color=#e8d9bb>「나쁜 사람이 오는데, 왜 나한테...」</color>",
  ui_story_5046_50460701_119_dialog_content = "<color=#e8d9bb>「설마 엄마는 내가 나쁜 사람이라고 생각한 거야?」</color>",
  ui_story_5046_50460701_120_dialog_content = "<color=#e8d9bb>「그래서 날 태워 죽이려고 한 거야...?」</color>",
  ui_story_5046_50460701_121_dialog_content = "<color=#e8d9bb>「내 말이 맞지? 엄마...」</color>",
  ui_story_5046_50460701_122_dialog_content = "(이제 알았구나... 하티...)",
  ui_story_5046_50460701_123_dialog_content = "(엄마가 말했던 나쁜 사람은... 바로 너야...)",
  ui_story_5046_50460701_124_dialog_content = "(이 힘을 싫어했고... 이 힘에 삼켜져 버린... 우릴 싫어했던 거야...)",
  ui_story_5046_50460701_125_dialog_content = "우리...?",
  ui_story_5046_50460701_126_dialog_content = "하티! 하티!",
  ui_story_5046_50460701_127_dialog_content = "누구...?",
  ui_story_5046_50460701_128_dialog_content = "나야! PlayerName!",
  ui_story_5046_50460701_129_dialog_content = "PlayerName? 너도... 날 버릴 거야?",
  ui_story_5046_50460701_130_dialog_content = "(PlayerName... 네가 좋아하는 PlayerName...)",
  ui_story_5046_50460701_131_dialog_content = "(녀석도 널 버릴 거야...)",
  ui_story_5046_50460701_132_dialog_content = "(자신의 불을 제어하지도 못하고... 여기저기 불을 붙이고...)",
  ui_story_5046_50460701_133_dialog_content = "(엄마를 화나게 만들어서... 엄마한테 버림받은 하티를... 누가 좋아해 주겠어?)",
  ui_story_5046_50460701_134_dialog_content = "엄마는 날 사랑하지 않는구나... 아무도 날 사랑하지 않아...",
  ui_story_5046_50460701_135_dialog_content = "아니야!",
  ui_story_5046_50460701_136_dialog_content = "하티가 그 힘을 쓴 건 언제나 소중한 사람을 위해서였어!",
  ui_story_5046_50460701_137_dialog_content = "암귀가 어머니를 해치지 못하게 막고... 어머니가 푹 쉴 수 있도록 이불을 말리고...",
  ui_story_5046_50460701_138_dialog_content = "암귀에 전혀 맞설 수 없는 날 구해주고...",
  ui_story_5046_50460701_139_dialog_content = "소중한 사람들을 위해서 허락되지 않은 힘을 쓴 거잖아...",
  ui_story_5046_50460701_140_dialog_content = "그런 하티는 정말 마음씨 좋고, 다른 사람의 마음을 아는 착한 아이야!",
  ui_story_5046_50460701_141_dialog_content = "난 그런 하티가 좋아!",
  ui_story_5046_50460701_142_dialog_content = "너희 어머니도 분명히 그랬을 거야!",
  ui_story_5046_50460701_143_dialog_content = "하티의 어머니는! 귀엽고 착한 하티를 진심으로 사랑했을 거라고!",
  ui_story_5046_50460701_144_dialog_content = "어머니가... 날 사랑해?",
  ui_story_5046_50460701_145_dialog_content = "(그 녀석은... 널 속이고 있어...)",
  ui_story_5046_50460701_146_dialog_content = "속이지 않아!",
  ui_story_5046_50460701_147_dialog_content = "너야말로 계속 하티를 괴롭히고 있잖아! 나쁜 놈은 오히려 너야!",
  ui_story_5046_50460701_148_dialog_content = "하티, 같이 녀석을 쓰러트리자!",
  ui_story_5046_50460702_1_dialog_content = "내가... 이겼어?",
  ui_story_5046_50460702_2_dialog_content = "(네가... 이겼다고...?)",
  ui_story_5046_50460702_3_dialog_content = "(아니... 넌 아직 여기 있고... 나도 아직 여기 있어...)",
  ui_story_5046_50460702_4_dialog_content = "(넌 아직... 자신을... 정말로 받아들이지... 못했어...)",
  ui_story_5046_50460702_5_dialog_content = "넌... 대체 뭐야?",
  ui_story_5046_50460702_6_dialog_content = "(우린... 다시 만나게 될 거야...)",
  ui_story_5046_50460702_7_dialog_content = "하티!",
  ui_story_5046_50460702_8_dialog_content = "하아... 하아...",
  ui_story_5046_50460702_9_dialog_content = "PlayerName...?",
  ui_story_5046_50460702_10_dialog_content = "다행이야... 깨어났구나.",
  ui_story_5046_50460702_11_dialog_content = "......",
  ui_story_5046_50460702_12_dialog_content = "고마워, 네가 또 날 구했어.",
  ui_story_5046_50460702_13_dialog_content = "고마워할 거 없어. 너도 날 암귀한테서 구해줬잖아.",
  ui_story_5046_50460702_14_dialog_content = "......",
  ui_story_5046_50460702_15_dialog_content = "가면 쓴 자식한테서 펜던트를 되찾고 싶은 건 그게 우리 어머니 물건이라서야.",
  ui_story_5046_50460702_16_dialog_content = "어렸을 때부터 난 다른 애들과는 달랐어.\n항상 멀리서 창문 너머로 다른 애들을 보기만 하고, 밖으로 나갈 수 없었어.",
  ui_story_5046_50460702_17_dialog_content = "내 세상 속엔 어머니밖에 없었어.",
  ui_story_5046_50460702_18_dialog_content = "어머니는 나랑 같이 놀아주고, 읽고 쓰는 법도 가르쳐 주고, 이야기도 들려줬어...\n무엇이든지 모두 어머니가 해주셨어...",
  ui_story_5046_50460702_19_dialog_content = "난 어머니가 정말 좋았어. 하지만 어머니는...\n왠지 내가 어머니를 좋아하는 것만큼 날 좋아하시진 않았던 것 같아.",
  ui_story_5046_50460702_20_dialog_content = "어째서...?",
  ui_story_5046_50460702_21_dialog_content = "기억 속의 우린 항상 이사를 다녔고, 한곳에 오래 머물러 본 적이 없었어.",
  ui_story_5046_50460702_22_dialog_content = "어머니가 날 보는 눈엔 종종 두려움을 엿볼 수 있었고,\n내가 밖에 나가는 걸 허락하지도 않으셨지.",
  ui_story_5046_50460702_23_dialog_content = "제일 오래 살았던 건 마지막 집이었어. 내 어린 시절이 완전히 막을 내렸던 곳이기도 하고.",
  ui_story_5046_50460702_24_dialog_content = "하티...",
  ui_story_5046_50460702_25_dialog_content = "난 항상 그날의 기억에서 도망치기만 했어. 하지만 어떻게 잊을 수 있겠어?",
  ui_story_5046_50460702_26_dialog_content = "8월 26일, 그날은 내 생일이었어.",
  ui_story_5046_50460702_27_dialog_content = "?!",
  ui_story_5046_50460702_28_dialog_content = "하티...",
  ui_story_5046_50460702_29_dialog_content = "가끔은 무서웠지만, 그래도 어머니는 내게 상냥했어.",
  ui_story_5046_50460702_30_dialog_content = "어머니는 내 생일을 기억하고, 전날부터 재료를 준비했어.\n그리고 생일날에 나랑 같이 딸기생크림케이크를 만들었어.",
  ui_story_5046_50460702_31_dialog_content = "그날도 어머니는 평소처럼 일찍 일어나셨지만, 왠지 기분은 좋지 않아 보였어.",
  ui_story_5046_50460702_32_dialog_content = "어머니는 나한테 생일 축하한다고 짧게 말하고는,\n집에서 바쁘게 뭔가를 준비하는 것 같았어.",
  ui_story_5046_50460702_33_dialog_content = "난 케이크가 먹고 싶다고 떠들었지. 근데 어머니는 대답하지 않고 이 펜던트를 주셨어.",
  ui_story_5046_50460702_34_dialog_content = "그리고 어머니는 날 벽난로 속으로 밀어버렸어. 날 태워 죽이려고 하셨던 거야.",
  ui_story_5046_50460702_35_dialog_content = "어떻게... 그런...",
  ui_story_5046_50460702_36_dialog_content = "난로 속에 갇힌 뒤의 일은 잘 기억나지 않아.\n정신이 들었을 때 난 고아원에 있었어.",
  ui_story_5046_50460702_37_dialog_content = "그렇게 많은 다른 애들과 함께 지내는 건 처음이었어...",
  ui_story_5046_50460702_38_dialog_content = "난 줄곧 나가서 다른 애들이랑 놀고 싶다고 생각해 왔는데,\n그게 이런 방식으로 이루어질 거라곤 생각한 적 없었어.",
  ui_story_5046_50460702_39_dialog_content = "난 고아원에서 다른 아이들이나 어른들과 사이좋게 지내려고 했어.\n하지만 저들은 그리 우호적이지 않았어.",
  ui_story_5046_50460702_40_dialog_content = "아이들끼린 자주 싸웠고, 선생님들도 아이들에게 친절하지 않았어.",
  ui_story_5046_50460702_41_dialog_content = "고아원에서 억울한 일이 있어서 어머니한테 하소연하고 싶었지만, 어머니는 어디에도 없었어.",
  ui_story_5046_50460702_42_dialog_content = "그제서야 깨달았어. 어머니는 이제 내가 필요 없었던 거야.",
  ui_story_5046_50460702_43_dialog_content = "그날 밤 고아원 사람이 내가 잠든 사이에 나한테 뭔가 하려고 했어.\n난 죽을힘을 다해서 발버둥 쳤고, 한쪽 귀가 잘리고 말았어.",
  ui_story_5046_50460702_44_dialog_content = "귀가 잘린다는 건 정말 아픈 거야. 아주 아프다고.",
  ui_story_5046_50460702_45_dialog_content = "난 감정을 억누를 수가 없었고, 내 분노를 멋대로 터트려서 온 고아원을 불태워 버렸지.",
  ui_story_5046_50460702_46_dialog_content = "그 뒤의 일부터는 너도 아는 이야기야.\n난 섀도우마스터한테 보내졌고, 두 달 전에야 나올 수 있었어.",
  ui_story_5046_50460702_47_dialog_content = "하티...",
  ui_story_5046_50460702_48_dialog_content = "아이를 사랑하지 않는 부모는 없어.",
  ui_story_5046_50460702_49_dialog_content = "어머니는 분명히 무슨 일이 있어도 네가 행복하게 살길 바라셨을 거야.",
  ui_story_5046_50460702_50_dialog_content = "위로할 필요 없어, PlayerName.",
  ui_story_5046_50460702_51_dialog_content = "어머니가 날 사랑했다면, 왜 날 벽난로 안에 밀었겠어?",
  ui_story_5046_50460702_52_dialog_content = "근데 하티도 마음속으로는 그렇게 생각 안 하잖아?",
  ui_story_5046_50460702_53_dialog_content = "그게 아니면 잃었던 기억을 뭐 하러 이렇게 애써서 되찾으려고 하겠어.",
  ui_story_5046_50460702_54_dialog_content = "하티도 마음속 어딘가에선 어머니가 자신을 사랑해주고 있었다고 믿는 거지?",
  ui_story_5046_50460702_55_dialog_content = "......",
  ui_story_5046_50460702_56_dialog_content = "...응.",
  ui_story_5046_50460702_57_dialog_content = "아까 내가 날 억누르지 못하고 있을 때, 넌 왜 그 틈에 저들이랑 도망치지 않은 거지?",
  ui_story_5046_50460702_58_dialog_content = "그건... 네가 내 도움이 필요하다고 생각했거든.",
  ui_story_5046_50460702_59_dialog_content = "그림 외에 날 이렇게까지 도와준 사람은 네가 처음이야.",
  ui_story_5046_50460702_60_dialog_content = "친구라면 서로 격려하는 게 당연하잖아.",
  ui_story_5046_50460702_61_dialog_content = "친구? 난 친구가 없어.",
  ui_story_5046_50460702_62_dialog_content = "그럼 지금부터 내가 바로 네 친구야.",
  ui_story_5046_50460702_63_dialog_content = "넌 섀도우마스터의 저택을 떠난 뒤로 두 달 동안 계속 기억을 되찾으려고 노력해왔을 거야.",
  ui_story_5046_50460702_64_dialog_content = "하지만 바깥엔 아직도 네가 모르는 더 넓은 세계가 있어.",
  ui_story_5046_50460702_65_dialog_content = "기억을 찾고 나면 내 콜로서스에 놀러 와도 좋아!",
  ui_story_5046_50460702_66_dialog_content = "같이 전 세계를 돌아다니면서, 그동안 못 놀았던 만큼 실컷 노는 거야!",
  ui_story_5046_50460702_67_dialog_content = "......",
  ui_story_5046_50460702_68_dialog_content = "그럼 약속하는 거지?",
  ui_story_5046_50460702_69_dialog_content = "......",
  ui_story_5046_50460702_70_dialog_content = "알겠어.",
  ui_story_5046_50460801_1_dialog_content = "(하멜 씨가 죽기 직전에 말했던 말도, 언급된 최후의 생존자도,\n모두 고아원과 관련이 있어요.)",
  ui_story_5046_50460801_2_dialog_content = "(현재로선 다른 단서가 없어요. 용의자 하티와 PlayerName 씨도 도망쳐 버렸어요.)",
  ui_story_5046_50460801_3_dialog_content = "(지금 상황에선 고아원을 실마리로 조사를 이어갈 수밖에 없어요.)",
  ui_story_5046_50460801_4_dialog_content = "(재건된 고아원엔 과거의 흔적이 거의 남아 있지 않아요.\n그렇다면 단서가 될 수 있는 건 당시의 아이들뿐이겠네요.)",
  ui_story_5046_50460801_5_dialog_content = "백야성 심판관? 사람 잘못 찾아온 건 아닌가요? 전 그냥 하인일 뿐인데요.",
  ui_story_5046_50460801_6_dialog_content = "(자료에 기록이 남아있던 사람은 단 두 명... 이 여자는 하티보다 두 살 연상이겠네요.)",
  ui_story_5046_50460801_7_dialog_content = "(화재 후 근처의 가정에 입양되었고, 지금은 백야성의\n한 귀족 가문에서 하녀로 일하고 있군요.)",
  ui_story_5046_50460801_8_dialog_content = "긴장하지 마세요.\n전 단지 움브라톤 고아원 화재 당시의 상황을 알고 싶을 뿐이에요.",
  ui_story_5046_50460801_9_dialog_content = "기록에 따르면 당신은 고아원에 오래 계셨더군요.",
  ui_story_5046_50460801_10_dialog_content = "그 일은 전에도 여러 번 와서 물었는데요. 이제 와서 왜 또 물어보는 거죠?",
  ui_story_5046_50460801_11_dialog_content = "그날 밤 전 푹 자고 있었어요. 그러다 다른 애들이 소리를 질러서 깼죠.\n눈을 떴을 때 주변은 이미 불바다였어요.",
  ui_story_5046_50460801_12_dialog_content = "그 새로 온 아인족 애가 온몸에 불이 붙어 있었는데,\n옆 침대 남자애는 걔가 불을 질렀다고 했었죠.",
  ui_story_5046_50460801_13_dialog_content = "그땐 도망치느라 정신이 없어서 다른 건 신경도 못 썼어요.",
  ui_story_5046_50460801_14_dialog_content = "(음... 옛날 증언과 차이는 없네요. 모두 이미 알고 있는 정보예요.)",
  ui_story_5046_50460801_15_dialog_content = "그럼 당시 그 하티라는 아인족 아이는 고아원의 누군가에게 원한을 품고 있진 않았나요?",
  ui_story_5046_50460801_16_dialog_content = "아니면 고아원 선생님이나 관리인 등과 충돌이 있진 않았나요?",
  ui_story_5046_50460801_17_dialog_content = "그건 모르겠네요. 들어본 적도 없고요.",
  ui_story_5046_50460801_18_dialog_content = "근데 원한이라뇨? 그때 걘 아직 새파란 어린애였을 거잖아요. 저보다도 어렸으니까요.",
  ui_story_5046_50460801_19_dialog_content = "고아원에도 고작 한 달밖에 없었는데 누구한테 원한을 품었겠어요?",
  ui_story_5046_50460801_20_dialog_content = "굳이 말하자면, 성장이 빠른 아이들은 자기 덩치를 믿고\n다른 애들한테 자기 말을 들으라고 하곤 했어요.",
  ui_story_5046_50460801_21_dialog_content = "그 아인족은 몸집이 작았어요. 그러니 그런 애들을 이기진 못했겠죠.",
  ui_story_5046_50460801_22_dialog_content = "그리고 거기 선생님들도 애들 싸움엔 별로 관심도 없었고,\n항상 애들을 귀찮아하면서 전혀 친절하게 대해주지 않았죠...",
  ui_story_5046_50460801_23_dialog_content = "아마 거기 사람들을 좋아했던 애는 없었을걸요?",
  ui_story_5046_50460801_24_dialog_content = "참, 그럼 한 가지만 더 물어볼게요.",
  ui_story_5046_50460801_25_dialog_content = "고아원에서 입양된 아이들 중에 지금도 연락이 닿는 사람이 있나요?",
  ui_story_5046_50460801_26_dialog_content = "당신이 있던 고아원은 입양 성사율이 무척 높았어요.\n하지만 양부모에 대한 기록은 전혀 찾아볼 수 없고, 사후 방문도 하지 않았죠...",
  ui_story_5046_50460801_27_dialog_content = "없어요.",
  ui_story_5046_50460801_28_dialog_content = "그때도 그런 농담을 했었죠. 매달 꼬박꼬박 여덟아홉 명 가까이 입양이 된다니,\n설마 데려가서 암귀한테 먹이로 주는 건 아니냐고 말이에요.",
  ui_story_5046_50460801_29_dialog_content = "매달 여덟아홉 명의 아이들이 입양되었단 말인가요...?",
  ui_story_5046_50460801_30_dialog_content = "(그건 조금 이상한데요...)",
  ui_story_5046_50460801_31_dialog_content = "알겠어요. 시간 내주셔서 고마워요.",
  ui_story_5046_50460801_32_dialog_content = "(다음은 이 사람이군요. 하티와 동갑내기였던 남자...)",
  ui_story_5046_50460801_33_dialog_content = "(기록상으로는 입양되어 양부모와 함께 빵집을 하고 있네요.)",
  ui_story_5046_50460801_34_dialog_content = "심판관이라고요? 전 아무짓도 안 했는데요.",
  ui_story_5046_50460801_35_dialog_content = "그렇게 긴장하지 마세요.\n전 단지 고아원 화재 당시의 상황을 다시 확인하고 싶을 뿐이에요.",
  ui_story_5046_50460801_36_dialog_content = "아? 그게 벌써 언제 적 일인데, 아직도 조사하는 겁니까?",
  ui_story_5046_50460801_37_dialog_content = "근데 제가 드릴 수 있는 정보는 딱히 없을 것 같은데요.\n기억나는 건 다 얘기했고, 조서에 적혀 있을 겁니다.",
  ui_story_5046_50460801_38_dialog_content = "그러니까 가능하면 제 장사 좀 방해 안 하셨으면 좋겠습니다.",
  ui_story_5046_50460801_39_dialog_content = "아...",
  ui_story_5046_50460801_40_dialog_content = "만약 당시의 일을 조금 더 떠올려 주실 수 있다면, 남은 빵은 전부 제가 살게요.",
  ui_story_5046_50460801_41_dialog_content = "정말입니까?!",
  ui_story_5046_50460801_42_dialog_content = "그럼 왠지 정말 사소한 일이라도 생각해낼 수 있을 것 같네요...",
  ui_story_5046_50460801_43_dialog_content = "협조해 주셔서 고마워요. 당신은 그때 불을 지른 게 하티인 걸 봤다고 하셨죠?\n그때 상황을 좀 더 자세히 말씀해 주시겠어요?",
  ui_story_5046_50460801_44_dialog_content = "그게 말이죠... 전 어릴 때부터 잠을 깊게 못 잤습니다.\n그래서 그때도 그 아인족이 비명을 지르는 걸 듣자마자 잠에서 깼었죠.",
  ui_story_5046_50460801_45_dialog_content = "제 침대는 그 애랑 조금 멀리 있어서, 뭐가 어떻게 된 건지 확실하게 본 건 아닙니다.\n하지만 그 애가 비명을 지르고 나서 온몸에 불이 붙었었죠.",
  ui_story_5046_50460801_46_dialog_content = "그리고 그 불이 커튼으로 옮겨붙어서 불이 커지니까 다른 애들도 잠에서 깼습니다.",
  ui_story_5046_50460801_47_dialog_content = "전 다른 아이들을 따라 도망쳤지만, 종아리에 화상을 입고 말았죠.\n이것들은 전부 예전에 조사받았을 때 얘기했던 것들입니다.",
  ui_story_5046_50460801_48_dialog_content = "그럼 그 아인족 하티는 고아원의 누군가에게 원한을 가지고 있진 않았나요?",
  ui_story_5046_50460801_49_dialog_content = "최근 일어난 화재의 피해자는 모두 고아원 관계자였어요.\n그래서 전 그들과 하티 사이에 무슨 원한이 있었던 건 아닌지 확인하고 싶어요.",
  ui_story_5046_50460801_50_dialog_content = "고아원엔 애들이 자주 새로 들어왔지만, 다들 얼마 안 가서 내보내졌어요.",
  ui_story_5046_50460801_51_dialog_content = "걔가 아인족이었으니 망정이지, 아니었으면 기억도 안 났을 거예요.\n누구와 원한이 있었는지는 말할 것도 없겠죠.",
  ui_story_5046_50460801_52_dialog_content = "고아원에 있던 사람들은...",
  ui_story_5046_50460801_53_dialog_content = "매일같이 자기 애도 아닌 시끄러운 애들을 잔뜩 상대해야 하잖아요.",
  ui_story_5046_50460801_54_dialog_content = "겉보기엔 그런대로 친절했지만, 뒤에서 뭘 하고 있었는지는 모르겠습니다.",
  ui_story_5046_50460801_55_dialog_content = "(아무래도 다들 고아원의 직원들에 대한 인상이 그리 좋지 않은 것 같네요...)",
  ui_story_5046_50460801_56_dialog_content = "그럼 전에 고아원에서 입양된 다른 아이들과는 지금도 연락을 하나요?",
  ui_story_5046_50460801_57_dialog_content = "아니면 혹시 입양된 가정에 대해 들은 소식이 있나요?",
  ui_story_5046_50460801_58_dialog_content = "입양된 후엔 완전히 연락이 끊겼어요.",
  ui_story_5046_50460801_59_dialog_content = "입양된 가정이라면...",
  ui_story_5046_50460801_60_dialog_content = "그런 건 보통 고아원 원장이 기록하지 않나요?",
  ui_story_5046_50460801_61_dialog_content = "참, 그러고 보니 고아원의 선생들이 몇몇 애들을 유심히 보면서\n뭔가 쓰거나 그림을 그리곤 했었죠.",
  ui_story_5046_50460801_62_dialog_content = "그러다 입양하는 날이 되면 그 애들을 데려갔습니다.",
  ui_story_5046_50460801_63_dialog_content = "지금 생각하면 그 노트엔 입양되는 아이들의 정보가 적혀 있었을지도 몰라요.\n잘은 모르겠지만. 심판관이라면 어디 가서 구할 수 있는 거 아닌가요?",
  ui_story_5046_50460801_64_dialog_content = "안타깝지만 그 화재 때 기록들이 모두 타버린 것 같아요.",
  ui_story_5046_50460801_65_dialog_content = "어쨌든 협조해 주셔서 감사해요. 가게 빵은 전부 주세요.",
  ui_story_5046_50460801_66_dialog_content = "(휴, 드디어 대량의 빵을 처리할 수 있었네요. 그럼 이번엔...)",
  ui_story_5046_50460801_67_dialog_content = "(입양 후 소식이 끊긴 아이들, 그리고 당시 어린아이였던 범인 하티에 대해 알아봐야 해요.)",
  ui_story_5046_50460801_68_dialog_content = "(대체 어떻게 해서 매달 그렇게 많은 아이들의 입양을 성사시켰을까요?\n게다가 그 후 소식이 끊기다니...)",
  ui_story_5046_50460801_69_dialog_content = "(최악의 가능성이라면... 고아원이 아이들을 이용해 뭔가를 하고 있었다는 거겠죠...)",
  ui_story_5046_50460801_70_dialog_content = "(정말 무서운 추측이지만... 그게 만약 사실이라면,\n하티의 방화와 하멜 씨의 살해에도 그만한 이유가 생기게 돼요.)",
  ui_story_5046_50460801_71_dialog_content = "(생각만 해도 소름이 끼쳐요... 옛 고아원엔 대체 얼마나 많은 비밀이 숨어 있는 걸까요?)",
  ui_story_5046_50460801_72_dialog_content = "앗...",
  ui_story_5046_50460801_73_dialog_content = "조심하세요, 아가씨.",
  ui_story_5046_50460801_74_dialog_content = "고마워요, 그런데 당신은...",
  ui_story_5046_50460801_75_dialog_content = "저기 모퉁이에 있는 「파이어플라이 바」의 주인입니다.\n그림이라고 부르세요.",
  ui_story_5046_50460801_76_dialog_content = "그림 씨? 하티의 친구분이시죠? 제나스 선생님께 들은 적 있어요.",
  ui_story_5046_50460801_77_dialog_content = "절 알고 계셨나요? 근데 잡담은 잠깐 미뤄두고 저 좀 도와주실 수 있을까요?",
  ui_story_5046_50460801_78_dialog_content = "무슨...",
  ui_story_5046_50460801_79_dialog_content = "크에엑!",
  ui_story_5046_50460801_80_dialog_content = "!!!",
  ui_story_5046_50460801_81_dialog_content = "아까 교외에 나갔다가 더러운 게 붙어 버려서요.",
  ui_story_5046_50460801_82_dialog_content = "암귀?! 조심하세요!",
  ui_story_5046_50460802_1_dialog_content = "도와주셔서 감사했습니다. 아가씨가 없었으면 벌써 암귀한테 잡아먹혔을 거예요.",
  ui_story_5046_50460802_2_dialog_content = "별일 아닌걸요. 참, 하티에 대해 좀 물어보고 싶은 게 있어요.",
  ui_story_5046_50460802_3_dialog_content = "물론 좋습니다. 여기서 모퉁이만 돌면 제 가게가 나오니까,\n앉아서 뭐라도 마시면서 이야기하시죠.",
  ui_story_5046_50460802_4_dialog_content = "<color=#e8d9bb>딸랑──</color>",
  ui_story_5046_50460802_5_dialog_content = "실례할게요.",
  ui_story_5046_50460802_6_dialog_content = "방금 절 구해주셨는데, 당연히 대접해 드려야죠.",
  ui_story_5046_50460802_7_dialog_content = "영업시간이 아니니까 편한 곳에 앉으세요. 뭘 주문하시겠어요?",
  ui_story_5046_50460802_8_dialog_content = "지금은 일하는 중이라서요. 게다가 전 술은 마시지 않아요.",
  ui_story_5046_50460802_9_dialog_content = "술 말고 다른 음료들도 나쁘지 않을 겁니다.",
  ui_story_5046_50460802_10_dialog_content = "블루 허리케인, 움브라톤 아로마, 백야 아이스티...",
  ui_story_5046_50460802_11_dialog_content = "고맙지만 됐어요. 바로 본론으로 들어가죠.",
  ui_story_5046_50460802_12_dialog_content = "하티와는 어떻게 알게 된 사이죠?",
  ui_story_5046_50460802_13_dialog_content = "하티는 여기서 일하니까 당연히 알죠.",
  ui_story_5046_50460802_14_dialog_content = "하티는 주로 식자재 운반이나 주방 청소 같은 일을 맡고 있어요.\n쓸데없는 말도 안 하고, 부지런하고 성실한 직원이에요.",
  ui_story_5046_50460802_15_dialog_content = "최근에 일어난 몇 건의 화재 발생 시 하티는 어디에 있었죠?",
  ui_story_5046_50460802_16_dialog_content = "벌써 한참 된 일이라서 저도 기억이 잘 안 나네요.",
  ui_story_5046_50460802_17_dialog_content = "하지만 그날은 확실히 기억해요. 가게에 재고 채우는 날이었거든요.",
  ui_story_5046_50460802_18_dialog_content = "하티는 주방에서 하루 종일 일을 했어요.\n도착한 재료를 확인하고, 신선도를 체크하고, 밤이 돼서야 끝났죠.",
  ui_story_5046_50460802_19_dialog_content = "(페르민이 당한 날이네요. 그림 씨의 증언이 사실이라면 하티는 알리바이가 있어요.)",
  ui_story_5046_50460802_20_dialog_content = "(하지만 그림 씨가 하티를 감싸주고 있을 가능성도 존재해요.)",
  ui_story_5046_50460802_21_dialog_content = "믿어주세요, 아가씨. 진짜예요.",
  ui_story_5046_50460802_22_dialog_content = "크리스틴이라고 부르면 돼요.",
  ui_story_5046_50460802_23_dialog_content = "하티에 대해 말씀해 주실 다른 이야기는 없나요?",
  ui_story_5046_50460802_24_dialog_content = "예를 들어 누군가에게 원한을 가지고 있다거나,\n복수를 하겠다는 등의 이야기를 한 적은 없었나요?",
  ui_story_5046_50460802_25_dialog_content = "하티는 말하는 걸 좋아하지 않아요. 게다가 저희도 알게 된 지 얼마 안 돼서요.\n그런 이야기는 들어 본 적 없네요.",
  ui_story_5046_50460802_26_dialog_content = "(아무래도 더는 들을 수 있는 얘기가 없을 것 같네요.)",
  ui_story_5046_50460802_27_dialog_content = "그렇군요. 그럼 실례했어요. 먼저 가 볼게요.",
  ui_story_5046_50460802_28_dialog_content = "잠시만요, 가시기 전에 제가 만든 특제 주스 한 잔 드시는 게 어떨까요?",
  ui_story_5046_50460802_29_dialog_content = "아까 소개해드린 건 취향이 아니신 것 같아서, 얘기하는 동안 만들어 봤거든요.",
  ui_story_5046_50460802_30_dialog_content = "이래 봬도 전 움브라톤 최고의 바텐더예요.",
  ui_story_5046_50460802_31_dialog_content = "괜찮아요.",
  ui_story_5046_50460802_32_dialog_content = "그렇게 차갑게 굴지 마세요. 음료 한잔과 진실인지 거짓인지 알 수 없는\n이야기를 맞바꾸는 건 움브라톤에서 살아가는 방식인걸요.",
  ui_story_5046_50460802_33_dialog_content = "한번 체험해 보시는 것도 좋아요.",
  ui_story_5046_50460802_34_dialog_content = "(뭔가 속뜻이 담긴 말 같네요... 게다가 왜... 갑자기 이렇게 가까이 다가오는 거죠?!)",
  ui_story_5046_50460802_35_dialog_content = "아직 근무 중이고, 용의자도 잡히지 않은 상황에서 음료라니...",
  ui_story_5046_50460802_36_dialog_content = "길에서 만났을 때 당신은 고민에 빠져 있는 것 같았죠.\n사건 조사가 진척이 없어서 그런 거겠죠?",
  ui_story_5046_50460802_37_dialog_content = "그럴 때일수록 앉아서 음료 한잔과 함께 이야기를 듣고 휴식을 취해야죠.\n뭔가 새로운 발견이 있을지도 모르잖아요.",
  ui_story_5046_50460802_38_dialog_content = "(정곡을 찔렸네요...)",
  ui_story_5046_50460802_39_dialog_content = "(지금 상황에선 다른 단서도 당장은 찾을 수 없겠죠.\n이야기를 들어보는 것도 나쁘진 않겠어요.)",
  ui_story_5046_50460802_40_dialog_content = "알겠어요. 대신 한 잔만이에요.",
  ui_story_5046_50460802_41_dialog_content = "후훗, 그럼 이야기를 시작해 볼까요?",
  ui_story_5046_50460802_42_dialog_content = "10년 전 움브라톤엔 아직 섀도우마스터가 없었어요.\n그 누구도 거리의 싸움과 살인에 신경 쓰지 않았고, 교외의 고아원은 말할 것도 없었죠.",
  ui_story_5046_50460802_43_dialog_content = "그런데 그런 환경에서도 어떤 고아원이 멀쩡하게 유지되었다면...",
  ui_story_5046_50460802_44_dialog_content = "어떤 이유인 것 같나요?",
  ui_story_5046_50460802_45_dialog_content = "무질서한 사회 환경에서도 고아원이 정상적으로 운영됐다면...\n아마 누군가가 선의로 지원해 준 덕분이겠죠.",
  ui_story_5046_50460802_46_dialog_content = "맞아요, 그 고아원엔 확실히 후원자가 있었어요. 하지만 지원 이유는 선의가 아니에요.",
  ui_story_5046_50460802_47_dialog_content = "그 고아원엔 원장과 직원 다섯 명밖에 없었어요.\n움브라톤의 거물이 뒤에 있다는 소문 같은 것도 없었죠.",
  ui_story_5046_50460802_48_dialog_content = "그런데 정기적으로 몇 명의 아이들이 입양되고, 새로운 아이들이 입소했어요...",
  ui_story_5046_50460802_49_dialog_content = "마치 이 술집의 재고가 들어왔다 떨어졌다 하는 것처럼 말이에요.",
  ui_story_5046_50460802_50_dialog_content = "서, 설마... 그 고아원에서 아동 인신매매가 벌어지고 있었다는 건가요?",
  ui_story_5046_50460802_51_dialog_content = "서두르지 마세요. 이야기는 아직 끝나지 않았어요.",
  ui_story_5046_50460802_52_dialog_content = "입양된 아이들은 모두 백야성의 어느 귀족들에게 보내졌는데,\n그 귀족들은 지금은 이미 몰락했다고 하더군요.",
  ui_story_5046_50460802_53_dialog_content = "다만 최근에 피트만이라는 심판관이 그 몇몇 가문의 귀족들을 재조사했다고 해요.",
  ui_story_5046_50460802_54_dialog_content = "피트만 선배님이 조사하시는 <color=#FFB400>그 사건</color>이군요!",
  ui_story_5046_50460802_55_dialog_content = "원장과 직원 다섯 명... 인원수는 제가 조사한 옛 고아원의 정보와 일치해요.",
  ui_story_5046_50460802_56_dialog_content = "옛 고아원의 대형 화재로 원장이 사망했고,\n직원 세 명이 최근 두 달간 발생한 화재로 사망했어요.",
  ui_story_5046_50460802_57_dialog_content = "하멜 씨도 옛 고아원과 관계가 있었어요. 여기에 그 사람이 언급했던 누군가를 더하면...",
  ui_story_5046_50460802_58_dialog_content = "딱 다섯 명이에요!",
  ui_story_5046_50460802_59_dialog_content = "여기에 과거 화재에서 생존했던 두 사람의 증언까지 더하면...",
  ui_story_5046_50460802_60_dialog_content = "말씀하신 이야기 속 고아원이 바로 저 옛 고아원인 거죠?",
  ui_story_5046_50460802_61_dialog_content = "어머... 전 그저 이야기를 하나 들려드렸을 뿐인걸요.",
  ui_story_5046_50460802_62_dialog_content = "뭔가 도움이 됐다면 다행이네요.",
  ui_story_5046_50460802_63_dialog_content = "지금 말씀들, 도움이 많이 됐어요. 협조해 주셔서 정말 감사드려요.",
  ui_story_5046_50460802_64_dialog_content = "하지만 궁금한 게 있어요. 지금 말씀하신 이야기는 어디에서 알게 되신 거죠?",
  ui_story_5046_50460802_65_dialog_content = "피트만 선배가 조사하고 있는 사건은 백야성의 귀족들이 관련돼 있어요.",
  ui_story_5046_50460802_66_dialog_content = "그 이야기를 해 주신 분은 상당히 세세한 것까지 알고 계신 것 같은데요.\n분명히 보통 사람이 아니겠죠?",
  ui_story_5046_50460802_67_dialog_content = "여기 와서 이야기를 나누는 사람들은 그 누구도 이름을 남기지 않아요.\n아는 게 적을수록 이야기는 재미있는 법이거든요.",
  ui_story_5046_50460802_68_dialog_content = "그림자는 모든 비밀을 알고 있답니다.",
  ui_story_5046_50460802_69_dialog_content = "(이 사람, 언뜻 보기엔 신뢰할 수 없을 것 같지만, 말과 행동엔 전혀 빈틈이 없어요...)",
  ui_story_5046_50460802_70_dialog_content = "(어쩌면 오늘 길에서 만난 것도 우연이 아닐지도 모르겠네요.\n아까 그 이야기를 하기 위해서 절 일부러 여기로 데려온 거겠죠.)",
  ui_story_5046_50460802_71_dialog_content = "이 대륙에서 일어나는 모든 일들은 서로 연결돼 있답니다.\n움브라톤에 있는 나비의 날갯짓이 백야성에 폭풍을 일으킬 수도 있어요.",
  ui_story_5046_50460802_72_dialog_content = "네?",
  ui_story_5046_50460802_73_dialog_content = "(왜 갑자기 절 보면서 저런 말을 한 걸까요?)",
  ui_story_5046_50460802_74_dialog_content = "후훗... 자, 이야기 시간은 끝났습니다.",
  ui_story_5046_50460802_75_dialog_content = "보세요, 밖에 야경이 꽤 멋져요. 크리스틴은 움브라톤의 야경을 별로 본 적이 없겠죠?",
  ui_story_5046_50460802_76_dialog_content = "밤이 되니까 불을 밝힌 노점들이 늘어섰네요.\n마치 은하수처럼 아름답고 따뜻한 풍경이에요.",
  ui_story_5046_50460802_77_dialog_content = "이야기, 그리고 음료 고마워요. 맛있었어요.",
  ui_story_5046_50460802_78_dialog_content = "후훗, 사실 그 특제 주스는 당신을 보고 영감이 떠올라서 만든 거예요.\n오늘 처음 시도한 레시피죠.",
  ui_story_5046_50460802_79_dialog_content = "이름이 있나요?",
  ui_story_5046_50460802_80_dialog_content = "아니요. 근데 이제 정했어요.",
  ui_story_5046_50460802_81_dialog_content = "「백야성의 백합」이라고 할까 싶네요.",
  ui_story_5046_50460901_1_dialog_content = "하티, 옛날에 네가 어디 살았는지 기억나?",
  ui_story_5046_50460901_2_dialog_content = "전에 살던 곳에 가 보면 기억을 되찾는 데 뭔가 도움이 되지 않을까?",
  ui_story_5046_50460901_3_dialog_content = "어머니는 날 데리고 여러 번 이사를 했어. 그래서 예전 주소는 기억이 잘 안 나.",
  ui_story_5046_50460901_4_dialog_content = "하지만 내가 불을 낸 집은 아직도 기억하고 있어. 움브라톤 근처였어.",
  ui_story_5046_50460901_5_dialog_content = "네가 불을 낸 게 아니야. 분명히 무슨 오해가 있었을 거야.",
  ui_story_5046_50460901_6_dialog_content = "가자, 그 집을 한번 보러 가자. 뭔가 생각날지도 몰라.",
  ui_story_5046_50460901_7_dialog_content = "여기야.",
  ui_story_5046_50460901_8_dialog_content = "오는 길에 있던 민가들도 전부 폐가가 돼 있었어.\n여긴 오랫동안 사람이 안 살았던 모양이네.",
  ui_story_5046_50460901_9_dialog_content = "하지만 불탄 곳은 이 집뿐이야. 한눈에 알 수 있어.",
  ui_story_5046_50460901_10_option_content = "왜 여긴 전부 황폐해진 거지?",
  ui_story_5046_50460901_11_dialog_content = "모르겠어.",
  ui_story_5046_50460901_12_dialog_content = "그때 불이 나고 나서 다시 정신을 차렸을 때 난 이미 고아원에 있었어.",
  ui_story_5046_50460901_13_dialog_content = "얼마 후엔 고아원에도 불이 났고, 난 섀도우마스터한테 보내졌어.",
  ui_story_5046_50460901_14_dialog_content = "여기 온 건 그 뒤로 처음이야.",
  ui_story_5046_50460901_15_dialog_content = "같이 집 안을 둘러보자.",
  ui_story_5046_50460901_16_option_content = "왜 자주 이사를 다닌 거야?",
  ui_story_5046_50460901_17_dialog_content = "나쁜 놈들이 계속 우릴 쫓아다녔거든.",
  ui_story_5046_50460901_18_dialog_content = "전에 어머니가 말해줬어. 아버지는 대단한 사람이라고.\n그래서 아버지를 잡아서 실험하고 싶어 하는 사람이 있대.",
  ui_story_5046_50460901_19_dialog_content = "어느 날 나쁜 놈이 집에 와서 아버지를 잡으려고 했어.\n아버지는 어머니를 지키려고 자기만 그 자리에 남았어.",
  ui_story_5046_50460901_20_dialog_content = "어머니는 도망쳤고, 그 뒤에 날 낳았어.",
  ui_story_5046_50460901_21_dialog_content = "전에 어머니한테 물어본 적이 있어. 난 왜 아버지가 없냐고.\n그랬더니 아버지는 아주 먼 곳에 있다고 어머니는 대답했어.",
  ui_story_5046_50460901_22_dialog_content = "그러다 내가 조금 크고 나서, 어머니는 어떤 정체를 알 수 없는 조직이\n아버지를 잡아서 실험을 하려고 한다고 말해줬어.",
  ui_story_5046_50460901_23_dialog_content = "그 조직은 그 뒤로도 계속 우릴 쫓았고, 그래서 어머니는 날 데리고 자주 이사를 다녔어.",
  ui_story_5046_50460901_24_dialog_content = "같이 집 안을 둘러보자.",
  ui_story_5046_50460901_25_option_content = "같이 집 안을 둘러보자.",
  ui_story_5046_50460901_26_dialog_content = "타버리긴 했지만, 여기서 어떻게 살았는지는 기억나지?",
  ui_story_5046_50460901_27_dialog_content = "그 기억을 떠올리는 게 너한테 힘든 일이라는 건 알아.\n하지만 어떤 사소한 일이든 네가 잃은 기억을 되찾는 계기가 될 수도 있어.",
  ui_story_5046_50460901_28_dialog_content = "사실 난 여길 돌아오는 게 무서웠어.\n어머니랑 살 때의 기억들이 떠오르는 게 두려웠으니까.",
  ui_story_5046_50460901_29_dialog_content = "잃었던 기억을 되찾는 것도 무서웠어.",
  ui_story_5046_50460901_30_dialog_content = "만약 그 기억 속에서 어머니가 정말로 내 힘을 무서워해서 날 난로에 넣은 거라면...",
  ui_story_5046_50460901_31_dialog_content = "그럴 리 없어. 어머니가 그렇게 한 건 분명히 다른 이유가 있을 거야.",
  ui_story_5046_50460901_32_dialog_content = "불은 널 해칠 수 없잖아? 어머니도 분명히 그걸 알고 계셨을 거야.",
  ui_story_5046_50460901_33_dialog_content = "어쩌면 그때 뭔가 위험한 상황이 돼서, 어머니가 널 지키려고 그랬던 걸지도 몰라.",
  ui_story_5046_50460901_34_dialog_content = "하티의 아버지가 어머니를 지키려고 했을 때처럼 말이야.",
  ui_story_5046_50460901_35_dialog_content = "......",
  ui_story_5046_50460901_36_dialog_content = "가자. 내가 전에 살던 곳을 보여줄게.",
  ui_story_5046_50460901_37_dialog_content = "응!",
  ui_story_5046_50460901_38_dialog_content = "여길 들어가면 바로 거실이 보여. 어머니는 항상 맛있는 거랑 그림책을 갖다주셨어.",
  ui_story_5046_50460901_39_dialog_content = "여긴 원래 창문이 있었어. 두꺼운 커튼이 쳐져 있어서 빛도 안 들어오고, 밖도 안 보였지.",
  ui_story_5046_50460901_40_dialog_content = "하지만 밖에서 아이들이 노는 목소리는 들렸어.",
  ui_story_5046_50460901_41_dialog_content = "한 번은 내가 창문을 열고 밖의 애들이 뭐 하고 노는지 보려고 했는데,\n어머니가 날 막았어.",
  ui_story_5046_50460901_42_dialog_content = "「창문 닫아! 당장!」",
  ui_story_5046_50460901_43_dialog_content = "빛이 안 들어오면 집안이 항상 깜깜했을 거잖아?",
  ui_story_5046_50460901_44_dialog_content = "어머니는 집에 촛불을 아주 많이 켜 두셨어. 그걸로 집을 밝혔어.",
  ui_story_5046_50460901_45_dialog_content = "그건 좀 이상하네...",
  ui_story_5046_50460901_46_dialog_content = "난 선천적으로 강력한 불꽃의 루미나를 가지고 있었어.\n어머니 말로는 아버지한테 물려받은 힘이랬어.",
  ui_story_5046_50460901_47_dialog_content = "그래서 어렸을 땐 실수로 이불이나 그림책을 태워버려서.\n어머니는 내가 불을 쓰는 걸 금지하셨어.",
  ui_story_5046_50460901_48_dialog_content = "그래서 난 어머니가 날 다른 아이들과 놀지 못하게 한 것도,\n날 벽난로에 넣은 것도 분명히 내 불꽃을 두려워해서 그런 거라 생각했어.",
  ui_story_5046_50460901_49_dialog_content = "(하티네 어머니는 하티를 밖에 못 나가게 하고,\n창문을 막아서 밖에서 안을 못 보게 하셨어...)",
  ui_story_5046_50460901_50_dialog_content = "(게다가 누군가가 두 사람을 쫓았다는 건...\n하티의 어머니가 뭔가를 숨기고 있었던 거겠지.)",
  ui_story_5046_50460901_51_dialog_content = "봐, 이 벽난로야.",
  ui_story_5046_50460901_52_dialog_content = "......",
  ui_story_5046_50460901_53_dialog_content = "PlayerName, 난... 저 벽난로 안으로 들어가 봐야겠어.",
  ui_story_5046_50460901_54_dialog_content = "뭐?",
  ui_story_5046_50460901_55_dialog_content = "방금 네가 여기 살던 기억을 떠올리라고 했잖아?\n그래서 그때처럼 벽난로 안에 들어가 보고 싶어.",
  ui_story_5046_50460901_56_dialog_content = "그러면 뭔가 생각날지도 몰라.",
  ui_story_5046_50460901_57_dialog_content = "가능성이 있는 것 같긴 하지만...",
  ui_story_5046_50460901_58_dialog_content = "알겠어!",
  ui_story_5046_50460901_59_dialog_content = "혹시라도 무슨 일이 생기면 내가 감응 능력으로 네 기억에 개입해서 도와줄게!",
  ui_story_5046_50460901_60_dialog_content = "고마워. 그래도 일단은 내 힘으로 기억해보고 싶어.",
  ui_story_5046_50460901_61_dialog_content = "그럼 도움이 필요할 때 말해줘!",
  ui_story_5046_50460901_62_dialog_content = "<color=#e8d9bb>움브라톤 교외</color>",
  ui_story_5046_50460901_63_dialog_content = "(저 앞이 하티가 전에 살았던 집이군요.)",
  ui_story_5046_50460901_64_dialog_content = "(전에 아버님이 사들이셨던 움브라톤의 별장도 분명히 이 근처였어요.)",
  ui_story_5046_50460901_65_dialog_content = "(이 모퉁이에서 왼쪽으로 돌아서 조금만 걸으면 대문이 보이겠죠.)",
  ui_story_5046_50460901_66_dialog_content = "(마지막으로 그 별장에 갔던 건 부모님과 함께 휴가를 보내기 위해서였어요...\n제나스 선생님께서 절 구해주신 곳도 그곳이었구요...)",
  ui_story_5046_50460901_67_dialog_content = "(어라, 저건... PlayerName 씨?!)",
  ui_story_5046_50460901_68_dialog_content = "뭔가 생각났어?",
  ui_story_5046_50460901_69_dialog_content = "아니, 아무것도.",
  ui_story_5046_50460901_70_dialog_content = "역시 안 되는 건가...",
  ui_story_5046_50460901_71_dialog_content = "PlayerName 씨! 하티!",
  ui_story_5046_50460901_72_dialog_content = "크리스틴?!",
  ui_story_5046_50460901_73_dialog_content = "하티! 당신을 복수의 살인 및 방화 혐의로 체포하겠어요!",
  ui_story_5046_50460901_74_dialog_content = "자, 잠깐만!",
  ui_story_5046_50460901_75_dialog_content = "네가 말한 것들은 전부 하티가 한 짓이 아니야! 왜 하티를 잡아?!",
  ui_story_5046_50460901_76_dialog_content = "스스로 죄를 인정하는 범인은 없어요.",
  ui_story_5046_50460901_77_dialog_content = "그, 그럼 너도 증거 있어?",
  ui_story_5046_50460901_78_dialog_content = "증거요?",
  ui_story_5046_50460901_79_dialog_content = "PlayerName 씨, 당신도 보셨잖아요?\n저 사람은 우리 눈앞에서 하멜 씨를 살해했어요.",
  ui_story_5046_50460901_80_dialog_content = "크리스틴, 날 믿어. 하멜 씨는 하티가 죽인 게 아니야!",
  ui_story_5046_50460901_81_dialog_content = "분명히 누군가가 뒤에서 하멜 씨한테 손을 쓴 거야!",
  ui_story_5046_50460901_82_dialog_content = "어쨌든 하멜 씨가 사망한 현장에 하티가 있었던 건 사실이에요.",
  ui_story_5046_50460901_83_dialog_content = "하티가 죽인 게 아니더라도, 수사에 협조할 의무가 있어요.",
  ui_story_5046_50460901_84_dialog_content = "동행해 주세요.",
  ui_story_5046_50460901_85_dialog_content = "난 어머니와의 기억을 되찾아야 해.",
  ui_story_5046_50460901_86_dialog_content = "그 외의 어떤 것도 내겐 중요하지 않아.",
  ui_story_5046_50460901_87_dialog_content = "그럼 동행을 거부하겠다는 건가요?",
  ui_story_5046_50460901_88_dialog_content = "좋을 대로 생각해.",
  ui_story_5046_50460901_89_dialog_content = "그럼 강제집행밖에 방법이 없겠네요.",
  ui_story_5046_50460901_90_dialog_content = "크리스틴, 하티가 기억을 되찾은 다음에 데려가면 안 될까?",
  ui_story_5046_50460901_91_dialog_content = "PlayerName 씨, 비키세요.",
  ui_story_5046_50460901_92_dialog_content = "계속해서 용의자를 두둔한다면 당신을 공범으로 체포하는 수밖에 없어요.",
  ui_story_5046_50460901_93_dialog_content = "어머니와의 기억은... 하티한테 아주 중요한 거야.",
  ui_story_5046_50460901_94_dialog_content = "난 그 기억이 하티한테 얼마나 소중한 건지 이해할 수 있어.",
  ui_story_5046_50460901_95_dialog_content = "그리고 난 하티랑 약속했어. 기억을 되찾는 걸 도와주겠다고.",
  ui_story_5046_50460901_96_dialog_content = "그러니까 절대 안 비켜.",
  ui_story_5046_50460901_97_dialog_content = "난 하티를 지킬 거야. 하티가 기억을 되찾는 그 순간까지.",
  ui_story_5046_50460901_98_dialog_content = "저 사람을 지키겠다고요...? 하지만 저도 선생님을 지키고 싶어요!",
  ui_story_5046_50460901_99_dialog_content = "저 사람은 고아원에 불을 지르고 당신을 인질로 데려갔어요...",
  ui_story_5046_50460901_100_dialog_content = "기사로서 선생님의 경력을 당신들이 망친 거라구요!",
  ui_story_5046_50460901_101_dialog_content = "당신과 저 사람을 찾으려고 선생님이 얼마나 고생하셨는지 아세요?!",
  ui_story_5046_50460901_102_dialog_content = "당신들을 데리고 돌아가서, 섀도우마스터와 움브라톤을 위해 이 임무를 완수한다면...",
  ui_story_5046_50460901_103_dialog_content = "선생님은 분명히 기뻐하실 거예요!",
  ui_story_5046_50460901_104_dialog_content = "다시 한번 말씀드릴게요!",
  ui_story_5046_50460901_105_dialog_content = "PlayerName 씨, 비키세요!",
  ui_story_5046_50460901_106_dialog_content = "싫어! 절대 못 비켜!",
  ui_story_5046_50460901_107_dialog_content = "「하티...... 펜던트를...... 지켜야 해......」",
  ui_story_5046_50460901_108_dialog_content = "엄마... 내가 대체 뭘 지켜야 되는 거야...?",
  ui_story_5046_50460901_109_dialog_content = "알려줘... 엄마...",
  ui_story_5046_50460901_110_dialog_content = "그날 대체 무슨 일이 있었던 거야... 왜 날 벽난로에 밀어 넣은 거냐고...",
  ui_story_5046_50460901_111_dialog_content = "마지막 경고예요! 비키세요! PlayerName 씨!",
  ui_story_5046_50460901_112_dialog_content = "「물건을...... 내놓...... 죽어라.......」",
  ui_story_5046_50460901_113_dialog_content = "크으윽! 머리가... 뭔가 머릿속에 들어오려고 해!",
  ui_story_5046_50460901_114_dialog_content = "왔구나.",
  ui_story_5046_50460901_115_dialog_content = "결국 이날이 오고 말았어.",
  ui_story_5046_50460901_116_dialog_content = "엄마?",
  ui_story_5046_50460901_117_dialog_content = "하티. 엄마는 네 곁에 없어도 영원히 널 사랑할 거야.",
  ui_story_5046_50460901_118_dialog_content = "엄마... 왜 없는데? 어디 가?",
  ui_story_5046_50460901_119_dialog_content = "무슨 말인지 모르겠어...",
  ui_story_5046_50460901_120_dialog_content = "이제... 시간이 없어...",
  ui_story_5046_50460901_121_dialog_content = "하티, 그 절반의 펜던트를 꼭 소중하게 지키렴.",
  ui_story_5046_50460901_122_dialog_content = "그 펜던트엔 아빠와 엄마가 널 사랑하는 마음이 담겨 있어.\n아빠 엄마가 하티를 영원히 지켜줄 거야.",
  ui_story_5046_50460901_123_dialog_content = "잘 살아가야 해. 사랑하는 하티.",
  ui_story_5046_50460901_124_dialog_content = "엄마?!",
  ui_story_5046_50460901_125_dialog_content = "으앗!",
  ui_story_5046_50460901_126_dialog_content = "(엄마! 왜 날 벽난로 속으로 밀어버린 거야?!)",
  ui_story_5046_50460901_127_dialog_content = "<color=#e8d9bb>끼이익──</color>",
  ui_story_5046_50460901_128_dialog_content = "(누가 왔어?! 누구지? 우리 집엔 아무도 온 적 없는데!)",
  ui_story_5046_50460901_129_dialog_content = "한참 찾았잖아, 캐서린 켈피. 도망칠 수 있을 줄 알았어?",
  ui_story_5046_50460901_130_dialog_content = "...제나스.",
  ui_story_5046_50460901_131_dialog_content = "쳇, 집이 뭐 이리 깜깜해? 불빛도 하나 없고.",
  ui_story_5046_50460901_132_dialog_content = "온실에서 자란 아가씨가 이런 집에 살다니, 먹고살기 쉽지 않았겠어.",
  ui_story_5046_50460901_133_dialog_content = "너만 죽으면 그 어떤 허름한 집에서도 행복하게 살 수 있어.",
  ui_story_5046_50460901_134_dialog_content = "쉿. 아가씨가 그렇게 거친 말을 해서야 쓰나.",
  ui_story_5046_50460901_135_dialog_content = "쓸데없는 소리 집어치워.",
  ui_story_5046_50460901_136_dialog_content = "오늘 반드시 널 죽여서 펜리르의 복수를 할 테니까.",
  ui_story_5046_50460901_137_dialog_content = "(펜리르? 아버지?! 저놈이 아버지를 죽였어?!)",
  ui_story_5046_50460901_138_dialog_content = "분수도 모르는군.",
  ui_story_5046_50460901_139_dialog_content = "하아... 하아...",
  ui_story_5046_50460901_140_dialog_content = "캐서린, 펜던트를 넘기면 목숨만은 살려주지.",
  ui_story_5046_50460901_141_dialog_content = "날 죽여...",
  ui_story_5046_50460901_142_dialog_content = "정말 고집불통이군. 그렇게 죽고 싶다면 내가 그 소원을 들어주지.",
  ui_story_5046_50460901_143_dialog_content = "(엄마!)",
  ui_story_5046_50460901_144_dialog_content = "으아아아──!",
  ui_story_5046_50460901_145_dialog_content = "(불이 붙었어?! 엄마가 한 거야?",
  ui_story_5046_50460901_146_dialog_content = "으윽! 뭐야, 이 불! 어떻게 순식간에 거세진 거지?!",
  ui_story_5046_50460901_147_dialog_content = "캐서린, 이게 네 계획이냐?",
  ui_story_5046_50460901_148_dialog_content = "네가 살아서 돌아갈 수 있을 것 같아...?",
  ui_story_5046_50460901_149_dialog_content = "날 길동무로 삼을 생각이었군! 이거 놔!",
  ui_story_5046_50460901_150_dialog_content = "펜리르의 복수를...",
  ui_story_5046_50460901_151_dialog_content = "우욱──!",
  ui_story_5046_50460901_152_dialog_content = "(엄마! 엄마가 날 보고 있어...)",
  ui_story_5046_50460901_153_dialog_content = "......",
  ui_story_5046_50460901_154_dialog_content = "(나오지... 말라고...?)",
  ui_story_5046_50460901_155_dialog_content = "(엄마?! 엄마가 안 움직여!)",
  ui_story_5046_50460901_156_dialog_content = "(엄마──!)",
  ui_story_5046_50460901_157_dialog_content = "흥, 감히 날 협박하다니.",
  ui_story_5046_50460901_158_dialog_content = "(흐아아앙... 엄마...)",
  ui_story_5046_50460901_159_dialog_content = "(저놈... 뭘 찾고 있어...)",
  ui_story_5046_50460901_160_dialog_content = "(저놈을 죽이고 엄마를 위해 복수할 거야!)",
  ui_story_5046_50460901_161_dialog_content = "(...하, 하지만... 엄마가 나오지 말라고 했잖아...)",
  ui_story_5046_50460901_162_dialog_content = "크윽... 대체 어디다 숨긴 거냐!",
  ui_story_5046_50460901_163_dialog_content = "......",
  ui_story_5046_50460901_164_dialog_content = "드디어 찾았군... 으윽, 얼굴에... 화상이라도 입은 건가?",
  ui_story_5046_50460901_165_dialog_content = "불이야! 불이야!",
  ui_story_5046_50460901_166_dialog_content = "빨리 피해야겠군...",
  ui_story_5046_50460901_167_dialog_content = "(가버렸어... 엄마는... 움직이지 않아...)",
  ui_story_5046_50460901_168_dialog_content = "(엄마...)",
  ui_story_5046_50460901_169_dialog_content = "겨우 다 껐네. 정말 엄청 센 불이었어...",
  ui_story_5046_50460901_170_dialog_content = "캐서린을 찾았을 땐 이미 숨을 거둔 뒤였어요...",
  ui_story_5046_50460901_171_dialog_content = "불기운이 보통 셌어야지. 안 타죽었으면 숨 막혀 죽었을걸.",
  ui_story_5046_50460901_172_dialog_content = "말 좀 가려서 해요.",
  ui_story_5046_50460901_173_dialog_content = "흥.",
  ui_story_5046_50460901_174_dialog_content = "할 일 없으면 치우는 거나 좀 거들어.",
  ui_story_5046_50460901_175_dialog_content = "예이, 예이.",
  ui_story_5046_50460901_176_dialog_content = "잠깐만! 이리 와 보세요! 벽난로 안에 어린애가 있어요!",
  ui_story_5046_50460901_177_dialog_content = "캐서린한테 아이가 있다는 말은 못 들었는데...",
  ui_story_5046_50460901_178_dialog_content = "심지어 상처 하나 없잖아. 분명히 그렇게 센 불이었는데...",
  ui_story_5046_50460901_179_dialog_content = "휴... 캐서린 저 여자, 항상 창문도 닫고 낮에도 촛불을 켜뒀잖아.",
  ui_story_5046_50460901_180_dialog_content = "내 이럴 줄 알았다니까. 언제 분명히 불이 나겠다 싶었다고. 거 봐.",
  ui_story_5046_50460901_181_dialog_content = "이제 와서 뭘 그런 소릴 하고 있어? 지금 중요한 건 아이를 어떻게 할지라고.",
  ui_story_5046_50460901_182_dialog_content = "고아원에 보내야 하지 않을까요?",
  ui_story_5046_50460901_183_dialog_content = "그럴 수밖에 없겠어.",
  ui_story_5046_50460901_184_dialog_content = "또 물어보고 싶은 게 있어.",
  ui_story_5046_50461001_1_dialog_content = "조금씩 진정되고 있는 것 같네요.",
  ui_story_5046_50461001_2_dialog_content = "고마워, 크리스틴.",
  ui_story_5046_50461001_3_dialog_content = "뭐가요?",
  ui_story_5046_50461001_4_dialog_content = "하티가 기억을 되찾는 걸 기다려줘서.",
  ui_story_5046_50461001_5_dialog_content = "사실 너도 하티가 범인이 아니라고 생각했지?",
  ui_story_5046_50461001_6_dialog_content = "조사를 할수록 하티에 대한 의심은 확실히 줄어들었어요.",
  ui_story_5046_50461001_7_dialog_content = "비록 이 사건은 확실히 하티와 관계가 있고, 모든 단서도 하티를 가리키고 있어요.",
  ui_story_5046_50461001_8_dialog_content = "하지만 풀리지 않은 모순점도 많이 있어요.",
  ui_story_5046_50461001_9_dialog_content = "크리스틴은 이 사건에 정말 진지하게 임하고 있구나.",
  ui_story_5046_50461001_10_dialog_content = "선생님이 가르쳐 주신 거예요.\n어떤 사건이든 진지하게 대하면서, 사소한 단서도 결코 놓쳐서는 안 된다고 말이에요.",
  ui_story_5046_50461001_11_dialog_content = "하지만 선생님은 이 사건에 제가 관여하는 걸 원하지 않으셨어요...",
  ui_story_5046_50461001_12_dialog_content = "그럼 크리스틴은 지금까지 몰래 조사하고 있었던 거야?",
  ui_story_5046_50461001_13_dialog_content = "네...",
  ui_story_5046_50461001_14_dialog_content = "근데 PlayerName 씨는 왜 하티와 함께 도망친 거죠? 당신은 인질이었잖아요.",
  ui_story_5046_50461001_15_dialog_content = "난 하티가 범인이 아니라고 믿거든. 그리고 그때 하티는 정서가 많이 불안정했어.",
  ui_story_5046_50461001_16_dialog_content = "하티는 내 도움이 필요해. 그래서 날 같이 데려가라고 한 거야.",
  ui_story_5046_50461001_17_dialog_content = "그 짧은 시간에 서로 그만한 신뢰를 쌓은 건가요...",
  ui_story_5046_50461001_18_dialog_content = "<size=30>선생님도 그만큼 절 신뢰해주시면 좋을 텐데...</size>",
  ui_story_5046_50461001_19_dialog_content = "크리스틴 넌 여길 어떻게 알아냈어?",
  ui_story_5046_50461001_20_dialog_content = "이 마을에 살던 주민이 알려줬어요.",
  ui_story_5046_50461001_21_dialog_content = "이 마을은 고아원과 멀지도 않고, 움브라톤에도 속해 있지 않아요.\n옛날에 이곳 주민들은 힘들게 살았다고 해요.",
  ui_story_5046_50461001_22_dialog_content = "당시 이스타반 씨는 고아원 화재의 사후 처리에 개입하면서\n취했던 일련의 조치 덕분에 민심을 얻을 수 있었죠.",
  ui_story_5046_50461001_23_dialog_content = "섀도우마스터가 된 후 이스타반 씨는 이 마을 주민들을 움브라톤으로 이주시켰어요.",
  ui_story_5046_50461001_24_dialog_content = "하티는 그 주민들이 고아원으로 보낸 거예요.",
  ui_story_5046_50461001_25_dialog_content = "마을 사람들 말에 따르면 그때 이 집에 큰불이 나서 불을 껐고,\n불에 탄 집 안에서 하티를 발견했다고 해요.",
  ui_story_5046_50461001_26_dialog_content = "이 집에 살던 여성 한 분은 이미 돌아가신 상태였고요.",
  ui_story_5046_50461001_27_dialog_content = "하지만 마을 사람들은 그분이 아이 이야기를 하는 걸 들어본 적도 없었고,\n아이를 어떻게 해야 할지 몰랐다고 해요.",
  ui_story_5046_50461001_28_dialog_content = "그래서 결국 고아원에 보내기로 결정했고, 그 아이가 하티였던 거예요.",
  ui_story_5046_50461001_29_dialog_content = "그랬구나...",
  ui_story_5046_50461001_30_dialog_content = "크리스틴 너 정말 대단하네. 얼마 없는 단서로 그렇게 많은 정보를 알아냈잖아.",
  ui_story_5046_50461001_31_dialog_content = "크흠... 아무리 칭찬해 주셔도 두 분은 동행해서 조사에 협조해 주셔야 해요.",
  ui_story_5046_50461001_32_dialog_content = "난 진심으로 크리스틴이 대단하다고 생각해! 나중에 꼭 좋은 심판관이 될 거야!",
  ui_story_5046_50461001_33_dialog_content = "선생님도 그렇게 생각해 주시면 좋겠는데 말이죠...",
  ui_story_5046_50461001_34_dialog_content = "제나스 씨 말하는 거야?",
  ui_story_5046_50461001_35_dialog_content = "네, 저번에 루미나틱스로 불을 끄려고 하다가 선생님을 다치게 만들었고,\n그 뒤엔 하멜 씨도 돌아가셨죠...",
  ui_story_5046_50461001_36_dialog_content = "선생님은 이제 더는 절 믿지 못하셔요.",
  ui_story_5046_50461001_37_dialog_content = "하지만 난 크리스틴이 이미 충분히 잘했다고 생각하는걸.",
  ui_story_5046_50461001_38_dialog_content = "아직 몇 번밖에 만나지 못했지만, 크리스틴은 성실하고 인내심 있고\n선한 마음을 가진 심판관이라고 생각해.",
  ui_story_5046_50461001_39_dialog_content = "그, 그런 듣기 좋은 말에 제가 봐줄 거라고 생각하면 오산이에요...",
  ui_story_5046_50461001_40_dialog_content = "전 백야성 심판소의 전문적인 훈련을 받고 있다구요.\n정의를 관통하는 제 신념은 다, 당신의 말 몇 마디에 흔들리는 게 아니에요!",
  ui_story_5046_50461001_41_dialog_content = "난 그냥 내 생각을 말했을 뿐이야! 다른 뜻은 없어!",
  ui_story_5046_50461001_42_dialog_content = "만약 하티가 정말로 그런 짓을 했다면, 내가 반드시 죗값을 치르게 할 거야.",
  ui_story_5046_50461001_43_dialog_content = "하지만 그게 아니라면, 너희도 하티를 모함해선 안 돼!",
  ui_story_5046_50461001_44_dialog_content = "마, 맞아요! 정의는 그런 거니까요!",
  ui_story_5046_50461001_45_dialog_content = "그러니까 크리스틴도 자신감을 가져. 남의 생각을 너무 신경 쓸 거 없어.",
  ui_story_5046_50461001_46_dialog_content = "왜냐하면 크리스틴은 이미 대단하니까!",
  ui_story_5046_50461001_47_dialog_content = "......",
  ui_story_5046_50461001_48_dialog_content = "혹시 평소에 여자애를 잘 달랜다는 말 들은 적 있나요?",
  ui_story_5046_50461001_49_dialog_content = "하아? 여자애를 잘 달래?",
  ui_story_5046_50461001_50_dialog_content = "난 바이스라는 친구가 있는데, 매일 나 대신 콜로서스의 재정 문제로 고민하고 있거든.\n그래서 걘 항상 내가 낭비한다고 날 혼내곤 해.",
  ui_story_5046_50461001_51_dialog_content = "오히려 여자애를 귀찮게 만드는 걸 잘한다고 말하는 게 맞을걸.",
  ui_story_5046_50461001_52_dialog_content = "<size=45>크어어!</size>",
  ui_story_5046_50461001_53_dialog_content = "암귀? 게다가 한 마리가 아닌 것 같아.",
  ui_story_5046_50461001_54_dialog_content = "여긴 오랫동안 황폐한 상태였으니까요. 암귀가 나와도 이상하지 않아요.",
  ui_story_5046_50461001_55_dialog_content = "하지만 하티는 아직 못 깨어났잖아.\n지금 무작정 하티를 데리고 여길 떠나는 건 위험할 것 같아.",
  ui_story_5046_50461001_56_dialog_content = "걱정하지 않으셔도 돼요. 암귀 몇 마리 정도는 제가 심판하겠어요!",
  ui_story_5046_50461002_1_dialog_content = "휴우──",
  ui_story_5046_50461002_2_dialog_content = "이제 주변에 암귀의 기척은 없는 것 같아.",
  ui_story_5046_50461002_3_dialog_content = "고마워, 크리스틴.",
  ui_story_5046_50461002_4_dialog_content = "아이테르의 능력은 정말 대단하네요.",
  ui_story_5046_50461002_5_dialog_content = "PlayerName 씨가 없었다면 몇 번이나 암귀의 기습에 당할 뻔했잖아요.",
  ui_story_5046_50461002_6_dialog_content = "PlayerName...",
  ui_story_5046_50461002_7_dialog_content = "하티! 정신이 들어?",
  ui_story_5046_50461002_8_dialog_content = "일어났으면 수사 협조를 위해 동행해 주세요. 조사 결과가 나오기 전까지는...",
  ui_story_5046_50461002_9_dialog_content = "제나스였어...",
  ui_story_5046_50461002_10_dialog_content = "네? 선생님이 왜요?",
  ui_story_5046_50461002_11_dialog_content = "PlayerName... 전부 다 생각났어.",
  ui_story_5046_50461002_12_dialog_content = "그날 밤 어머니는 날 지키려고 벽난로 속으로 날 밀었던 거야.",
  ui_story_5046_50461002_13_dialog_content = "어머니는 혼자서 제나스와 싸웠어... 그래, 그 남자의 이름이 제나스였어.",
  ui_story_5046_50461002_14_dialog_content = "그놈이 어머니를 죽이고, 어머니가 차고 있던 펜던트를 뺏었던 거야.",
  ui_story_5046_50461002_15_dialog_content = "난 반드시 펜던트를 되찾겠어.",
  ui_story_5046_50461002_16_dialog_content = "네? 지금 그게 대체 무슨 말이죠?",
  ui_story_5046_50461002_17_dialog_content = "제나스는 살인범이야.",
  ui_story_5046_50461002_18_dialog_content = "헛소리!",
  ui_story_5046_50461002_19_dialog_content = "계속해서 선생님에 대한 비방을 일삼는다면, 저도 용서하지 않겠어요!",
  ui_story_5046_50461002_20_dialog_content = "살인범은 살인범일 뿐이야. 그건 사실이야.",
  ui_story_5046_50461002_21_dialog_content = "그날 밤 제나스가 집에 왔어. 어머니는 그놈에게 살해당했고, 펜던트도 빼앗겼어...",
  ui_story_5046_50461002_22_dialog_content = "내가 이 눈으로 다 봤다고! 반드시 죽여버릴 거야! 어머니를 위해 복수하겠어!",
  ui_story_5046_50461002_23_dialog_content = "선생님이 당신 어머니를 죽인 범인이라고 어떻게 단정하죠?",
  ui_story_5046_50461002_24_dialog_content = "지금 그 기억은 이제 막 떠오른 거죠? 게다가 아주 오래전에 일어난 일이잖아요.",
  ui_story_5046_50461002_25_dialog_content = "당신의 기억이 틀리지 않았다고 단언할 수 있나요?\n당신이 거짓말을 하고 있을 가능성도 부정할 수 없어요.",
  ui_story_5046_50461002_26_dialog_content = "틀림없어...",
  ui_story_5046_50461002_27_dialog_content = "놈의 얼굴 화상, 그리고 어머니의 펜던트...",
  ui_story_5046_50461002_28_dialog_content = "그것만으로도 범인이 확실하다고!",
  ui_story_5046_50461002_29_dialog_content = "미안하지만 선생님의 얼굴 화상은 절 구해주시다가 생긴 거예요.",
  ui_story_5046_50461002_30_dialog_content = "그날 저녁, 부모님은 파티에 참석하러 가셨어요.",
  ui_story_5046_50461002_31_dialog_content = "그날은 해가 빨리 졌고, 부모님을 배웅하자마자 날이 어두워졌던 게 확실히 기억나요.",
  ui_story_5046_50461002_32_dialog_content = "전 방으로 돌아가서 책을 읽고 있었어요.",
  ui_story_5046_50461002_33_dialog_content = "그런데 갑자기 어디선가 거센 불이 치솟았고,\n연기에 휩싸인 전 무서워서 그 자리에서 울고 있었어요.",
  ui_story_5046_50461002_34_dialog_content = "그때 마침 제나스 선생님이 제 이름을 부르는 소리가 들렸어요.\n제가 우는 소리를 듣고 찾으러 와 주셨던 거죠...",
  ui_story_5046_50461002_35_dialog_content = "불길 속을 도망칠 때, 선생님은 절 품에 꽉 안고 계셨고,\n그래서 전 연기에 목이 멘 것 외에는 상처 하나 입지 않았어요.",
  ui_story_5046_50461002_36_dialog_content = "하지만 선생님은... 얼굴 절반에 화상을 입고 말았죠.",
  ui_story_5046_50461002_37_dialog_content = "그럼 제나스 씨의 화상은 크리스틴을 도와줬을 때 입은 거겠네.",
  ui_story_5046_50461002_38_dialog_content = "......",
  ui_story_5046_50461002_39_dialog_content = "하티, 제나스가 온 게 언제였는지 기억나?",
  ui_story_5046_50461002_40_dialog_content = "8월 26일... 내 생일이야.",
  ui_story_5046_50461002_41_dialog_content = "8월 26일이요?!",
  ui_story_5046_50461002_42_dialog_content = "선생님께서 절 도와주신 날도 8월 26일이었어요.",
  ui_story_5046_50461002_43_dialog_content = "그 날짜... 똑똑히 기억하고 있어요.",
  ui_story_5046_50461002_44_dialog_content = "같은 날 두 건의 화재가 발생한 건가...",
  ui_story_5046_50461002_45_dialog_content = "지금 크리스틴 넌 그때 밤에 불이 났다고 했지?\n그럼 제나스가 크리스틴의 집에 나타난 것도 물론 밤이 되겠네.",
  ui_story_5046_50461002_46_dialog_content = "근데 하티도 제나스가 밤에 왔다고 했어.",
  ui_story_5046_50461002_47_dialog_content = "그럼 제나스는 같은 날 같은 시간에 두 개의 다른 장소에 나타났다는 말이 돼.",
  ui_story_5046_50461002_48_dialog_content = "아무리 생각해도 그건 말이 안 돼요. 분명히 하티 당신 기억이 틀렸을 거예요.",
  ui_story_5046_50461002_49_dialog_content = "그럼 펜던트는 어떻게 설명할 거지?",
  ui_story_5046_50461002_50_dialog_content = "어머니가 나한테 소중히 지키라고 했던 펜던트를 왜 놈이 가지고 있지?",
  ui_story_5046_50461002_51_dialog_content = "난 그 펜던트 때문에 놈을 알아본 거라고.",
  ui_story_5046_50461002_52_dialog_content = "당신이 말한 펜던트는 선생님 가문의 증표예요.",
  ui_story_5046_50461002_53_dialog_content = "펜던트에 새겨져 있는 무늬는 10여 년 전 몰락한 백야성 귀족 가문의 문장이에요.",
  ui_story_5046_50461002_54_dialog_content = "그날 선생님께서 절 불길 속에서 구해주시고 나서,\n아버님은 감사 인사를 하면서 선생님께 성함을 물었죠.",
  ui_story_5046_50461002_55_dialog_content = "그때 선생님은 그 펜던트를 꺼내서, 자신도 원래는 귀족이었지만\n가문이 몰락해서 정처 없이 떠돌고 있다고 대답하셨어요.",
  ui_story_5046_50461002_56_dialog_content = "아버님은 같은 귀족을 배려하는 차원에서 선생님을 집에 머무르도록 하셨죠.",
  ui_story_5046_50461002_57_dialog_content = "그 펜던트는 우리 어머니 게 확실해. 난 똑똑히 기억하고 있어.",
  ui_story_5046_50461002_58_dialog_content = "놈이 펜던트를 훔쳐서 자기 것처럼 말한 게 분명하다고!",
  ui_story_5046_50461002_59_dialog_content = "당신도 증거는 없잖아요! 그럼 그 말들도 전부 추측일 뿐이에요!",
  ui_story_5046_50461002_60_dialog_content = "(잠깐만... 하티는 그 시절에 어머니가 항상 창문을 막아 두었다고 했어.\n그래서 집에는 빛 한 점도 없었고, 평소엔 촛불을 조명으로 썼다고 했고 말이야.)",
  ui_story_5046_50461002_61_dialog_content = "(그럼 사건이 일어난 게 낮인지 밤인지 확실하지 않다는 거잖아?)",
  ui_story_5046_50461002_62_dialog_content = "하티. 그 사람이 집에 온 게 밤이었다고 단정할 수 있어?",
  ui_story_5046_50461002_63_dialog_content = "...촛불이 켜져 있었어. 아마 밤이었을 거야.",
  ui_story_5046_50461002_64_dialog_content = "문제는 바로 그거야.",
  ui_story_5046_50461002_65_dialog_content = "촛불이 켜져 있어서 넌 그렇게 생각한 거잖아.",
  ui_story_5046_50461002_66_dialog_content = "촛불을 켜야 했으니까 시간은 밤이었을 거고, 사건도 밤에 일어났다고 말이야.",
  ui_story_5046_50461002_67_dialog_content = "하지만 하티네 집은 밤이나 낮이나 촛불이 켜져 있었어.\n그러니까 「촛불이 켜져 있었다」는 사실만으로 시간을 특정할 순 없어.",
  ui_story_5046_50461002_68_dialog_content = "난 하티네 집에서 사건이 있었던 게 낮일 거라고 생각해.",
  ui_story_5046_50461002_69_dialog_content = "그런 건가...",
  ui_story_5046_50461002_70_dialog_content = "한편 크리스틴은 저녁에 부모님이 파티에 참석하러 나가셨고,\n그날은 해가 빨리 저물었다고 세세한 것까지 기억했어.",
  ui_story_5046_50461002_71_dialog_content = "크리스틴의 집에서 사건이 벌어졌던 건 밤이 맞을 거야.",
  ui_story_5046_50461002_72_dialog_content = "이 전제를 토대로 추리한다면, 범인은 낮에 하티의 집을 습격했고,\n밤에는 크리스틴의 집으로 달려가서 크리스틴을 구했다는 말이 돼.",
  ui_story_5046_50461002_73_dialog_content = "그럼 「같은 인물이 같은 시간에 두 개의 다른 장소에 출현했다」는 모순도 없는 거지.",
  ui_story_5046_50461002_74_dialog_content = "훌륭한 추리네요...",
  ui_story_5046_50461002_75_dialog_content = "다만 중요한 문제가 하나 더 있어. 여기서 크리스틴네 별장까지 가려면 얼마나 걸리지?",
  ui_story_5046_50461002_76_dialog_content = "그건 오는 길에 저도 생각했던 일이에요. 별장은 여기서 그리 멀지 않아요.",
  ui_story_5046_50461002_77_dialog_content = "설마... 정말로 선생님이... 아니, 그럴 순 없어요...",
  ui_story_5046_50461002_78_dialog_content = "제나스가 범인인지 확인하고 싶다면, 펜던트만 보여달라고 하면 돼.",
  ui_story_5046_50461002_79_dialog_content = "그 펜던트는 두 개가 한 쌍이라고 하티가 그랬어.",
  ui_story_5046_50461002_80_dialog_content = "제나스가 하티의 집을 덮친 범인이 아니라 자기 말대로 「몰락한 귀족」이라면...",
  ui_story_5046_50461002_81_dialog_content = "그 펜던트가 하티의 것과 딱 맞을 리가 없어.",
  ui_story_5046_50461002_82_dialog_content = "하지만 만약... 두 펜던트가 하나로 딱 맞는다면...",
  ui_story_5046_50461002_83_dialog_content = "제나스가 범인이야.",
  ui_story_5046_50461002_84_dialog_content = "그럴 리가 없어요! 선생님은 절대 살인범이 아니에요!",
  ui_story_5046_50461002_85_dialog_content = "아, 그래요! 동기! 동기가 있어야죠!",
  ui_story_5046_50461002_86_dialog_content = "선생님과 당신 가족 사이엔 아무런 인연도 원한도 없을 텐데요.\n그럼 선생님이 무슨 이유로 당신들을 쫓은 거죠?",
  ui_story_5046_50461002_87_dialog_content = "어머니는 어떤 의문의 조직이 아버지의 힘을 노리고 있고,\n아버지를 잡아서 실험하려고 한다고 그랬어.",
  ui_story_5046_50461002_88_dialog_content = "기억 속에서 어머니는 아버지의 복수를 위해 제나스와 함께 죽으려고 했어...",
  ui_story_5046_50461002_89_dialog_content = "그러니까 제나스는 그 조직의 사람이 분명해.",
  ui_story_5046_50461002_90_dialog_content = "못 믿겠어요!",
  ui_story_5046_50461002_91_dialog_content = "그럴 리 없어요... 절대로 그럴 리 없다구요!",
  ui_story_5046_50461002_92_dialog_content = "크리스틴, 진정해.",
  ui_story_5046_50461002_93_dialog_content = "제나스가 범인인지 아닌지는 두 사람의 펜던트만 합쳐보면 알 수 있어.",
  ui_story_5046_50461002_94_dialog_content = "가서 펜던트를 내놓으라고 해.",
  ui_story_5046_50461002_95_dialog_content = "내놓지 않는다면, 내가 놈을 쓰러트리고 빼앗는 수밖에 없어.",
  ui_story_5046_50461002_96_dialog_content = "폭력은 안 돼! 게다가 움브라톤 곳곳엔 널 잡으려는 병사들이 있어.\n제나스를 만나서 얘기하는 건 무리야.",
  ui_story_5046_50461002_97_dialog_content = "......",
  ui_story_5046_50461002_98_dialog_content = "제가 도와드릴게요.",
  ui_story_5046_50461002_99_dialog_content = "PlayerName 씨 말처럼 펜던트야말로 지금 선생님의 결백을\n증명할 수 있는 가장 좋은 방법이에요.",
  ui_story_5046_50461002_100_dialog_content = "그러니까 제가 도와드릴게요.\n다른 병사들이 없을 때 여러분이 선생님과 만날 수 있도록요.",
  ui_story_5046_50461002_101_dialog_content = "대신 여러분도 약속해 주세요. 펜던트가 서로 맞지 않는다면 얌전히 수사에 협조해 주세요.",
  ui_story_5046_50461002_102_dialog_content = "크리스틴, 우릴 믿어주는 거야?",
  ui_story_5046_50461002_103_dialog_content = "그런 말은 안 했어요.",
  ui_story_5046_50461002_104_dialog_content = "하지만 PlayerName 씨의 치밀한 추리 덕분에 저도 많은 걸 배웠어요.",
  ui_story_5046_50461002_105_dialog_content = "이 사건을 다시 처음부터 자세히 알아보고 싶어요.",
  ui_story_5046_50461002_106_dialog_content = "많이 늦었네요. 얼른 움브라톤으로 돌아가죠.",
  ui_story_5046_50461101_1_dialog_content = "크리스틴 아가씨, 오셨습니까.",
  ui_story_5046_50461101_2_dialog_content = "크리스틴이라고 부르면 돼요.",
  ui_story_5046_50461101_3_dialog_content = "제나스 대장님은요? 왜 안 보이시죠?",
  ui_story_5046_50461101_4_dialog_content = "제나스 대장님은 병사들 몇 명을 데리고 고아원에 가셨습니다.",
  ui_story_5046_50461101_5_dialog_content = "고아원이요? 거긴 왜 가신 거죠?",
  ui_story_5046_50461101_6_dialog_content = "그건... 말씀 안 하셨습니다.",
  ui_story_5046_50461101_7_dialog_content = "그렇군요, 고마워요.",
  ui_story_5046_50461101_8_dialog_content = "대장님, 아직까진 어떤 물건도 찾지 못했습니다.",
  ui_story_5046_50461101_9_dialog_content = "계속 찾으세요. 어떤 물건이든 발견하는 즉시 제게 가져오도록 하세요.",
  ui_story_5046_50461101_10_dialog_content = "대장님!",
  ui_story_5046_50461101_11_dialog_content = "뭔가 찾았습니까?",
  ui_story_5046_50461101_12_dialog_content = "아닙니다. 크리스틴 아가씨께서 오셨습니다. 대장님을 만나고 싶다고 하십니다.",
  ui_story_5046_50461101_13_dialog_content = "크리스틴이 여긴 왜 온 거죠?",
  ui_story_5046_50461101_14_dialog_content = "선생님.",
  ui_story_5046_50461101_15_dialog_content = "여러분은 잠시 자리를 비켜주실 수 있나요? 선생님과 둘이서 이야기를 나누고 싶어요.",
  ui_story_5046_50461101_16_dialog_content = "예.",
  ui_story_5046_50461101_17_dialog_content = "크리스틴? 왜 온 겁니까?",
  ui_story_5046_50461101_18_dialog_content = "심판소에 사건 조사 기록을 내러 갔을 시간 아닙니까?",
  ui_story_5046_50461101_19_dialog_content = "백야성으로 돌아가기 전에 선생님께 부탁드리고 싶은 게 있어요.",
  ui_story_5046_50461101_20_dialog_content = "선생님의 펜던트를 좀 빌려주세요.",
  ui_story_5046_50461101_21_dialog_content = "펜던트?",
  ui_story_5046_50461101_22_dialog_content = "전에 보여주셨죠? 선생님 가문의 문장이 새겨진 펜던트 말이에요.",
  ui_story_5046_50461101_23_dialog_content = "그게 왜 필요한 겁니까?",
  ui_story_5046_50461101_24_dialog_content = "으음...",
  ui_story_5046_50461101_25_dialog_content = "사건 자료를 조사하다가 선생님 가문의 문장과 비슷한 모양을 발견했어요.\n그래서 다시 한번 보고 싶어요.",
  ui_story_5046_50461101_26_dialog_content = "......",
  ui_story_5046_50461101_27_dialog_content = "크리스틴, 전 당신이 어릴 때부터 자라오는 걸 봐 왔습니다.\n진실을 말하고 있는지 어떤지는 한눈에 알 수 있습니다.",
  ui_story_5046_50461101_28_dialog_content = "선생님...",
  ui_story_5046_50461101_29_dialog_content = "말하세요. 무슨 일 때문이죠?",
  ui_story_5046_50461101_30_dialog_content = "사실... 전 펜던트로 선생님의 결백을 증명하고 싶어요.",
  ui_story_5046_50461101_31_dialog_content = "결백?",
  ui_story_5046_50461101_32_dialog_content = "몇 년 전 방화 사건과 선생님이 관련돼 있을지도 모른다는 걸 알았어요.",
  ui_story_5046_50461101_33_dialog_content = "선생님의 혐의를 벗기 위해서는 선생님이 가지고 계신 그 펜던트가 필요해요.",
  ui_story_5046_50461101_34_dialog_content = "제 펜던트와 방화 사건이 무슨 상관이 있습니까?",
  ui_story_5046_50461101_35_dialog_content = "선생님의 펜던트와 제가 가지고 있는 펜던트가... 한 쌍이라고 해요.",
  ui_story_5046_50461101_36_dialog_content = "선생님의 펜던트를 주세요. 두 펜던트가 맞는지 안 맞는지만 확인하면...",
  ui_story_5046_50461101_37_dialog_content = "사건 관련 증거를 입수했다면, 자세히 조사하도록 관계자에게 전달했어야지요.",
  ui_story_5046_50461101_38_dialog_content = "증거를 들이대고 상사를 심문하다니... 크리스틴, 그동안 제게 뭘 배운 겁니까?",
  ui_story_5046_50461101_39_dialog_content = "순순히 말을 들을 생각이 없다면 주먹으로 해결하자고.",
  ui_story_5046_50461101_40_dialog_content = "하티?",
  ui_story_5046_50461101_41_dialog_content = "크리스틴, 지금 용의자를 체포하고도 감옥에 가두지 않은 겁니까?",
  ui_story_5046_50461101_42_dialog_content = "하티는 용의자가 아니니까.\n움브라톤의 몇 건의 방화 사건도, 하멜 씨의 죽음도 하티와는 관계가 없어.",
  ui_story_5046_50461101_43_dialog_content = "당신들... 그랬군요.",
  ui_story_5046_50461101_44_dialog_content = "크리스틴, 당신은 용의자를 비호하고 있을 뿐만 아니라,\n용의자와 결탁해서 상사를 속이려고 하는 겁니까!",
  ui_story_5046_50461101_45_dialog_content = "전... 그런 게 아니라...",
  ui_story_5046_50461101_46_dialog_content = "고작 펜던트를 빌리겠다는 것뿐인데 반응이 너무 격렬한 거 아냐?",
  ui_story_5046_50461101_47_dialog_content = "아니면 켕기는 거라도 있어서 그래?",
  ui_story_5046_50461101_48_dialog_content = "당신은 하티네 집이 밤낮으로 촛불을 켜는 걸 이용해서 알리바이를 만들었어.\n게다가 크리스틴을 증인으로 이용했어!",
  ui_story_5046_50461101_49_dialog_content = "그때 당신은 하티의 집에서 사람을 죽이고,\n근처에 있는 크리스틴의 집 별장에 불을 질렀겠지.",
  ui_story_5046_50461101_50_dialog_content = "그러고 우연히 지나가던 것처럼 꾸며 크리스틴을 도와주고,\n얼굴 화상은 그때 생긴 것처럼 보이게 한 거야!",
  ui_story_5046_50461101_51_dialog_content = "하지만 실제로는 하티의 어머니와 싸우다가 생긴 화상이잖아!",
  ui_story_5046_50461101_52_dialog_content = "훗, 그게 절 모함하려고 지어낸 이야기입니까? 꽤 그럴싸하군요.",
  ui_story_5046_50461101_53_dialog_content = "지어낸 이야기가 아니야. 지금까지의 정보를 토대로 당시 상황을 추리한 거지.",
  ui_story_5046_50461101_54_dialog_content = "크리스틴, 당신도 같은 생각입니까?",
  ui_story_5046_50461101_55_dialog_content = "선생님... 전...",
  ui_story_5046_50461101_56_dialog_content = "PlayerName 씨의 추리가...",
  ui_story_5046_50461101_57_dialog_content = "......",
  ui_story_5046_50461101_58_dialog_content = "......",
  ui_story_5046_50461101_59_dialog_content = "하하하하하하!",
  ui_story_5046_50461101_60_dialog_content = "크리스틴, 당신 정말 대단한 아가씨였군요.",
  ui_story_5046_50461101_61_dialog_content = "이제 막 알게 된 아이테르를 당신의 선생님인 저보다 더 믿는 겁니까?",
  ui_story_5046_50461101_62_dialog_content = "그럼 왜 펜던트를 빌려주지 않으시는 거죠...?",
  ui_story_5046_50461101_63_dialog_content = "펜던트만 보여주면 제 의심을 풀 수 있잖아요...",
  ui_story_5046_50461101_64_dialog_content = "이미 당신은 마음속에 의심의 씨앗을 품고 있는데,\n제가 그런 쓸데없는 일을 할 필요가 있습니까?",
  ui_story_5046_50461101_65_dialog_content = "제가 빌려주든, 안 빌려주든 이미 속으로 결론은 나 있겠지요.",
  ui_story_5046_50461101_66_dialog_content = "아, 아니에요! 그 어떤 추측도 증거가 없는 한...",
  ui_story_5046_50461101_67_dialog_content = "자, 이제 됐습니다.",
  ui_story_5046_50461101_68_dialog_content = "앞으로는 더는 선생님이라고 부르지 마세요.",
  ui_story_5046_50461101_69_dialog_content = "당신이 용의자와 한패가 되는 길을 선택한다면, 제 검은 당신을 겨누는 수밖에 없습니다.",
  ui_story_5046_50461101_70_dialog_content = "선생님... 대체 뭘 하시려는 거죠?",
  ui_story_5046_50461101_71_dialog_content = "크리스틴, 자기 판단을 믿어!",
  ui_story_5046_50461101_72_dialog_content = "지금 제나스는 감정에 호소해서 널 얽매려고 하는 거야!\n상대가 선생님이든 아니든 네가 지켜야 할 건 마음속의 정의야!",
  ui_story_5046_50461101_73_dialog_content = "그래야 백야성의 견습 심판관 크리스틴, 너다운 거라고!",
  ui_story_5046_50461101_74_dialog_content = "......",
  ui_story_5046_50461101_75_dialog_content = "경비병! 크리스틴은 아이테르와 결탁해서 용의자 하티를 감싸고 있습니다.\n모두 체포하세요!",
  ui_story_5046_50461101_76_dialog_content = "예!",
  ui_story_5046_50461102_1_dialog_content = "하... 하아...",
  ui_story_5046_50461102_2_dialog_content = "제 병사들을 모두 쓰러트릴 줄이야...",
  ui_story_5046_50461102_3_dialog_content = "체포에 저항했을 뿐만 아니라 백야성 경비병을 공격했으니,\n심판소의 법률에 의거해 어떤 처벌을 받게 될지는 알고 있겠죠?",
  ui_story_5046_50461102_4_dialog_content = "크리스틴, 말해 보세요.",
  ui_story_5046_50461102_5_dialog_content = "선생님... 조사에 협조해 주세요...",
  ui_story_5046_50461102_6_dialog_content = "조사로 선생님의 결백을 증명할 수 있다면, 다시 원래대로 돌아갈 수 있어요...",
  ui_story_5046_50461102_7_dialog_content = "알겠습니다.",
  ui_story_5046_50461102_8_dialog_content = "네?! 동의해 주시는 건가요?",
  ui_story_5046_50461102_9_dialog_content = "(방금까지 절대로 입을 안 열려고 했는데, 왜 갑자기 동의하는 거지?)",
  ui_story_5046_50461102_10_dialog_content = "얼른 펜던트를 내놔!",
  ui_story_5046_50461102_11_dialog_content = "그리고 어머니... 어머니를 죽인 죄의 대가를 치러야 해!",
  ui_story_5046_50461102_12_dialog_content = "죽여버릴 거야! 아버지와 어머니의 원수!",
  ui_story_5046_50461102_13_dialog_content = "진정해! 하티!",
  ui_story_5046_50461102_14_dialog_content = "사건은 크리스틴이 제대로 조사해 줄 거야...",
  ui_story_5046_50461102_15_dialog_content = "지금 여기서 폭력으로 해결하면, 이번엔 정말로 살인범이 되고 만다고!",
  ui_story_5046_50461102_16_dialog_content = "내가 아는 하티는... 부모님의 사랑을 받은 상냥하고 착한 아이야!",
  ui_story_5046_50461102_17_dialog_content = "너희 아버지도, 어머니도... 네가 이런 식으로 복수하는 걸 원치 않으실 거야!",
  ui_story_5046_50461102_18_dialog_content = "...정말... 아버지도, 어머니도... 그런 건 원하지 않으실까...?",
  ui_story_5046_50461102_19_dialog_content = "...좋아.",
  ui_story_5046_50461102_20_dialog_content = "펜던트는 드리죠. 대신 움브라톤으로 돌아갑시다.\n모두가 보는 앞에서 제 결백을 증명해야겠습니다.",
  ui_story_5046_50461102_21_dialog_content = "갑시다, 크리스틴.",
  ui_story_5046_50461102_22_dialog_content = "돌아가서 제 결백을 증명하면, 우리도 원래대로 돌아갈 수 있겠죠...",
  ui_story_5046_50461102_23_dialog_content = "네...",
  ui_story_5046_50461102_24_dialog_content = "움직이지 마세요. 움직이면 크리스틴의 목을 부러트릴 겁니다.",
  ui_story_5046_50461102_25_dialog_content = "선생님! 어, 어째서...",
  ui_story_5046_50461102_26_dialog_content = "뭐 하는 거야?! 빨리 크리스틴을 놔줘!",
  ui_story_5046_50461102_27_dialog_content = "크리스틴은 용의자 하티를 추적하던 중 격렬한 저항에 부딪혀서,\n안타깝게도 순직하고 만 겁니다.",
  ui_story_5046_50461102_28_dialog_content = "이런 미친 자식!",
  ui_story_5046_50461102_29_dialog_content = "크리스틴만 죽으면, 오늘 무슨 일이 일어났는지 아는 사람은 저뿐입니다.",
  ui_story_5046_50461102_30_dialog_content = "제가 심판소에 보고하고 나면, 하티는 극악무도한 방화 살인마가 되는 겁니다!",
  ui_story_5046_50461102_31_dialog_content = "그리고 아이테르! 당신도 공범이 되겠죠!",
  ui_story_5046_50461102_32_dialog_content = "그때가 되면 당신들이 무슨 말을 하든, 아무도 믿지 않을 겁니다.",
  ui_story_5046_50461102_33_dialog_content = "정말로 진실을 숨길 수 있다고 생각해?!",
  ui_story_5046_50461102_34_dialog_content = "고작 너 혼자서 거짓 증언을 꾸민다고 우릴 범인으로 만들 수 있을 것 같아?!",
  ui_story_5046_50461102_35_dialog_content = "진실? 진실이 무엇인지가 중요합니까?",
  ui_story_5046_50461102_36_dialog_content = "중요한 건 제가 무사히 백야성에서 계속해서 기사로 살아가는 겁니다...",
  ui_story_5046_50461102_37_dialog_content = "진실은... 당신들의 시체와 함께 영원히 땅속에 잠들겠죠!",
  ui_story_5046_50461102_38_dialog_content = "선생님... 그게 진심인가요?",
  ui_story_5046_50461102_39_dialog_content = "선생님은 항상 제게 정의를 지키고, 진상을 밝히라고 가르쳐 주셨잖아요,,,\n왜... 그런 선생님이 대체 왜 그런...",
  ui_story_5046_50461102_40_dialog_content = "크리스틴, 전 당신 마음속 소중한 존재겠죠?",
  ui_story_5046_50461102_41_dialog_content = "?!",
  ui_story_5046_50461102_42_dialog_content = "제가 그토록 소중하다면, 제 명예와 지위를 지키기 위해 죽는 것도 무척 기쁘겠죠?",
  ui_story_5046_50461102_43_dialog_content = "선생님... 대체 무슨 말씀을 하시는 건가요...",
  ui_story_5046_50461102_44_dialog_content = "크리스틴은 네가 목숨을 걸고 구해낸 사람이잖아! 그런 크리스틴을 죽이겠다는 거야?!",
  ui_story_5046_50461102_45_dialog_content = "(하티! 지금 이건 감응 능력으로 너한테 말하는 거야! 어떻게든 크리스틴을 구해야 해!)",
  ui_story_5046_50461102_46_dialog_content = "(PlayerName?)",
  ui_story_5046_50461102_47_dialog_content = "(내가 제나스의 주의를 끌 테니까, 넌 기회를 봐서 제나스를 덮쳐!)",
  ui_story_5046_50461102_48_dialog_content = "(알겠어.)",
  ui_story_5046_50461102_49_dialog_content = "구했다고요? 그 화재 말입니까?\n그렇다면 크리스틴은 제게 목숨을 빚졌으니, 지금이야말로 은혜에 보답할 차례네요.",
  ui_story_5046_50461102_50_dialog_content = "만약 내 추리가 틀렸고, 그때 네가 정말로 크리스틴을 구하기 위해서\n목숨을 걸고 불길 속에 뛰어든 거였다면...",
  ui_story_5046_50461102_51_dialog_content = "지금 어떻게 크리스틴을 해칠 생각을 할 수 있겠어?!",
  ui_story_5046_50461102_52_dialog_content = "그 말대로입니다.\n제가 목숨을 걸고 구해서 오랜 시간 보물처럼 가르치고 이끈 소녀를...",
  ui_story_5046_50461102_53_dialog_content = "제가 어떻게 해치겠습니까?",
  ui_story_5046_50461102_54_dialog_content = "선생님...",
  ui_story_5046_50461102_55_dialog_content = "하지만 크리스틴, 나의 아가씨.",
  ui_story_5046_50461102_56_dialog_content = "당신은 처음부터 끝까지, 결국 제 체스 말일 뿐입니다.",
  ui_story_5046_50461102_57_dialog_content = "그때 그 화재도 제 계획의 일부였거든요.",
  ui_story_5046_50461102_58_dialog_content = "네?!",
  ui_story_5046_50461102_59_dialog_content = "전 힘 있는 귀족에게 의지해 백야성으로 들어가려고 생각했었죠.\n그때 마침 이 계집애의 별장이 근처에 있더군요.",
  ui_story_5046_50461102_60_dialog_content = "그날 별장에 있는 건 힘없는 하인들뿐이라는 정보도 손에 넣었습니다.\n그래서 하인을 매수하고 불을 질렀지요.",
  ui_story_5046_50461102_61_dialog_content = "그리고 우연히 지나가던 척 목숨을 걸고 백야성 귀족 아가씨를 구해낸 겁니다.",
  ui_story_5046_50461102_62_dialog_content = "예상대로 가족은 제게 무척이나 고마워했고,\n전 꿈꿔온 백야성 생활을 순조롭게 시작할 수 있었습니다.",
  ui_story_5046_50461102_63_dialog_content = "모두 당신 덕분입니다, 아가씨... 아니, 크리스틴.",
  ui_story_5046_50461102_X63_dialog_content = "보세요. 당신을 구해내느라 얼굴에 화상까지 입었잖아요.",
  ui_story_5046_50461102_64_dialog_content = "다...당신 정말 끔찍한 사람이었군요! 절대 용서하지 않겠어요!",
  ui_story_5046_50461102_65_dialog_content = "백야성에 들어가려고 얼굴을 망가트리다니, 그럴 가치가 있어?",
  ui_story_5046_50461102_66_dialog_content = "아이테르, 당신이 권력의 매력을 알기나 합니까?",
  ui_story_5046_50461102_67_dialog_content = "권력으로는 돈을 얻을 수 있죠. 하지만 돈으로 꼭 권력을 살 수 있는 건 아닙니다.",
  ui_story_5046_50461102_68_dialog_content = "권력만 있으면 모든 걸 손에 넣을 수 있는 겁니다! 모든 이를 복종하게 만들 수 있죠!",
  ui_story_5046_50461102_69_dialog_content = "그렇지 않습니까? 크리스틴.",
  ui_story_5046_50461102_70_dialog_content = "당신은 태어날 때부터 백야성의 귀족이었습니다. 그런 기분은 정말 달콤했겠죠.",
  ui_story_5046_50461102_71_dialog_content = "왕관을 쓰려는 자는 반드시 그 무게를 견뎌야 해요...",
  ui_story_5046_50461102_72_dialog_content = "귀족은 그에 걸맞은 고귀한 인품과 덕성을 갖춰야 한다구요.",
  ui_story_5046_50461102_73_dialog_content = "귀족 신분을 이용해서 사리를 취하는 자는 귀족이라고 부를 수 없어요.",
  ui_story_5046_50461102_74_dialog_content = "하하하하하!",
  ui_story_5046_50461102_75_dialog_content = "크리스틴, 당신은 정말 우수한 제자로군요.",
  ui_story_5046_50461102_76_dialog_content = "정말 귀족들이 모두 당신처럼 고결하고 신성한 백합 같은 존재라고 생각하나요?",
  ui_story_5046_50461102_77_dialog_content = "뭐, 됐습니다. 말이 많았네요.",
  ui_story_5046_50461102_78_dialog_content = "음?! 잠깐, 하티는 어디 갔죠?!",
  ui_story_5046_50461102_79_dialog_content = "......",
  ui_story_5046_50461102_80_dialog_content = "(지금이야! 하티!)",
  ui_story_5046_50461102_81_dialog_content = "이야아압──!",
  ui_story_5046_50461102_82_dialog_content = "크윽!",
  ui_story_5046_50461102_83_dialog_content = "어느 틈에 뒤로...?!",
  ui_story_5046_50461102_84_dialog_content = "앗...",
  ui_story_5046_50461102_85_dialog_content = "크리스틴! 괜찮아?!",
  ui_story_5046_50461102_86_dialog_content = "부축해 줄게. 일어설 수 있겠어?",
  ui_story_5046_50461102_87_dialog_content = "PlayerName 씨... 훌쩍...",
  ui_story_5046_50461102_88_dialog_content = "이쪽으로 와.",
  ui_story_5046_50461102_89_dialog_content = "이제 인질은 없어. 순순히 펜던트를 내놔.",
  ui_story_5046_50461102_90_dialog_content = "아니면 나한테 좀 얻어맞아야 얌전해질 생각인가?",
  ui_story_5046_50461102_91_dialog_content = "좋습니다... 펜던트를 드리죠.",
  ui_story_5046_50461102_92_dialog_content = "펜던트를 원한다면...",
  ui_story_5046_50461102_93_dialog_content = "네 목숨부터 넘겨라!",
  ui_story_5046_50461102_94_dialog_content = "<color=#e8d9bb>챙──!</color>",
  ui_story_5046_50461102_95_dialog_content = "!",
  ui_story_5046_50461102_96_dialog_content = "크윽!",
  ui_story_5046_50461102_97_dialog_content = "펜던트를 건네는 척하며 기습을 해오다니...",
  ui_story_5046_50461102_98_dialog_content = "이제 우리 모두 무기는 없습니다. 누가 이길지는 알 수 없게 됐네요.",
  ui_story_5046_50461102_99_dialog_content = "크리스틴과 아이테르에겐 별다른 전투 능력도 없습니다. 그렇다면...",
  ui_story_5046_50461102_100_dialog_content = "이제 저와 당신만 남았습니다.",
  ui_story_5046_50461102_101_dialog_content = "우선 당신을 처리하고, 나머지 둘을 처리하면...",
  ui_story_5046_50461102_102_dialog_content = "하하하하하!",
  ui_story_5046_50461102_103_dialog_content = "......",
  ui_story_5046_50461102_104_dialog_content = "...내 검을?!",
  ui_story_5046_50461102_105_dialog_content = "흥, 됐습니다. 도끼도 나쁘진 않겠죠.",
  ui_story_5046_50461102_106_dialog_content = "피로 얼룩진 그 손으로 검을 잡을 자격은 없어.",
  ui_story_5046_50461102_X106_dialog_content = "검은 정의의 상징이야. 하지만 넌 사악해.",
  ui_story_5046_50461102_107_dialog_content = "진짜로 정의가 악을 이긴다고 생각하는 겁니까?",
  ui_story_5046_50461102_108_dialog_content = "물론이지.",
  ui_story_5046_50461102_109_dialog_content = "누가 이길지는 알 수 없어.",
  ui_story_5046_50461102_110_dialog_content = "<color=#e8d9bb>캉──!</color>",
  ui_story_5046_50461102_111_dialog_content = "죽어라!",
  ui_story_5046_50461102_112_dialog_content = "크아아!",
  ui_story_5046_50461102_113_dialog_content = "으아아아!",
  ui_story_5046_50461102_114_dialog_content = "<color=#e8d9bb>덜커덩──</color>",
  ui_story_5046_50461102_115_dialog_content = "......",
  ui_story_5046_50461102_116_dialog_content = "이제 네 칼이 네 목을 겨누고 있어.",
  ui_story_5046_50461102_117_dialog_content = "언제든 그 목을 베어버려서 어머니를 위해 복수할 수 있어.",
  ui_story_5046_50461102_118_dialog_content = "!",
  ui_story_5046_50461102_119_dialog_content = "하지만 그렇겐 안 해.",
  ui_story_5046_50461102_120_dialog_content = "그런 건 PlayerName 저 녀석이 원하지 않으니까.",
  ui_story_5046_50461102_121_dialog_content = "그리고 아버지도, 어머니도 내 손이 네놈 피로 더러워지는 건 원치 않으시겠지.",
  ui_story_5046_50461102_122_dialog_content = "거기, 크리스틴인지 뭔지 너.",
  ui_story_5046_50461102_123_dialog_content = "앗...",
  ui_story_5046_50461102_124_dialog_content = "언제까지 훌쩍대고 있을 거지?\n이놈을 너희한테 넘기기 전에 내가 펜던트부터 되찾아도 되겠어?",
  ui_story_5046_50461102_125_dialog_content = "펜던트? 무슨 소리죠? 강도질이라도 할 생각입니까?",
  ui_story_5046_50461102_126_dialog_content = "대체 왜 이 지경이 돼서도 죄를 인정하지 않는 거죠?!",
  ui_story_5046_50461102_127_dialog_content = "무슨 말인지 모르겠습니다만.",
  ui_story_5046_50461102_128_dialog_content = "선생님... 아니, 제나스.",
  ui_story_5046_50461102_129_dialog_content = "당신은 몇 년 전의 살인 사건 및 두 건의 방화 사건과 관계가 있어요.\n수사에 협조해 주세요.",
  ui_story_5046_50461102_130_dialog_content = "(크리스틴, 방금 전까지 울더니 금방 진정했네.)",
  ui_story_5046_50461102_131_dialog_content = "흥...",
  ui_story_5046_50461102_132_dialog_content = "변함없이 고집이 센 아가씨로군요.",
  ui_story_5046_50461102_133_dialog_content = "지금은 아무 말도 하고 싶지 않아요. 할 말이 있다면 심판소에 가서 하세요.",
  ui_story_5046_50461102_134_dialog_content = "사실 아까도 당신을 정말 죽일 생각은 없었습니다.\n당신은 직접 구해내고, 오랫동안 곁을 지킨 분입니다.",
  ui_story_5046_50461102_135_dialog_content = "제가 어떻게 당신을 해칠 수 있겠습니까.",
  ui_story_5046_50461102_136_dialog_content = "왜 아직도 절 속이려고 하시는 거죠?",
  ui_story_5046_50461102_137_dialog_content = "무엇이 사실이고, 무엇이 거짓인지, 정말 구분할 수 있습니까?",
  ui_story_5046_50461102_138_dialog_content = "이제 그만 좀 해요!",
  ui_story_5046_50461102_139_dialog_content = "당신 같은 사기꾼은 이제 절 가르칠 자격이 없어요!",
  ui_story_5046_50461102_140_dialog_content = "앞으로 누굴 믿고, 누굴 믿지 않을지는 저 스스로 판단할 수 있어요.",
  ui_story_5046_50461102_141_dialog_content = "전 이제 어린애가 아니에요.\n당신의 가르침을 필요로 하는 온실 속 소녀가 아니라구요.",
  ui_story_5046_50461102_142_dialog_content = "당신의 죄에 대해서는 심판소가 공정한 판결을 내릴 거예요.",
  ui_story_5046_50461102_143_dialog_content = "죄송해요, PlayerName 씨. 추태를 보였네요.",
  ui_story_5046_50461102_144_dialog_content = "전 이제 제나스를 백야성으로 연행하겠어요.\n판결이 나면 두 분께 알려드릴게요.",
  ui_story_5046_50461102_145_dialog_content = "펜던트.",
  ui_story_5046_50461102_146_dialog_content = "안심하세요. 받으면 바로 전달해 드릴 테니까요.",
  ui_story_5046_50461201_1_dialog_content = "<color=#e8d9bb>며칠 뒤</color>",
  ui_story_5046_50461201_2_dialog_content = "크리스틴!",
  ui_story_5046_50461201_3_dialog_content = "안녕하세요, PlayerName 씨.",
  ui_story_5046_50461201_4_dialog_content = "오랜만입니다, PlayerName 님.",
  ui_story_5046_50461201_5_dialog_content = "피트만 씨도 오셨군요!",
  ui_story_5046_50461201_6_dialog_content = "하티는 어디 있죠? 콜로서스를 보러 왔다고 들었는데요.",
  ui_story_5046_50461201_7_dialog_content = "크리스틴.",
  ui_story_5046_50461201_8_dialog_content = "자, 여기 펜던트요.",
  ui_story_5046_50461201_9_dialog_content = "어머니의 펜던트야...",
  ui_story_5046_50461201_10_dialog_content = "제나스의 조사와 심문은 제가 이어받게 되었습니다.",
  ui_story_5046_50461201_11_dialog_content = "PlayerName 씨 덕분에 <color=#FFB400>전의 그 사건</color>에 관한 단서를 찾을 수 있었습니다.",
  ui_story_5046_50461201_12_dialog_content = "아하하... 전 아무것도 안 했는데요.",
  ui_story_5046_50461201_13_dialog_content = "제가 인질이 된 게 이렇게 많은 일로 이어질 줄은 몰랐어요.",
  ui_story_5046_50461201_14_dialog_content = "크흠...",
  ui_story_5046_50461201_15_dialog_content = "참, 궁금한 게 몇 가지 있는데요...",
  ui_story_5046_50461201_16_option_content = "지난 두 달 동안 일어난 방화 사건의 진범은 누구였죠?",
  ui_story_5046_50461201_17_dialog_content = "조사 결과 고아원 준공식 리허설 때 발생했던 화재를 포함해서,\n최근 움브라톤에서 2개월간 벌어진 방화 사건은 모두 같은 연료를 사용했습니다.",
  ui_story_5046_50461201_18_dialog_content = "연료에 대해 알아봤더니 극소수의 가게에서만 구할 수 있는 물건이었습니다.",
  ui_story_5046_50461201_19_dialog_content = "그리고 가게 주인은 두 달 전 제나스가 대량으로 그 연료를 구입했다고 증언했습니다.",
  ui_story_5046_50461201_20_dialog_content = "제나스도 방화 혐의에 대해서는 인정했습니다. 목적은 입막음이었지요.",
  ui_story_5046_50461201_21_dialog_content = "근데 제나스가 왜 그 사람들의 입을 막아야 했던 거죠?",
  ui_story_5046_50461201_22_dialog_content = "그것도 <color=#FFB400>전의 그 사건</color>과 관계가 있었습니다.",
  ui_story_5046_50461201_23_dialog_content = "당시 하멜 씨를 포함한 다섯 명은 고아원을 은신처로 삼고,\n아이들을 실험체로 제공하고 있었습니다.",
  ui_story_5046_50461201_24_dialog_content = "그러다 고아원에 불이 났고, 제나스와 하멜 씨를 제외한\n나머지 세 사람은 형편이 어려워졌습니다.",
  ui_story_5046_50461201_25_dialog_content = "그래서 세 사람은 과거의 일을 빌미로 제나스를 협박했고,\n제나스는 돈을 주고 입막음을 할 수밖에 없었습니다.",
  ui_story_5046_50461201_26_dialog_content = "하지만 세 사람의 요구는 갈수록 심해졌고...",
  ui_story_5046_50461201_27_dialog_content = "결국 영원히 입을 막아버리기로 한 거군요.",
  ui_story_5046_50461201_28_dialog_content = "그렇습니다.",
  ui_story_5046_50461201_29_dialog_content = "그럼 하멜 씨는 누구한테 살해당한 거죠?",
  ui_story_5046_50461201_30_dialog_content = "제나스는 자신이 세 명의 옛 고아원 직원을 방화로 살해한 것을 인정했습니다.",
  ui_story_5046_50461201_31_dialog_content = "당시 고아원에서 일했고, 사건과 관련된 인물은 제나스를 포함해 다섯 명입니다.",
  ui_story_5046_50461201_32_dialog_content = "그럼 하멜 씨도 제나스가 죽였다는 건가요?",
  ui_story_5046_50461201_33_dialog_content = "상당한 혐의점이 있습니다만, 현재로서는 증거가 없고, 본인도 인정하지 않고 있습니다.",
  ui_story_5046_50461201_34_dialog_content = "그렇게 많은 살인에 연루돼 있었다니...",
  ui_story_5046_50461201_35_dialog_content = "(크리스틴... 왠지 많이 안 좋아 보이네...)",
  ui_story_5046_50461201_36_dialog_content = "크리스틴, 괜찮아?",
  ui_story_5046_50461201_37_dialog_content = "PlayerName 씨는 제가 그렇게 약한 사람이라고 생각하시나요?",
  ui_story_5046_50461201_38_dialog_content = "아니, 그런 뜻이 아니었어! 그냥...",
  ui_story_5046_50461201_39_dialog_content = "전 괜찮아요.",
  ui_story_5046_50461201_40_dialog_content = "그날 PlayerName 씨가 해주신 이야기, 잘 기억하고 있어요.",
  ui_story_5046_50461201_41_dialog_content = "제가 좋은 심판관이 될 수 있다고 하셨잖아요.",
  ui_story_5046_50461201_42_dialog_content = "이렇게나 많은 분들이 절 격려하고 응원해 주고 있으니까,\n저도 어느 한 사람 때문에 낙담하고 있진 않을 거예요.",
  ui_story_5046_50461201_43_dialog_content = "비록 아직은 갈 길이 멀지만, 노력해서 꼭 목표를 달성할 거예요.",
  ui_story_5046_50461201_44_dialog_content = "아무튼 전 「대단」하니까요! 그렇죠? PlayerName 씨?",
  ui_story_5046_50461201_45_dialog_content = "응! 크리스틴 너라면 분명히 할 수 있을 거야!",
  ui_story_5046_50461201_46_dialog_content = "동감이야.",
  ui_story_5046_50461201_47_dialog_content = "동의합니다.",
  ui_story_5046_50461201_48_dialog_content = "으앗──! 피트만 선배님 아직 계신 것도 잊고 있었네요...",
  ui_story_5046_50461201_49_dialog_content = "크흠, 그럼 펜던트도 드렸으니까, 저흰 이만 가 볼게요.",
  ui_story_5046_50461201_50_dialog_content = "실례했습니다.",
  ui_story_5046_50461201_51_dialog_content = "......",
  ui_story_5046_50461201_52_dialog_content = "하티, 긴장돼?",
  ui_story_5046_50461201_53_dialog_content = "응.",
  ui_story_5046_50461201_54_dialog_content = "이 두 펜던트는 원래 하나였고, 어머니는 절반을 나한테 주셨어.",
  ui_story_5046_50461201_55_dialog_content = "어머니가 그러셨어. 두 펜던트가 합쳐지면 우리 가족은 영원히 함께라고...",
  ui_story_5046_50461201_56_dialog_content = "하지만 어머니는 이제 안 계셔... 흑... 흑흑...",
  ui_story_5046_50461201_57_dialog_content = "엄마... 흑흑...",
  ui_story_5046_50461201_58_dialog_content = "착하지, 울지 마...",
  ui_story_5046_50461201_59_dialog_content = "(착하지 우리 하티, 그만 울자, 뚝.)",
  ui_story_5046_50461201_60_dialog_content = "(엄마가 노래 불러줄게. 하티. 안심하고 자렴...)",
  ui_story_5046_50461201_61_dialog_content = "(라라라~♪ 라라라라~♪)",
  ui_story_5046_50461201_62_dialog_content = "(하티, 네가 푹 자는 모습을 보면, 엄마는 지금 이 순간이 영원히 멈췄으면 좋겠어.)",
  ui_story_5046_50461201_63_dialog_content = "(하지만 네가 무럭무럭 자란 모습도 보고 싶어. 분명히 펜리르를 꼭 닮았겠지.)",
  ui_story_5046_50461201_64_dialog_content = "(네가 갓 태어났을 땐 복슬복슬하고 그렇게 작았는데,\n이젠 내 무릎까지 키가 닿게 됐구나.)",
  ui_story_5046_50461201_65_dialog_content = "(이렇게 컸는데도 넌 여전히 엄마가 안아주지 않으면 잠도 안 자고,\n아침도 엄마가 안아서 데려와야 겨우 먹는 거니...)",
  ui_story_5046_50461201_66_dialog_content = "(엄마는 이제 무거워서 널 안고 걸을 수도 없는걸.)",
  ui_story_5046_50461201_67_dialog_content = "(하티. 엄마가 할머니가 되면, 그땐 네가 엄마를 안고 침대까지 데려다줘...)",
  ui_story_5046_50461201_68_dialog_content = "(하티... 아직도 너한테 하고 싶은 말이 정말 많단다...)",
  ui_story_5046_50461201_69_dialog_content = "(널 계속 보면서, 네 곁에서 네가 자라는 걸 보고 싶어...)",
  ui_story_5046_50461201_70_dialog_content = "(......)",
  ui_story_5046_50461201_71_dialog_content = "(......)",
  ui_story_5046_50461201_72_dialog_content = "(......)",
  ui_story_5046_50461201_73_dialog_content = "......",
  ui_story_5046_50461201_74_dialog_content = "난 이제 네가 무섭지 않아. 그리고 이 힘도... 이제 무섭지 않아.",
  ui_story_5046_50461201_75_dialog_content = "난 이제 자신을 완전히 받아들였어.",
  ui_story_5046_50461201_76_dialog_content = "그동안 힘을 두려워하고 자신을 싫어했던 하티도...",
  ui_story_5046_50461201_77_dialog_content = "불꽃으로 소중한 사람을 지키려는 하티도...",
  ui_story_5046_50461201_78_dialog_content = "모두 다 나야.",
  ui_story_5046_50461201_79_dialog_content = "(이미... 자신을 받아들일 준비가 된 건가...)",
  ui_story_5046_50461201_80_dialog_content = "준비됐어.",
  ui_story_5046_50461202_1_dialog_content = "내가... 이겼어?",
  ui_story_5046_50461202_2_dialog_content = "넌...?",
  ui_story_5046_50461202_3_dialog_content = "(넌 이미 자신을 완전히 받아들였다.)",
  ui_story_5046_50461202_4_dialog_content = "(너는 너 자신과 화해한 거다.)",
  ui_story_5046_50461202_5_dialog_content = "(앞으로 넌 이 힘을 잘 쓸 수 있을 거다. 정말 기쁘구나.)",
  ui_story_5046_50461202_6_dialog_content = "(난 이제 가야 한다.)",
  ui_story_5046_50461202_7_dialog_content = "불꽃의 힘이 느껴져...",
  ui_story_5046_50461202_8_dialog_content = "힘이 끝없이 내 몸속으로 스며들고 있어...",
  ui_story_5046_50461202_9_dialog_content = "<color=#e8d9bb>화르륵!</color>",
  ui_story_5046_50461202_10_dialog_content = "불꽃... 내 마음에서 생겨난 불꽃...",
  ui_story_5046_50461202_11_dialog_content = "따뜻해.",
  ui_story_5046_50461202_12_dialog_content = "PlayerName?",
  ui_story_5046_50461202_13_dialog_content = "일어났어? 너 방금 내가 노래 흥얼거리는 사이에 잠들었거든.",
  ui_story_5046_50461202_14_dialog_content = "아주 푹 자길래 안 깨웠어.",
  ui_story_5046_50461202_15_dialog_content = "어렸을 때 꿈을 꿨어. 내 실수로 물건을 태워서 어머니한테 혼나서 울었어.",
  ui_story_5046_50461202_16_dialog_content = "어머니는 날 안고 자장가를 부르면서 재워주었어.",
  ui_story_5046_50461202_17_dialog_content = "그리고 잠든 뒤에...",
  ui_story_5046_50461202_18_dialog_content = "마음속 어둠을 만났어.",
  ui_story_5046_50461202_19_dialog_content = "그래서 녀석한테 말했어. 이제 더는 네가 무섭지 않다고.",
  ui_story_5046_50461202_20_dialog_content = "그리고?",
  ui_story_5046_50461202_21_dialog_content = "내가... 이겼어.",
  ui_story_5046_50461202_22_dialog_content = "이제 난 불꽃을 두려워하지 않아. 왜냐하면 이 불꽃은 날 따뜻하게 감싸주니까.",
  ui_story_5046_50461202_23_dialog_content = "아버지랑 어머니가 안아주는 것처럼.",
  ui_story_5046_50461202_24_dialog_content = "정말 다정한 꿈이었겠네.",
  ui_story_5046_50461202_25_dialog_content = "난 무엇이든 맞설 용기가 생겼어. 그건 아버지와 어머니...",
  ui_story_5046_50461202_26_dialog_content = "그리고 PlayerName 네가 준 용기야.",
  ui_story_5046_50461202_27_dialog_content = "지금까지 계속 함께해 줘서 고마워.",
  ui_story_5046_50461202_28_dialog_content = "에이, 뭘! 우린 친구잖아!",
  ui_story_5046_50461202_29_dialog_content = "이제 펜던트를 맞춰볼 거야. PlayerName, 같이 있어 줄래?",
  ui_story_5046_50461202_30_dialog_content = "응! 같이 보자!",
  ui_story_5046_50461202_31_dialog_content = "<color=#e8d9bb>딸그락──</color>",
  ui_story_5046_50461202_32_dialog_content = "어? 펜던트를 합치니까 밑에서 뭐가 나온 것 같아...",
  ui_story_5046_50461202_33_dialog_content = "<color=#e8d9bb>휘릭──</color>",
  ui_story_5046_50461202_34_dialog_content = "이, 이건...",
  ui_story_5046_50461202_35_dialog_content = "사진이 몇 장 있네...",
  ui_story_5046_50461202_36_dialog_content = "이건... 내가 어렸을 때 그린 가족 그림이야.",
  ui_story_5046_50461202_37_dialog_content = "어머니가 펜던트 안에 넣어 주신 줄은 몰랐어.",
  ui_story_5046_50461202_38_dialog_content = "너 어렸을 때 사진도 있어!",
  ui_story_5046_50461202_39_dialog_content = "그리고 두 장...",
  ui_story_5046_50461202_40_dialog_content = "이쪽은 분명히 하티의 어머니겠네. 근데 이쪽은...",
  ui_story_5046_50461202_41_dialog_content = "아버지야...",
  ui_story_5046_50461202_42_dialog_content = "어? 이분이 하티네 아버지라고?",
  ui_story_5046_50461202_43_dialog_content = "근데 사진 속 배경은 실험실 같은데...?",
  ui_story_5046_50461202_44_dialog_content = "난...",
  ui_story_5046_50461202_45_dialog_content = "아버지를 만난 적이 없어.",
  ui_story_5046_50461202_46_dialog_content = "하지만 이 사진을 보니까, 이 사람이 바로 아버지인 것 같아...",
  ui_story_5046_50461202_47_dialog_content = "「두 펜던트가 합쳐지면 우리 가족은 영원히 함께야...」",
  ui_story_5046_50461202_48_dialog_content = "이제 우리 가족은 영원히 함께야.",
  ui_story_5046_50461202_49_dialog_content = "<color=#e8d9bb>움브라톤의 어딘가</color>",
  ui_story_5046_50461202_50_dialog_content = "편지를 제나스에게 건네고 뒤를 쫓았습니다.",
  ui_story_5046_50461202_51_dialog_content = "여러분은 계속해서 이 일대를 수색하십시오. 어느 한 곳도 빠트리지 마십시오.",
  ui_story_5046_50461202_52_dialog_content = "예!",
  ui_story_5046_50461202_53_dialog_content = "......",
  ui_story_5046_50461202_54_dialog_content = "(이 방향은... 고아원으로 가는 건가?)",
  ui_story_5046_50461202_55_dialog_content = "오랜만이로군요.",
  ui_story_5046_50461202_56_dialog_content = "너였나.",
  ui_story_5046_50461202_57_dialog_content = "(하멜? 설마 섀도우마스터가 필요로 하는 물건이 저 사람 손에 있는 건가?)",
  ui_story_5046_50461202_58_dialog_content = "다시 만났는데 기쁘지 않습니까?",
  ui_story_5046_50461202_59_dialog_content = "날 만나러 온 게 아니라 그걸 찾으러 온 거겠지.",
  ui_story_5046_50461202_60_dialog_content = "서운하군요. 오늘은 좋은 소식을 가져왔습니다만.",
  ui_story_5046_50461202_61_dialog_content = "그 녀석이 널 보자고 하는 거랑 내가 무슨 상관이지?",
  ui_story_5046_50461202_62_dialog_content = "안드레와 다른 두 사람도 죽었으니, 이제 곧 저와 당신 차례도 올 겁니다.",
  ui_story_5046_50461202_63_dialog_content = "앉아서 기다리고 있느니, 우리가 먼저 손을 쓰는 건 어떻습니까?",
  ui_story_5046_50461202_64_dialog_content = "(하멜의 시선이 아까부터 계속 저쪽으로 향하고 있어.)",
  ui_story_5046_50461202_65_dialog_content = "왜 제가 직접 나서지 않는지 궁금하시겠죠.",
  ui_story_5046_50461202_66_dialog_content = "이 편지는 절 지목하고 있습니다. 만약 제가 그 여자와 어떤 관계가 있는지\n다른 사람이 알게 되고, 그걸 토대로 조사가 확대된다면 일이 복잡해질 겁니다.",
  ui_story_5046_50461202_67_dialog_content = "그렇게 되면 저도 당신에게 편의를 제공할 수 없고,\n당신까지 조사의 대상이 될 수도 있겠죠.",
  ui_story_5046_50461202_68_dialog_content = "지금 날 협박하는 거냐...",
  ui_story_5046_50461202_69_dialog_content = "서로 이익이 되는 이야기를 할 뿐입니다.\n자, 이게 약속 장소의 위치입니다.",
  ui_story_5046_50461202_70_dialog_content = "좋아, 귀찮은 일은 내가 처리해 주지. 대신 데려갈 부하들을 좀 붙여줘야겠어.",
  ui_story_5046_50461202_71_dialog_content = "제나스가 떠나고, 하멜이 자는 틈에 수색해서 그 물건을 발견할 수 있었습니다.",
  ui_story_5046_50461202_72_dialog_content = "거기엔 거래 날짜와 가격, 그리고 구매자의 정보가 적혀 있었습니다.",
  ui_story_5046_50461202_73_dialog_content = "잘했다.",
  ui_story_5046_50461202_74_dialog_content = "오래전 움브라톤은 주인 없는 혼란의 장이었지.\n백야성은 이곳을 놈들의 죄악을 덮는 곳으로 쓰고 있었다.",
  ui_story_5046_50461202_75_dialog_content = "이제 내가 움브라톤을 지키는 이상, 이 거리가 과거의 모습으로 돌아가지는 않을 것이다.",
  ui_story_5046_50461202_76_dialog_content = "그림자는 모든 비밀을 알고 있다.",
  ui_story_5046_50461202_77_dialog_content = "네, 섀도우마스터.",
  ui_story_5046_50461202_78_dialog_content = "며칠간 고생했다.",
  ui_story_5046_50461202_79_dialog_content = "<color=#e8d9bb>백야성 감옥</color>",
  ui_story_5046_50461202_80_dialog_content = "......",
  ui_story_5046_50461202_81_dialog_content = "오셨군요.",
  ui_story_5046_50461202_82_dialog_content = "이런 칙칙하고 음산한 곳은 아가씨가 오실 곳이 못 됩니다.",
  ui_story_5046_50461202_83_dialog_content = "오늘은 당신, 그리고 제 과거와 작별하고 싶어서 왔어요.",
  ui_story_5046_50461202_84_dialog_content = "지금까지 전 줄곧 당신 뜻대로 해왔어요.\n사고방식도, 행실도 모두 당신이 원하는 방향대로였죠.",
  ui_story_5046_50461202_85_dialog_content = "마치 당신의 인형처럼 말이에요.",
  ui_story_5046_50461202_86_dialog_content = "아가씨, 전 한 번도 당신에게 무엇을 하고, 무엇을 생각하라고 강요한 적은 없습니다만.",
  ui_story_5046_50461202_87_dialog_content = "지금까지 쭉 그렇게 만들어 놓고도 아무 관계도 없다는 그 태도... 정말 역겹네요!",
  ui_story_5046_50461202_88_dialog_content = "당신은 구제할 수 없는 쓰레기예요!",
  ui_story_5046_50461202_89_dialog_content = "......",
  ui_story_5046_50461202_90_dialog_content = "미안해요. 추태를 보였네요.",
  ui_story_5046_50461202_91_dialog_content = "펜던트.",
  ui_story_5046_50461202_92_dialog_content = "그 펜던트 안에는 대체 뭐가 들어 있었습니까?",
  ui_story_5046_50461202_93_dialog_content = "물어보고 싶은 건 그것뿐인가요?",
  ui_story_5046_50461202_94_dialog_content = "......",
  ui_story_5046_50461202_95_dialog_content = "그 펜던트를 위해 전 수많은 대가를 치렀습니다.",
  ui_story_5046_50461202_96_dialog_content = "그 안에... 제가 생각한 물건이 있었는지 알고 싶습니다.",
  ui_story_5046_50461202_97_dialog_content = "안에는 하티의 가족사진이 들어 있었어요.",
  ui_story_5046_50461202_98_dialog_content = "가족사진? 그게 전부입니까?",
  ui_story_5046_50461202_99_dialog_content = "네, 그것뿐이었어요.",
  ui_story_5046_50461202_100_dialog_content = "...하하하하하하!",
  ui_story_5046_50461202_101_dialog_content = "생각도 못 했군요...",
  ui_story_5046_50461202_102_dialog_content = "끝내 맞이한 게 이런 결말이라니...",
  ui_story_5046_50461202_103_dialog_content = "더 할 말이 없다면...",
  ui_story_5046_50461202_104_dialog_content = "전 이만 실례할게요.",
  ui_story_5046_50461202_105_dialog_content = "......",
  ui_story_5046_50461202_106_dialog_content = "당신을 만나는 건 이번이 마지막이에요.",
  ui_story_5046_50461202_107_dialog_content = "안녕히 계세요, 선생님.",
  ui_story_5046_50461202_108_dialog_content = "(안녕, 나의 과거...)",
  ui_story_5046_50461202_109_dialog_content = "<color=#e8d9bb>움브라톤 고아원 준공식 당일</color>",
  ui_story_5046_50461202_110_dialog_content = "이 고아원은 움브라톤의 수많은 자선가들의 피땀이 모여 이루어진 것입니다.\n이 자리를 빌어 도움을 주신 모든 분들께 감사의 말씀을 드립니다!",
  ui_story_5046_50461202_111_dialog_content = "그럼 이제, 움브라톤 고아원이 준공되었음을 선포합니다!",
  ui_story_5046_50461202_112_dialog_content = "우와아──!",
  ui_story_5046_50461202_113_dialog_content = "무사히 완공돼서 정말 다행이에요!",
  ui_story_5046_50461202_114_dialog_content = "고아원이 잘 운영되길 바랄게. 옛날 같은 일은 다시는 일어나지 말아야 해.",
  ui_story_5046_50461202_115_dialog_content = "고아원은 움브라톤의 섀도우마스터가 관리하실 겁니다. 안심하셔도 좋아요.",
  ui_story_5046_50461202_116_dialog_content = "그림?!",
  ui_story_5046_50461202_117_dialog_content = "제나스가 잡힌 날 하티랑 같이 찾아갔는데 바에 없길래...",
  ui_story_5046_50461202_118_dialog_content = "일이 좀 있어서 외출했거든요.",
  ui_story_5046_50461202_119_dialog_content = "참, 하티는요?",
  ui_story_5046_50461202_120_dialog_content = "하티는...",
  ui_story_5046_50461202_121_dialog_content = "이어서 고아원을 화재에서 구한 영웅── 하티를 박수로 맞이해 주세요!",
  ui_story_5046_50461202_122_dialog_content = "......",
  ui_story_5046_50461202_123_dialog_content = "하티는 최근 두 달간 움브라톤에서 일어난 복수의 화재 현장에서\n용감하게 나서서 사람들을 구조했답니다.",
  ui_story_5046_50461202_124_dialog_content = "며칠 전 준공식 리허설 현장에서도 화재로 한 소녀가 불 속에 갇혔었죠...",
  ui_story_5046_50461202_125_dialog_content = "하티는 위험을 무릅쓰고 불길 속으로 뛰어들어 그 소녀를 구출했습니다...",
  ui_story_5046_50461202_126_dialog_content = "뭐야, 방화범이 아니었던 거구나...",
  ui_story_5046_50461202_127_dialog_content = "현장에 나타난 건 사람을 구하려고 그런 거였어?",
  ui_story_5046_50461202_128_dialog_content = "정말 용감하네요. 꼭 슈퍼히어로 같아요...",
  ui_story_5046_50461202_129_dialog_content = "역시 베델 씨가 신경을 많이 쓰셨네요.\n이걸로 움브라톤의 그 누구도 하티를 방화범이라 여기지 않을 거예요.",
  ui_story_5046_50461202_130_dialog_content = "그러게. 나였으면 아무리 생각해도 이런 아이디어는 못 냈을 거야.",
  ui_story_5046_50461202_131_dialog_content = "후훗... PlayerName 씨도 자신만의 장점이 있는걸요.\n그 누구도 완벽한 사람은 없으니까요.",
  ui_story_5046_50461202_132_dialog_content = "귀찮아.",
  ui_story_5046_50461202_133_dialog_content = "뭐야... 벌써 내려왔어?",
  ui_story_5046_50461202_134_dialog_content = "위에 서 있으니까 온몸의 털이 솟구치는 것 같다고.",
  ui_story_5046_50461202_135_dialog_content = "익숙해지면 괜찮을 거예요. 아직 바깥세상을 접한 지 얼마 안 됐잖아요.\n앞으로도 이것저것 배워야 해요.",
  ui_story_5046_50461202_136_dialog_content = "으...",
  ui_story_5046_50461202_137_dialog_content = "하티, 이제 어떻게 할 생각이죠?",
  ui_story_5046_50461202_138_dialog_content = "......",
  ui_story_5046_50461202_139_dialog_content = "아직 모르겠어.",
  ui_story_5046_50461202_140_dialog_content = "지금까진 어머니와의 기억을 떠올리는 게 목표였어.",
  ui_story_5046_50461202_141_dialog_content = "하지만 그 목표는 이미 달성했어...",
  ui_story_5046_50461202_142_dialog_content = "이제 또 뭘 해야 할지 모르겠어.",
  ui_story_5046_50461202_143_dialog_content = "그거면 돼. 인생은 그렇게 하나하나 목표를 이루면서 나아가는 거니까!",
  ui_story_5046_50461202_144_dialog_content = "그리고 다음 목표를 찾을 때까지 휴식 시간도 필요해.",
  ui_story_5046_50461202_145_dialog_content = "첫 번째 목표를 이루기 위해 하티 넌 이미 전력을 다했으니까.",
  ui_story_5046_50461202_146_dialog_content = "다음 목표...?",
  ui_story_5046_50461202_147_dialog_content = "그게 뭔지 모르겠어.",
  ui_story_5046_50461202_148_dialog_content = "언젠가 꼭 찾을 수 있을 거야.",
  ui_story_5046_50461202_149_dialog_content = "네 인생은 이제 막 시작됐잖아!",
  ui_story_5046_50461202_150_dialog_content = "전에 내가 말한 것처럼 이 세상엔 네가 발견해 주길 기다리는 신기한 게 아주 많아!",
  ui_story_5046_50461202_151_dialog_content = "그러니까 다음 목표를 찾을 때까지는 푹 쉬어 둬!",
  ui_story_5046_50461202_152_dialog_content = "응.",
  ui_story_5046_50461202_153_dialog_content = "고마워, PlayerName.",
  ui_story_5046_50461202_154_dialog_content = "그것보다 난 앞으로 네가 또 갑자기 머리가 아플까 그게 걱정이라고...",
  ui_story_5046_50461202_155_dialog_content = "너랑 비슷하게 생긴 그 개가 또 너한테 무슨 말을 걸진 않을까...",
  ui_story_5046_50461202_156_dialog_content = "이제 걱정할 필요 없어.",
  ui_story_5046_50461202_157_dialog_content = "우린 화해했거든.",
  ui_story_5046_50461202_158_dialog_content = "이제 우린 하나야.",
  ui_story_5046_50461202_159_dialog_content = "으아앗──!",
  ui_story_5046_50461202_160_dialog_content = "너... 이제 그 개랑 똑같이 생겼잖아!",
  ui_story_5046_50461202_161_dialog_content = "응.",
  ui_story_5046_50461202_162_dialog_content = "무서워할 거 없어.",
  ui_story_5046_50461202_163_dialog_content = "난 이제 이 힘을 제대로 제어할 수 있으니까...",
  ui_story_5046_50461202_164_dialog_content = "불꽃의 힘을 말이야.",
  ui_story_5046_50461202_165_dialog_content = "오빠!",
  ui_story_5046_50461202_166_dialog_content = "넌...",
  ui_story_5046_50461202_167_dialog_content = "...그때 그 여자애?",
  ui_story_5046_50461202_168_dialog_content = "우릴 구해준 강아지한테 주려고 화관을 만들었어!",
  ui_story_5046_50461202_169_dialog_content = "강아지 어디 있는지 알아?",
  ui_story_5046_50461202_170_dialog_content = "강아지는...",
  ui_story_5046_50461202_171_dialog_content = "여기 있어.",
  ui_story_5046_50461202_172_dialog_content = "으아아앗──!",
  ui_story_5046_50461202_173_dialog_content = "내 모습이 그렇게 무서워?",
  ui_story_5046_50461202_174_dialog_content = "커다란 강아지야!",
  ui_story_5046_50461202_175_dialog_content = "멋있어!",
  ui_story_5046_50461202_176_dialog_content = "......",
  ui_story_5046_50461202_177_dialog_content = "진짜 그날 나 구해준 강아지 맞아?",
  ui_story_5046_50461202_178_dialog_content = "그래.",
  ui_story_5046_50461202_179_dialog_content = "아! 알겠어!",
